vipLevel = function vipLevel(){return Math.min(5,Math.floor(s.crafted/250))};
paintBattle = function paintBattle(){const hp=dungeonRun?dungeonRun.hp:s.enemyHp,mx=dungeonRun?dungeonRun.maxHp:maxHp();$('stage').textContent=dungeonRun?['황금 광산','고대 무기고','마법 도서관'][dungeonRun.i]:'STAGE '+stageText();$('region').textContent=dungeonRun?`${dungeonRun.n}단계 · ${Math.ceil(dungeonRun.time)}초 남음`:['폐허의 숲','잿빛 협곡','고대의 성채','얼어붙은 폐허','심연의 성역','천공의 회랑'][Math.floor((s.stage-1)/50)%6];$('enemy').textContent=dungeonRun?'던전 수호자':s.stage%10===0?'광폭한 숲의 지배자':'숲의 멧돼지 무리';$('enemybar').style.width=Math.max(0,Math.min(100,100*hp/mx))+'%';$('enemytext').textContent=compact(hp)+' / '+compact(mx);$('mobActor').classList.toggle('boss-form',s.stage%10===0||!!dungeonRun);$('route').innerHTML=[0,1,2,3].map(i=>`<span class="${((s.stage-1)%10)>=i*2?'filled':''}"></span>`).join('')+`<b title="보스 스테이지"><ui-mark data-shape=boss aria-hidden=true></ui-mark></b>`;document.querySelector('.landscape').style.filter=dungeonRun?['sepia(.25) saturate(1.2)','hue-rotate(15deg)','hue-rotate(35deg)'][dungeonRun.i]:['none','sepia(.15)','hue-rotate(10deg)','saturate(.7)','hue-rotate(25deg)','brightness(1.1)'][Math.floor((s.stage-1)/50)%6]};
paint = function paint(){if(!s)return;for(let k of ['gold','gems','ore'])$(k).textContent=compact(s[k]);$('energy').textContent=s.tickets.reduce((a,b)=>a+b,0)+'/6';$('level').textContent='Lv.'+s.level+' 성운기사';$('power').textContent='전투력 '+ratingText(combatPower());$('xpFill').style.width=Math.min(100,s.xp/(playerXpGoal())*100)+'%';$('vipLabel').textContent='VIP '+vipLevel();$('auto').classList.toggle('off',!s.auto);$('auto').innerHTML=`<i>${s.auto?'<ui-mark data-shape=check aria-hidden=true></ui-mark>':'<ui-mark data-shape=minus aria-hidden=true></ui-mark>'}</i>자동 전투`;$('autoBoss').classList.toggle('off',!s.autoBoss);$('autoBoss').innerHTML=`<i>${s.autoBoss?'<ui-mark data-shape=check aria-hidden=true></ui-mark>':'<ui-mark data-shape=minus aria-hidden=true></ui-mark>'}</i>보스 자동 도전`;$('battle').classList.toggle('off',!s.auto);$('speed').textContent='×'+s.speed;$('crafts').textContent='('+num(s.crafted)+'회)';$('mailDot').hidden=s.mailClaimed;document.body.classList.toggle('low-motion',!s.effects);$('heroActor').style.filter=s.wear?`hue-rotate(${[0,185,0,240,40,295,270,140][s.wear]}deg) drop-shadow(0 7px 5px #1119)`:'drop-shadow(0 7px 5px #1119)';paintBattle();paintSkillButtons();paintDashboard();if(view)render();hydrateArt()};
paintSkillButtons = function paintSkillButtons(){$('skillbuttons').innerHTML=s.slots.map((k,i)=>`<button class="${k<0?'locked':''}" onclick="cast(${i})" aria-label="${k<0?'스킬 장착':SK[k][0]}" title="${k<0?'스킬 장착':SK[k][0]}">${art('cast'+i)}<small id="cool${i}" style="display:${cooldowns[i]>0?'grid':'none'}">${k<0?'+':Math.ceil(cooldowns[i])}</small><em>${i+1}</em></button>`).join('')};
toggleAuto = function toggleAuto(){s.auto=!s.auto;paint();save()};
toggleBoss = function toggleBoss(){s.autoBoss=!s.autoBoss;paint();save()};
travel = function travel(d){if(dungeonRun){notice('던전 전투 중에는 이동할 수 없습니다');return}const target=s.stage+d;if(target<1||target>s.maxStage){notice('먼저 현재 스테이지를 클리어하세요');return}s.stage=target;s.enemyHp=maxHp();paint();save()};
damageText = function damageText(d,crit=false,index=0){let el=document.createElement('div');el.className='hit'+(crit?' critical':'');el.textContent='−'+compact(d);el.style.left=(54+index*12+Math.random()*5)+'%';el.style.top=(35+index*11)+'%';$('fx').append(el);setTimeout(()=>el.remove(),1000)};
visualStrike = function visualStrike(){const h=$('heroActor'),mobs=[$('mobActor'),$('mobTwo'),$('mobThree')];strikeTimeouts.forEach(clearTimeout);strikeTimeouts=[];h.classList.remove('attacking');void h.offsetWidth;h.classList.add('attacking');[0,1,2,3,0].forEach((frame,i)=>strikeTimeouts.push(setTimeout(()=>{h.style.backgroundPosition=(frame*100/3)+'% 0'},i*90)));mobs.forEach((m,i)=>{m.classList.remove('damaged');void m.offsetWidth;m.classList.add('damaged');strikeTimeouts.push(setTimeout(()=>m.classList.remove('damaged'),330+i*35))});emitEffect('slash',.61,.64);playSound('hit')};
hit = function hit(){if(!s)return;visualStrike();const crit=Math.random()<.15,damage=Math.max(1,Math.floor(power()*(.75+Math.random()*.5)*(crit?1.75:1)));applyDamage(damage,crit);if(Math.random()<.45)damageText(Math.round(damage*.85),false,1);paintBattle()};
applyDamage = function applyDamage(d,crit=false){damageText(d,crit);if(dungeonRun){dungeonRun.hp-=d;if(dungeonRun.hp<=0)finishDungeon(true);return}s.enemyHp-=d;if(s.enemyHp<=0){const defeated=s.stage;s.kills++;s.daily.kills=(s.daily.kills||0)+1;s.gold+=goldGain();gainXP(4+Math.floor(s.stage/4));if(Math.random()<.45)s.ore++;if(s.stage%10===0){s.ore+=5;s.bossKills=(s.bossKills||0)+1;banner('BOSS CLEAR');playSound('reward')}const next=s.stage+1;if(next%10!==0||s.autoBoss)s.stage=Math.min(300,next);s.maxStage=Math.max(s.maxStage,s.stage);if(defeated%5===0)s.stones+=2;s.enemyHp=maxHp();if(!s.autoBoss&&next%10===0)notice('보스 도전 대기 · 보스 자동 도전을 켜면 진행합니다');s.battleCount=(s.battleCount||0)+1;if(s.battleCount%10===0)recordPower();paint();save()}};
cast = function cast(i,automatic=false){let k=s.slots[i];if(k<0){if(!automatic)openMenu('skills');return}if(cooldowns[i]>0){if(!automatic)notice('스킬 재사용 대기 '+Math.ceil(cooldowns[i])+'초');return}cooldowns[i]=[5,8,11,14][i];visualStrike();skillVisual(k);const damage=Math.ceil(power()*(2+(s.skills[k]||1)*.15)*(1+s.relics[2]*.025));applyDamage(damage,true);if(!automatic)banner(SK[k][0],900);paintBattle();paintCooldowns()};
paintCooldowns = function paintCooldowns(){for(let i=0;i<4;i++){const el=$('cool'+i);if(el){el.style.display=cooldowns[i]>0?'grid':'none';el.textContent=Math.ceil(cooldowns[i])}}};
skillVisual = function skillVisual(k){emitEffect(k===12||k===11?'void':k>=7&&k<=8?'ice':k>=9&&k<=10?'holy':'fire',.73,.63);playSound('skill')};
banner = function banner(t,time=1500){$('combatBanner').textContent=t;clearTimeout(banner.timer);banner.timer=setTimeout(()=>$('combatBanner').textContent='',time)};
playSound = function playSound(){return false};
emitEffect = function emitEffect(type,x,y){if(!s.effects||s.powerSaving)return;const colors={slash:'#ffd591',fire:'#ff8238',ice:'#a2efff',void:'#c767ff',holy:'#fff3a5',gold:'#ffdd70'},c=colors[type]||colors.fire;particles.push({kind:type==='slash'?'arc':'ring',x,y,t:0,born:performance.now(),life:type==='slash'?.32:.65,c});for(let i=0;i<(type==='slash'?12:28);i++){let a=Math.random()*Math.PI*2,v=.03+Math.random()*.18;particles.push({kind:'spark',x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,t:0,born:performance.now(),life:.35+Math.random()*.5,c,size:2+Math.random()*3})}if(particles.length>180)particles=particles.slice(-180);if(!effectRaf){frameTime=performance.now();effectRaf=requestAnimationFrame(drawEffects)}};
resizeEffects = function resizeEffects(){let r=$('battle').getBoundingClientRect(),d=Math.min(2,window.devicePixelRatio||1);fxSize={w:r.width,h:r.height};$('battle').style.setProperty('--tower-mini-size',Math.round(Math.min(r.width*(Number($('battle').dataset.miniScale)||.46),r.height*.53))+'px');let cv=$('effects');cv.width=Math.round(r.width*d);cv.height=Math.round(r.height*d);fxContext=cv.getContext('2d');fxContext.setTransform(d,0,0,d,0,0)};
drawEffects = function drawEffects(now){const dt=Math.min(.04,(now-frameTime)/1000);frameTime=now;const ctx=fxContext;if(!ctx){effectRaf=0;return}ctx.clearRect(0,0,fxSize.w,fxSize.h);ctx.globalCompositeOperation='lighter';particles=particles.filter(p=>p.t<p.life);particles.forEach(p=>{p.t=Math.max(0,(now-p.born)/1000);if(p.t>=p.life)return;const f=p.t/p.life,alpha=Math.max(0,1-f);ctx.globalAlpha=alpha;ctx.strokeStyle=p.c;ctx.fillStyle=p.c;ctx.shadowColor=p.c;ctx.shadowBlur=7;let x=p.x*fxSize.w,y=p.y*fxSize.h;if(p.kind==='spark'){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.12*dt;ctx.beginPath();ctx.arc(x,y,p.size*alpha,0,Math.PI*2);ctx.fill()}else if(p.kind==='arc'){ctx.lineWidth=(1-f)*7+2;ctx.beginPath();ctx.ellipse(x,y,fxSize.w*(.09+f*.1),fxSize.h*(.04+f*.10),-.18,-Math.PI*.7,Math.PI*.5);ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#fff8ce';ctx.stroke()}else{ctx.lineWidth=3*(1-f)+1;ctx.beginPath();ctx.ellipse(x,y,(20+f*95)*fxSize.w/900,(10+f*55)*fxSize.h/380,0,0,Math.PI*2);ctx.stroke()}});ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';effectRaf=particles.length?requestAnimationFrame(drawEffects):0};
upgrade = function upgrade(i,n=1){if(![0,1,2].includes(i))return;let count=0;while(count<n&&s.gold>=statCost(i)&&s.stats[i]<300){s.gold-=statCost(i);s.stats[i]++;count++}if(!count)notice(s.stats[i]>=300?'최대 레벨입니다':'골드가 부족합니다');else{s.daily.upgrades=(s.daily.upgrades||0)+count;notice(['공격력','공격속도','골드 획득'][i]+' +'+count);playSound('reward')}paint();save()};
make = function make(n){let count=Math.min(Math.max(0,Math.floor(n)),Math.floor(s.ore),100);if(!count){notice('성운석이 부족합니다');return}lastLoot=[];for(let i=0;i<count;i++){s.ore--;s.crafted++;s.forgeExp++;let r=rollR(),p=1+Math.floor(Math.random()*6),g={id:Date.now().toString(36)+'_'+s.crafted,p,r,plus:0};s.unlocked[p+'_'+r]=true;lastLoot.push({...g,salvaged:s.autoSalvage&&r<=1});if(s.autoSalvage&&r<=1)s.stones+=r+1;else if(s.gear.length>=GEAR_CAPACITY){s.stones+=r+1;lastLoot[lastLoot.length-1].salvaged=true}else{s.gear.push(g);if(s.autoEquip){let old=equippedItem(p);if(!old||(g.r+1)*(1+g.plus*.2)>(old.r+1)*(1+old.plus*.2))s.equipped[p]=g.id}}while(s.forgeLevel<FORGE_MAX_LEVEL&&s.forgeExp>=NEED[s.forgeLevel-1]){s.forgeExp-=NEED[s.forgeLevel-1];s.forgeLevel++}}s.daily.crafted=(s.daily.crafted||0)+count;playSound('reward');paint();save();openMenu('loot');banner('제작 완료',1000)};
salvage = function salvage(id){let g=s.gear.find(x=>x.id===id);if(!g)return;if(s.equipped[g.p]===id){notice('착용 중인 장비는 분해할 수 없습니다');return}s.stones+=(g.r+1)*5+g.plus*3;s.gear=s.gear.filter(x=>x.id!==id);paint();save();notice('장비를 분해했습니다')};
equipBest = function equipBest(){for(let p=0;p<7;p++){let best=s.gear.filter(g=>g.p===p).sort((a,b)=>(b.r+1)*(1+b.plus*.2)-(a.r+1)*(1+a.plus*.2))[0];if(best)s.equipped[p]=best.id}paint();save();notice('최고 전투력 장비를 장착했습니다')};
skillLevel = function skillLevel(i){if(s.shards<10){notice('스킬 조각이 부족합니다');return}if((s.skills[i]||0)>=100){notice('최대 레벨입니다');return}s.shards-=10;s.skills[i]=(s.skills[i]||0)+1;s.daily.upgrades=(s.daily.upgrades||0)+1;paint();save()};
levelAllSkills = function levelAllSkills(maximum){const learned=Object.keys(s.skills).map(Number);if(!learned.length||s.shards<10){notice('스킬 조각이 부족합니다');return}let count=0;for(let round=0;round<(maximum?100:1);round++){let done=0;for(const k of learned){if(s.shards<10)break;if(s.skills[k]>=100)continue;s.skills[k]++;s.shards-=10;done++;count++}if(!done)break}s.daily.upgrades=(s.daily.upgrades||0)+count;paint();save();notice('스킬 '+count+'회 강화 완료')};
slotSkill = function slotSkill(k){if(!s.skills[k]){notice('스킬을 먼저 습득하세요');return}if(s.slots.includes(k)){notice('이미 장착한 스킬입니다');return}view='slot';tab=String(k);render()};
setSlot = function setSlot(slot,k){if(!s.skills[k]||slot<0||slot>3)return;s.slots[slot]=k;cooldowns[slot]=Math.max(cooldowns[slot],5);view='skills';tab='';paint();save();notice(SK[k][0]+' 장착 완료')};
summon = function summon(n,useTicket=false,freeDay=null){return executeGameDraw('skill',n,useTicket,freeDay)};
dungeon = function dungeon(i){resetDay();if(dungeonRun){notice('이미 던전 전투 중입니다');return}if(s.tickets[i]<1){notice('입장권이 부족합니다. 내일 다시 도전하세요');return}s.tickets[i]--;let n=s.dungeonLevel[i];dungeonRun={i,n,hp:power()*(6+n*2),maxHp:power()*(6+n*2),time:40,startPower:power()};closeMenu();banner(['황금 광산','고대 무기고','마법 도서관'][i]+' 입장');paint();save()};
finishDungeon = function finishDungeon(win){const run=dungeonRun;if(!run)return;dungeonRun=null;let reward=0;if(win){reward=run.i===0?500*run.n:run.i===1?15*run.n:12*run.n;s[['gold','ore','shards'][run.i]]+=reward;s.dungeonLevel[run.i]=run.n+1;s.daily.dungeons=(s.daily.dungeons||0)+1;playSound('reward')}paint();save();view='dungeonResult';window.lastDungeonResult={...run,win,reward};$('overlay').classList.add('show');render()};
recordPower = function recordPower(){
 if(!s?.classId||testSession||s.testOnly||dungeonRun?.mode==='trial')return;
 const score=Math.round(combatPower());
 if(Number.isSafeInteger(score)&&score>0)s.rankPower=Math.max(s.rankPower||0,score);
};
claimMail = function claimMail(){if(s.mailClaimed){notice('이미 수령한 우편입니다');return}s.mailClaimed=true;s.gems+=300;s.ore+=30;s.shards+=30;notice('환영 보상 · 다이아 300 · 성운석 30 · 스킬 조각 30');paint();save()};
claimVip = function claimVip(i){const needs=[0,250,500,750,1000,1250];if(s.crafted<needs[i]||s.vipClaimed[i]){notice('조건 미달 또는 이미 수령한 보상입니다');return}s.vipClaimed[i]=true;s.gems+=100+i*50;s.ore+=10+i*5;paint();save();notice('VIP '+i+' 보상 수령')};
claimCollection = function claimCollection(p){let found=Object.keys(s.unlocked).filter(k=>k.startsWith(p+'_')).length,claimed=s.collectionClaimed[p]||0;if(found<=claimed){notice('새로운 등급의 장비를 수집하세요');return}s.gems+=(found-claimed)*20;s.collectionClaimed[p]=found;paint();save();notice('도감 보상 수령')};
dailyClaim = function dailyClaim(type){const goals={kills:30,crafted:10,upgrades:5,dungeons:1};if((s.daily[type]||0)<goals[type]||s.daily.claimed[type]){notice('조건 미달 또는 수령 완료');return}s.daily.claimed[type]=true;s.gems+=50;paint();save();notice('일일 미션 · 다이아 +50')};
claimAttendance = function claimAttendance(){resetDay();if(s.lastAttendance===today()){notice('오늘 출석 보상을 이미 받았습니다');return}let i=s.attendance%7,[icon,n]=ATT[i];if(i===0||i===3||i===6)s.gems+=n;else if(i===1)s.ore+=n;else if(i===4)s.shards+=n;else if(i===5)s.tickets=s.tickets.map(x=>x+n);else s.shards+=n*5;s.attendance++;s.lastAttendance=today();notice((i+1)+'일차 출석 완료');paint();save();playSound('reward')};
dashboardQuestTab = function dashboardQuestTab(t){questTab=t;paintDashboard();hydrateArt()};
setSkillTab = function setSkillTab(t){currentSkillTab=t;paintSkillPreview();hydrateArt()};
paintDashboard = function paintDashboard(){const side=(parts,cls)=>`<div class="gear-side ${cls}">${parts.map(p=>{const g=equippedItem(p);return `<button class="gear-icon ${g?'':'empty'} ${g&&g.r>=4?'epic':''}" onclick="openMenu('equipment')" aria-label="${PARTS[p]} 관리">${art('gear'+p)}<b>${g?'+'+g.plus:'−'}</b></button>`}).join('')}</div>`;$('equipmentPreview').innerHTML=side([0,2,4],'left')+side([1,3,5],'right')+`<div class="paperdoll"></div><div class="equipment-stats"><b>전투력 ${ratingText(combatPower())}</b><div class="stat-row"><span>${art('gear0')} 공격력</span><strong>${num(power())}</strong></div><div class="stat-row"><span>${art('gear2')} 방어력</span><strong>${num(armor())}</strong></div><div class="stat-row"><span>${art('relic1')} 체력</span><strong>${num(health())}</strong></div></div><button class="gold-button small equipment-manage" onclick="openMenu('equipment')">장비 관리</button>`;$('forgeLevel').textContent='Lv.'+s.forgeLevel+(s.forgeLevel>=FORGE_MAX_LEVEL?' (MAX)':'');$('forgeProgress').style.width=(s.forgeLevel>=FORGE_MAX_LEVEL?100:s.forgeExp/NEED[s.forgeLevel-1]*100)+'%';$('forgeXP').textContent=s.forgeLevel>=FORGE_MAX_LEVEL?'경험치 (MAX)':num(s.forgeExp)+' / '+num(NEED[s.forgeLevel-1]);paintSkillPreview();$('relicPreview').innerHTML=art('relicCore','relic-core')+REL.map((r,i)=>`<button class="relic-item" onclick="openMenu('relics')" title="${r[0]}">${art('relic'+i)}<small>Lv.${s.relics[i]}</small></button>`).join('');$('relicSummary').innerHTML=`<b>유물 종합 효과</b><div><span>공격력 +${(s.relics[0]*4).toFixed(1)}%</span><span>체력 +${(s.relics[1]*4).toFixed(1)}%</span></div><div><span>스킬 피해 +${(s.relics[2]*2.5).toFixed(1)}%</span><span>골드 획득 +${(s.relics[3]*3).toFixed(1)}%</span></div>`;$('dungeonPreview').innerHTML=['황금 광산','고대 무기고','마법 도서관'].map((name,i)=>`<div class="dungeon-card"><b>${name}</b>${art('dungeon'+i)}<small>입장 가능 ${s.tickets[i]}/2</small><button class="gold-button" onclick="dungeon(${i})" ${s.tickets[i]<1?'disabled':''}>입장</button></div>`).join('');const at=s.attendance%7,claimedToday=s.lastAttendance===today(),cycle=claimedToday&&at===0?7:at;$('attendancePreview').innerHTML=ATT.map((a,i)=>`<button class="day-card ${i===at&&!claimedToday?'today':''}" onclick="${i===at&&!claimedToday?'claimAttendance()':"openMenu('attendance')"}"><b>${i+1}일차</b>${i<cycle?'<span class="claimed"><ui-mark data-shape=check aria-hidden=true></ui-mark></span>':art(['gem','ore','ticket','gem','shard','ticket','gem'][i])+`<strong>${num(a[1])}</strong>`}</button>`).join('');const stages=[5,10,20,30,50,75,100,150],level=Math.min(30,Math.floor(s.maxStage/5)+1);$('passPreview').innerHTML=art('passPortrait','pass-portrait')+`<div class="pass-level"><b>Lv.${level}</b><div class="progress-track"><i style="width:${(s.maxStage%5)/5*100}%"></i><small>${s.maxStage%5} / 5 STAGE</small></div></div><div class="pass-rewards">${stages.slice(0,6).map((n,i)=>`<button class="pass-reward" onclick="claimPass(${n},${50+i*25})" title="STAGE ${n} 달성 보상"><b>${n}</b>${art('gem')}<small>${s.passClaimed[n]?'<ui-mark data-shape=check aria-hidden=true></ui-mark>':50+i*25}</small></button>`).join('')}</div>`;paintQuests();$('rankingPreview').textContent='최고 전투력 '+ratingText(s.rankPower||0)};
paintSkillPreview = function paintSkillPreview(){const tabs=['전체','무속성','화염','냉기','신성','암흑'];$('skillTabs').innerHTML=tabs.map(t=>`<button class="${currentSkillTab===t?'active':''}" onclick="setSkillTab('${t}')">${t}</button>`).join('');const types=['무속성','무속성','무속성','무속성','화염','화염','화염','냉기','냉기','신성','신성','암흑','암흑'];let list=SK.map((_,i)=>i).filter(i=>currentSkillTab==='전체'||types[i]===currentSkillTab).slice(0,10);$('skillPreview').innerHTML=list.map(i=>`<button class="skill-tile ${s.skills[i]?'':'unlearned'}" onclick="skillDetail(${i})" title="${SK[i][0]}">${art('s'+(i%10))}<small>${s.skills[i]?'Lv.'+s.skills[i]:'미습득'}</small></button>`).join('')};
skillDetail = function skillDetail(k){tab=String(k);view='skillDetail';$('overlay').classList.add('show');render()};
questProgress = function questProgress(index){const values=[s.kills,s.crafted,s.stats[0],s.maxStage,s.crafted,s.kills,s.maxStage,s.stats[1],s.crafted,s.maxStage,s.forgeLevel,s.kills,s.maxStage,s.stats[0],s.forgeLevel,s.maxStage,s.crafted,s.kills,s.maxStage,s.forgeLevel,s.maxStage,s.forgeLevel],goals=[10,10,10,5,30,50,10,10,100,20,3,200,30,30,5,50,500,1000,75,8,100,10];return [values[index]||0,goals[index]||1]};
paintQuests = function paintQuests(){$('mainQuestTab').classList.toggle('selected',questTab==='main');$('dailyQuestTab').classList.toggle('selected',questTab==='daily');let rows=questTab==='main'?Array.from({length:3},(_,j)=>{let i=s.quest+j;if(!Q[i])return null;let [v,max]=questProgress(i);return {name:Q[i][0],v,max,ready:i===s.quest&&Q[i][1](),code:i===s.quest&&Q[i][1]()?'claimQuest()':"openMenu('quests')",reward:orderRewardText(growthQuestReward(i))}}):[['kills','몬스터 30마리 처치',30],['crafted','장비 제작 10회',10],['upgrades','능력 강화 5회',5]].map(([key,name,max])=>({name,v:s.daily[key]||0,max,ready:(s.daily[key]||0)>=max&&!s.daily.claimed[key],code:`dailyClaim('${key}')`,reward:'다이아 50',claimed:s.daily.claimed[key]}));$('questPreview').innerHTML=rows.filter(Boolean).map(r=>`<div class="quest-row"><span class="quest-medal">${art('quests')}</span><div class="quest-label"><span>${r.name} (${Math.min(r.v,r.max)}/${r.max})</span><div class="quest-line"><i style="width:${Math.min(100,r.v/r.max*100)}%"></i></div></div><span class="quest-reward">${r.reward}</span><button class="gold-button ${r.ready?'':'purple'}" onclick="${r.code}" ${r.claimed?'disabled':''}>${r.claimed?'완료':r.ready?'보상 수령':'이동'}</button></div>`).join('')||'<div class="empty-state">모든 퀘스트를 완료했습니다.</div>'};
openMenu = function openMenu(x){lastFocused=document.activeElement;view=x;tab='';$('overlay').classList.add('show');render();setTimeout(()=>document.querySelector('.close-button').focus(),20)};
closeMenu = function closeMenu(){view='';$('overlay').classList.remove('show');if(lastFocused?.isConnected)lastFocused.focus()};
render = function render(){if(!view)return;const title=MENU_DATA.find(x=>x[0]===view)?.[1]||{attendance:'출석 보상',shop:'상점',vip:'모험 VIP',event:'이벤트',mail:'우편함',loot:'제작 결과',slot:'스킬 슬롯 선택',skillDetail:'스킬 상세',dungeonResult:'던전 전투 결과'}[view]||'성운의 모루';$('heading').textContent=title;const content=$('content'),oldScroll=content.scrollTop;const renders={growth:growthUI,forge:forgeUI,equipment:equipmentUI,skills:skillsUI,relics:relicUI,dungeon:dungeonUI,quests:questUI,attendance:attendanceUI,shop:shopUI,collection:collectionUI,costume:costumeUI,pass:passUI,ranking:rankingUI,vip:vipUI,settings:settingsUI,mail:mailUI,event:eventUI,loot:lootUI,slot:slotUI,skillDetail:skillDetailUI,dungeonResult:dungeonResultUI};content.innerHTML=(renders[view]||settingsUI)();hydrateArt(content);content.scrollTop=oldScroll};
growthUI = function growthUI(){return panel('성운기사 · Lv.'+s.level,`<div class="modal-stats"><span>전투력 <b>${ratingText(combatPower())}</b></span><span>방어력 <b>${num(armor())}</b></span><span>체력 <b>${num(health())}</b></span></div><p class="muted">장비와 유물의 보너스가 능력에 적용됩니다.</p><div class="bar"><i style="width:${s.xp/(playerXpGoal())*100}%"></i></div><div class="small">경험치 ${num(s.xp)} / ${num(playerXpGoal())}</div>`)+panel('기본 능력 강화',['공격력','공격속도','골드 획득'].map((x,i)=>`<div class="between growth-row">${art(['equipment','growth','coin'][i])}<div class="growth-info"><b>${x} Lv.${s.stats[i]}</b><small>${i===0?'기본 공격 피해 증가':i===1?'자동 공격 간격 감소':'처치 골드 증가'}</small></div>${actionButton('골드 '+num(statCost(i)),'upgrade('+i+')')}${actionButton('10회 강화','upgrade('+i+',10)','alt')}</div>`).join(''))};
forgeUI = function forgeUI(){return panel('천공의 대장간',`${art('forge','forge-illustration')}<div style="text-align:center"><b>모루 Lv.${s.forgeLevel} / ${FORGE_MAX_LEVEL}</b><p>보유 성운석 ${num(s.ore)} · 누적 제작 ${num(s.crafted)}회</p><div class="bar"><i style="width:${s.forgeLevel===FORGE_MAX_LEVEL?100:s.forgeExp/NEED[s.forgeLevel-1]*100}%"></i></div><p class="small">${s.forgeLevel===FORGE_MAX_LEVEL?'최대 레벨':num(s.forgeExp)+' / '+num(NEED[s.forgeLevel-1])+' 경험치'}</p>${[1,10,100].map(n=>actionButton(n+'회 제작 · 성운석 '+n,'make('+n+')')).join('')}</div>`)+panel('제작 설정',`<label><input type="checkbox" ${s.autoEquip?'checked':''} onchange="s.autoEquip=this.checked;save()"> 더 강한 장비 자동 장착</label><p><label><input type="checkbox" ${s.autoSalvage?'checked':''} onchange="s.autoSalvage=this.checked;save()"> 일반 · 매직 장비 자동 분해</label></p><p class="muted">제작당 경험치 +1. 모루 레벨에 따라 상위 등급이 열립니다.</p>`)+panel('제작 등급과 확률',RAR.map((r,i)=>{let max=unlockedR(),total=Array.from({length:max+1},(_,j)=>Math.pow(2.9,max-j)).reduce((a,b)=>a+b,0);return `<div class="between"><span class="rar${i}">${r}</span><span>${i>max?'미해금':(Math.pow(2.9,max-i)/total*100).toFixed(3)+'%'}</span></div>`}).join(''))};
lootUI = function lootUI(items=lastLoot,action=currentResultAction('loot'),selected=new Set()){
 const sorted=[...items].sort((a,b)=>b.r-a.r),owned=new Map(s.gear.map(g=>[g.id,g]));
 return forgeBatchHighlight(sorted[0],items.length)+`<div class="summary-strip">${items.length}회 제작 완료 <b class="rar${sorted[0]?.r||0}">최고 ${RAR[sorted[0]?.r]||'일반'}</b></div>${items.length>12?resultFooter(action):''}${salvageBar(selected)}<div class="collection-grid4">${sorted.map(g=>equipmentTile(g,owned.get(g.id),selected)).join('')}</div>${items.length<=12?resultFooter(action):''}<button class="muted-button profile-wide" onclick="openMenu('inventory')">장비 가방</button>`;
};
equipmentUI = function equipmentUI(){const t=tab||'착용';let head=`<div class="tabs">${['착용','가방','도감'].map(x=>`<button class="${t===x?'active':''}" onclick="switchTab('${x}')">${x}</button>`).join('')}</div>`;if(t==='도감')return head+collectionUI();if(t==='착용')return head+panel('장착 장비 · 전투력 '+ratingText(combatPower()),`<div class="item-hero"></div><div class="grid">${PARTS.map((p,i)=>{const g=equippedItem(i);return `<div class="tile"><span class="ico">${art('gear'+i)}</span><strong>${p}</strong><b class="rar${g?.r||0}">${g?gearName(g):'미장착'}</b><div>${g?actionButton(g.plus>=15?'최대 강화':'강화 · '+num(10*(g.plus+1)*(g.r+1))+'석',`improve('${g.id}')`):''}</div></div>`}).join('')}</div><p>보유 강화석 ${num(s.stones)}</p>${actionButton('최고 장비 자동 장착','equipBest()')}${actionButton('가방 열기',"switchTab('가방')",'alt')}`);return head+panel('장비 가방 '+s.gear.length+' / '+GEAR_CAPACITY,`${actionButton('최고 장비 장착','equipBest()')}${actionButton('일반 · 매직 일괄 분해','salvageLow()','alt')}<div class="small">착용 장비는 분해에서 보호됩니다. 강화석 ${num(s.stones)}</div>`)+`<div class="grid">${[...s.gear].sort((a,b)=>b.r-a.r||b.plus-a.plus).map(g=>`<div class="tile"><span class="ico">${gearArt(g)}</span><strong class="rar${g.r}">${gearName(g)}</strong><div class="small">${s.equipped[g.p]===g.id?'착용 중':'보관 중'} · 장비 효과 ${Math.floor((g.r+1)*12*(1+g.plus*.2))}</div>${actionButton('장착',`equip('${g.id}')`)}${actionButton('강화',`improve('${g.id}')`,'alt')}${s.equipped[g.p]!==g.id?actionButton('분해',`salvage('${g.id}')`,'red'):''}</div>`).join('')}</div>`};
skillsUI = function skillsUI(){return panel('장착 스킬',`<div class="grid">${s.slots.map((k,i)=>`<div class="tile"><span class="ico">${art('cast'+i)}</span><strong>슬롯 ${i+1} · ${k<0?'빈 슬롯':SK[k][0]}</strong><small>${k<0?'스킬을 습득하고 장착하세요':'Lv.'+s.skills[k]+' · 재사용 '+[5,8,11,14][i]+'초'}</small></div>`).join('')}</div><p class="muted">자동 사용은 설정에서, 수동 사용은 단축키 1–4로 조작하세요.</p>`)+panel('스킬 소환',`보유 다이아 ${num(s.gems)} · 스킬 조각 ${num(s.shards)}<br>${actionButton('1회 소환 · 다이아 150','summon(1)')}${actionButton('10회 소환 · 다이아 1,350','summon(10)')}`)+`<div class="grid">${SK.map(([name],i)=>`<div class="tile"><span class="ico">${art('s'+i%10)}</span><strong>${name}</strong><div class="small">${s.skills[i]?'Lv.'+s.skills[i]:'미습득'}</div>${actionButton('조각 10 · '+(s.skills[i]?'강화':'습득'),'skillLevel('+i+')','alt')}${actionButton('장착','slotSkill('+i+')')}</div>`).join('')}</div>`};
skillDetailUI = function skillDetailUI(){let k=Number(tab),lv=s.skills[k]||0;return panel(SK[k][0],`<div class="tile"><span class="ico">${art('s'+k%10)}</span><strong>Lv.${lv} / 100</strong><p>${lv?'공격력의 '+Math.round((2+lv*.15)*100)+'% 피해':'스킬 조각 10개로 습득할 수 있습니다.'}</p><p class="small">보유 조각 ${num(s.shards)}</p>${actionButton(lv?'조각 10 · 강화':'조각 10 · 습득','skillLevel('+k+')')}${actionButton('슬롯에 장착','slotSkill('+k+')','alt')}</div>`)};
slotUI = function slotUI(){const k=Number(tab);return panel(SK[k][0]+' 장착',s.slots.map((v,i)=>`<div class="between"><span>슬롯 ${i+1} · ${v<0?'빈 슬롯':SK[v][0]}</span>${actionButton('이 슬롯에 장착',`setSlot(${i},${k})`)}</div>`).join(''))};
relicUI = function relicUI(){return panel('유물의 힘',`${art('relicCore','large-relic')}<p>보유 조각 ${num(s.shards)}</p><p class="muted">자연의 검은 공격력, 수호의 방패는 체력·방어력, 고대의 지팡이는 스킬 피해, 왕의 반지는 골드 획득을 강화합니다.</p>`)+`<div class="grid">${REL.map(([name,icon,stage],i)=>`<div class="tile"><span class="ico">${art('relic'+i)}</span><strong>${name}</strong><p class="small">${s.maxStage<stage?'STAGE '+stageText(stage)+' 해금':'Lv.'+s.relics[i]+' / 50'}</p>${actionButton('조각 '+(5+s.relics[i]*2)+' · 강화','relicLevel('+i+')')}</div>`).join('')}</div>`};
relicLevel = function relicLevel(i){if(s.maxStage<REL[i][2]){notice('최고 스테이지 '+stageText(REL[i][2])+'에서 해금됩니다');return}const cost=5+s.relics[i]*2;if(s.relics[i]>=50){notice('최대 레벨입니다');return}if(s.shards<cost){notice('조각이 부족합니다');return}s.shards-=cost;s.relics[i]++;paint();save()};
dungeonUI = function dungeonUI(){return `<div class="grid">${['황금 광산','고대 무기고','마법 도서관'].map((name,i)=>`<div class="tile"><span class="ico" style="height:100px;width:85px">${art('dungeon'+i)}</span><strong>${name}</strong><p>난이도 ${s.dungeonLevel[i]}</p><p class="small">입장권 ${s.tickets[i]} · 보상 ${['골드','성운석','스킬 조각'][i]}</p>${actionButton('입장','dungeon('+i+')')}</div>`).join('')}</div>`+panel('던전 도전',`40초 안에 수호자를 쓰러뜨리면 보상을 받습니다. 입장 시 입장권 1개를 사용하며, 매일 기기 시간 자정에 2개로 충전됩니다.${dungeonRun?'<p>현재 던전 전투 진행 중</p>'+actionButton('전투로 돌아가기','closeMenu()')+actionButton('던전 포기','finishDungeon(false)','red'):''}`)};
dungeonResultUI = function dungeonResultUI(){const r=window.lastDungeonResult;return panel(r.win?'DUNGEON CLEAR':'도전 종료',`<div style="text-align:center">${art('dungeon'+r.i,'large-relic')}<h3>${['황금 광산','고대 무기고','마법 도서관'][r.i]} ${r.n}단계</h3><p>${r.win?['골드','성운석','스킬 조각'][r.i]+' +'+num(r.reward):'제한 시간이 종료되었거나 도전을 포기했습니다.'}</p>${actionButton('확인','closeMenu()')}${actionButton('던전 목록',"openMenu('dungeon')",'alt')}</div>`)};
questUI = function questUI(){const q=Q[s.quest],[v,max]=questProgress(s.quest);return panel('진행 퀘스트 '+Math.min(22,s.quest+1)+' / 22',q?`<strong>${q[0]}</strong><p>${Math.min(v,max)} / ${max}</p><div class="bar"><i style="width:${Math.min(100,v/max*100)}%"></i></div>${actionButton(orderRewardText(growthQuestReward(s.quest))+' · 보상 수령','claimQuest()')}`:'모든 진행 퀘스트를 완료했습니다!')+panel('일일 미션',[['kills','몬스터 처치',30],['crafted','장비 제작',10],['upgrades','능력 강화',5],['dungeons','던전 클리어',1]].map(([key,name,goal])=>`<div class="between"><span>${name} ${Math.min(s.daily[key]||0,goal)} / ${goal}</span>${actionButton(s.daily.claimed[key]?'수령 완료':'다이아 50 · 수령',`dailyClaim('${key}')`,s.daily.claimed[key]?'alt':'')}</div>`).join(''))};
attendanceUI = function attendanceUI(){const cycle=s.attendance%7,done=s.lastAttendance===today();return panel('7일 출석 보상',`<p>누적 출석 ${s.attendance}일 · ${done?'오늘 보상 수령 완료':'오늘 보상을 받을 수 있습니다'}</p><div class="grid">${ATT.map(([_,n],i)=>`<div class="tile"><b>${i+1}일차</b><span class="ico">${art(['gem','ore','ticket','gem','shard','ticket','gem'][i])}</span><strong>${['다이아','성운석','스킬북','다이아','스킬 조각','던전 입장권','다이아'][i]} ${num(n)}</strong><div class="small">${i<(done&&cycle===0?7:cycle)?'수령 완료':i===cycle&&!done?'오늘 수령 가능':'다음 출석 보상'}</div></div>`).join('')}</div><p class="small">7일차 수령 다음 날 다시 시작합니다. 스킬북 1권은 스킬 조각 5개입니다.</p>${actionButton(done?'오늘 수령 완료':'오늘 출석 보상 받기','claimAttendance()')}`)};
