hydrateArt=function(root=document){
 const aliases={mission:'quests',crown:'vip',collection:'inventory',chest:'offlineChest'};
 for(const el of root.querySelectorAll('[data-art]')){
  const key=el.dataset.art;
  const catalogName=CATALOG_ART[key];
  if(typeof catalogName==='string'){
   el.dataset.icon=key;
   el.classList.add('catalog-icon');
   el.style.backgroundImage='url("'+catalogPath(catalogName)+'")';
   el.removeAttribute('data-art');continue;
  }
  if(/^tower_mini_\d{2}$/.test(key)){
   el.dataset.icon=key;el.classList.add('hd');el.style.backgroundImage='url("./assets/tower-minis/'+key.slice(-2)+'.webp")';
   el.style.backgroundSize='contain';el.style.backgroundPosition='center';el.style.maskImage='none';el.removeAttribute('data-art');continue;
  }
  const skillSurface=el.closest?.('[data-surface="skills"],#skillbuttons,.skill-sigil,.skill-tile,.class-skill-preview');
  const asset=HD_ART[key] || (!skillSurface && HD_ART[aliases[key]]);
  el.dataset.icon=key;
  if(asset){
   const [sheet,w,h,x,y,cw,ch]=asset;
   el.classList.add('hd');
   const size=(w/cw*100)+'% '+(h/ch*100)+'%';
   const position=(w===cw?0:x/(w-cw)*100)+'% '+(h===ch?0:y/(h-ch)*100)+'%';
   const isGear=/^(?:equipment|masterwork)_\d+_\d+$/.test(key);
   let paint=el;
   const relicSheet=sheet==='relic-treasures'||sheet==='relic-sanctum';
   if(isGear||relicSheet){
    paint=document.createElement('span');paint.className='atlas-cell';
    const fit=sheet==='relic-sanctum'?94:100;
    paint.style.width=(cw/Math.max(cw,ch)*fit)+'%';paint.style.height=(ch/Math.max(cw,ch)*fit)+'%';
    el.classList.add('atlas-fit');el.appendChild(paint);
   }
   paint.style.backgroundImage='var(--'+sheet+')';paint.style.backgroundSize=size;paint.style.backgroundPosition=position;
   // A menu icon's alpha mask clips every animated descendant of the actor.
   // Battle paintings have their own transparent edges at every pose.
   if(el.classList.contains('mob')&&el.closest?.('#battle')){
    paint.style.removeProperty('mask-image');el.classList.remove('ui-cutout');
   }else if(!skillSurface && sheet!=='scenes-hd' && sheet!=='summon-book-hd' && !/^(?:s|cast)\d+$/.test(key)){
    if(!isGear&&!relicSheet){
     paint.style.maskImage='url("./assets/ui-masks/'+sheet+'.png")';
     paint.style.maskSize=size;paint.style.maskPosition=position;paint.style.maskRepeat='no-repeat';
    }
    el.classList.add(isGear?'gear-illustration':'ui-cutout');
   }else if(!skillSurface && sheet==='summon-book-hd'){el.classList.add('book-outline')}
  }else{
   const z=ART[key]||ART.gem;
   el.style.backgroundSize=(1672/z[2]*100)+'% '+(941/z[3]*100)+'%';
   el.style.backgroundPosition=(z[0]/(1672-z[2])*100)+'% '+(z[1]/(941-z[3])*100)+'%';
  }
  el.removeAttribute('data-art');
 }
 if(root===document||root.id==='screenContent'||root.id==='content')paintTransactionControls(root);
 if(typeof paintFeatureLocks==='function'&&typeof featureOpen==='function'){
  paintFeatureLocks(root);
  if(root.id==='screenContent')paintFeatureLocks($('screenTabs'));
 }
};

