renderScreen = function renderScreen(keepScroll=true){if(activeScreen==='home')return;const [title,eyebrow]=SCREEN_META[activeScreen],el=$('screenContent'),scroll=keepScroll?el.scrollTop:0;el.dataset.surface=activeScreen==='skills'||activeScreen==='shop'&&screenTab==='summon'?'skills':'interface';$('screenHeading').textContent=activeScreen==='character'?(SCREEN_TABS.character.find(([key])=>key===screenTab)?.[1]||title):title;$('screenEyebrow').textContent=eyebrow;const tabs=SCREEN_TABS[activeScreen]||[],tabBar=$('screenTabs');tabBar.hidden=tabs.length===0;tabBar.innerHTML=tabs.map(([k,n])=>`<button data-guide="tab-${k}" onclick="switchScreenTab('${k}')" class="${screenTab===k?'active':''}" aria-pressed="${screenTab===k}">${n}${rewardDot('tab:'+k)}</button>`).join('');el.innerHTML=({character:characterScreen,forge:forgeScreen,skills:skillsScreen,dungeon:dungeonScreen,shop:shopScreen,content:townScreen}[activeScreen])();hydrateArt(el);el.scrollTop=scroll;if(!keepScroll&&typeof el.animate==='function'&&typeof motionAllowed==='function'&&motionAllowed()){el.getAnimations?.().forEach(a=>a.cancel());el.animate([{opacity:0,transform:'translate3d(0,6px,0)'},{opacity:1,transform:'none'}],{duration:200,easing:'cubic-bezier(.22,1,.36,1)'});}};
screenInfo = function screenInfo(){openMenu('info',activeScreen)};
render = function render(){if(!view)return;const titles={more:'성운의 기록',info:'도움말',attendance:'별빛 출석',event:'모험의 선물',quests:'임무',pass:'성장 패스',ranking:'랭킹',settings:'설정',mail:'우편함',vip:'모험 VIP',loot:'제작 결과',skillDetail:'스킬',slot:'장착 슬롯',gearDetail:'장비 상세',inventory:'장비 가방',relicDetail:'유물 강화',forgeRates:'모루 성장',dungeonResult:'던전 결과',collection:'장비 도감'};$('heading').textContent=titles[view]||'성운의 모루';const el=$('content'),scroll=el.scrollTop;const pages={more:morePopup,info:infoPopup,attendance:attendancePopup,event:eventPopup,quests:questsPopup,pass:passPopup,ranking:rankingPopup,settings:settingsUI,mail:mailUI,vip:vipUI,loot:lootUI,skillDetail:skillPopup,slot:slotPopup,gearDetail:gearPopup,inventory:inventoryPopup,relicDetail:relicPopup,forgeRates:forgeRatesPopup,dungeonResult:dungeonResultUI,collection:collectionUI};el.innerHTML=pages[view]?pages[view]():`<div class="empty-state">메뉴를 다시 선택해 주세요.</div>`;hydrateArt(el);el.scrollTop=scroll;setPopupInert(true)};
characterScreen = function characterScreen(){switch(screenTab){case 'growth':return growthScreen();case 'relics':return relicsScreen();case 'costume':return costumeScreen();case 'collection':return collectionScreen();default:return equipmentScreen()}};
equipmentScreen = function equipmentScreen(){
 const tiles=PARTS.map((part,i)=>{
  const g=equippedItem(i);
  if(g?.signature)return weaponTile();
  if(g)return equipmentTile(g,g,null,true);
  if(i>0)return equippedTileButton({title:part,label:part+' 빈 슬롯 +'+s.gearSlotLevels[i],grade:0,icon:gearArt({p:i,r:0}),level:'+'+s.gearSlotLevels[i],action:"openMenu('gearSlot',"+i+")"});
  return collectionTile({name:part,icon:gearArt({p:i,r:0}),empty:true,action:i===0?"navigate('forge','weapon')":"openMenu('gearSlot',"+i+")"});
 });
 return gearMaterialHUD()+`<section class="codex-block"><div class="codex-heading"><h3>장착 장비</h3><span>전투력 ${ratingText(combatPower())}</span></div><div class="collection-grid4">${tiles.join('')}</div><div class="action-row">${button('장비 가방 '+s.gear.length+'/'+GEAR_CAPACITY,"openMenu('inventory')",false,true)}${button('최고 장비 장착','equipBest()')}</div></section><div class="stat-chips"><div><small>공격력</small><b>${compact(power())}</b></div><div><small>방어력</small><b>${compact(armor())}</b></div><div><small>체력</small><b>${compact(health())}</b></div></div>`;
};
growthScreen = function growthScreen(){return `<div class="card"><h3>성운기사 Lv.${s.level}</h3><div class="between"><span class="muted">다음 레벨까지</span><b>${num(s.xp)} / ${num(playerXpGoal())}</b></div><div class="bar"><i style="width:${s.xp/(playerXpGoal())*100}%"></i></div><div class="small">전투에서 경험치를 얻으면 레벨이 오릅니다.</div></div><div class="section-label"><span>기본 능력 강화</span><small>보유 골드 ${num(s.gold)}</small></div>${['공격력','공격속도','골드 획득'].map((name,i)=>`<div class="growth-row">${art(['equipment','growth','coin'][i])}<div><b>${name} Lv.${s.stats[i]}</b><small>${['기본 공격 피해','공격 간격 단축','몬스터 처치 보상'][i]}</small></div><button class="gold-button" onclick="upgrade(${i})">강화<small>${compact(statCost(i))} 골드</small></button></div>`).join('')}<div class="section-label"><span>일괄 강화</span><small>재화가 허용하는 만큼 적용</small></div><div class="action-row">${['공격력','공격속도','골드 획득'].map((n,i)=>`<button class="gold-button purple" onclick="upgrade(${i},10)">${n} 10회</button>`).join('')}</div><div class="summary-strip">현재 전투력 <b>${ratingText(combatPower())}</b></div>`};
relicsScreen = function relicsScreen(){return `<div class="relic-scene">${art('relicCore','relic-center')}${REL.map(([name],i)=>`<button class="relic-node n${i}" onclick="openMenu('relicDetail',${i})" aria-label="${name} 강화">${art('relic'+i)}<small>Lv.${s.relics[i]}</small></button>`).join('')}</div><div class="resource-note">${art('shard')}보유 조각 <b>${num(s.shards)}</b></div><div class="effect-table"><div><span>자연의 검 · 공격력</span><b>+${s.relics[0]*4}%</b></div><div><span>수호의 방패 · 체력</span><b>+${s.relics[1]*4}%</b></div><div><span>고대의 지팡이 · 스킬 피해</span><b>+${(s.relics[2]*2.5).toFixed(1)}%</b></div><div><span>왕의 반지 · 골드 획득</span><b>+${s.relics[3]*3}%</b></div></div><p class="small" style="text-align:center">유물을 누르면 다음 효과와 강화 비용을 볼 수 있습니다.</p>`};
costumeFilter = function costumeFilter(i){return 'hue-rotate('+[0,185,0,240,40,295,270,140][i]+'deg)'};
changeCostume = function changeCostume(d){selectedCostume=(selectedCostume+d+8)%8;renderScreen()};
selectCostume = function selectCostume(i){selectedCostume=i;renderScreen()};
costumeScreen = function costumeScreen(){const i=selectedCostume,owned=s.costumes.includes(i);return `<div class="costume-stage">${costumeSprite(i)}<button onclick="changeCostume(-1)" aria-label="이전 스킨"><ui-mark data-shape=chevron-left aria-hidden=true></ui-mark></button><button onclick="changeCostume(1)" aria-label="다음 스킨"><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></button><div class="costume-name"><strong>${COSTUME_NAMES[i]}</strong><small>${s.wear===i?'현재 착용 중':owned?'보유 스킨':'미보유 스킨'}</small></div></div><div class="action-row"><button class="gold-button" onclick="wear(${i})" ${!owned||s.wear===i?'disabled':''}>${s.wear===i?'착용 중':'착용'}</button><button class="gold-button purple" onclick="navigate('shop','summon')">스킨 소환</button></div><div class="summary-strip">${s.costumes.length}종 보유 <b>공격력 +${s.costumes.length*2}%</b></div><div class="costume-thumbs">${COSTUME_NAMES.map((n,j)=>`<button class="${j===i?'active':''} ${s.costumes.includes(j)?'':'locked'}" onclick="selectCostume(${j})">${costumeSprite(j)}<small>${n}</small></button>`).join('')}</div>`};
collectionScreen = function collectionScreen(){const count=Object.values(s.unlocked).filter(Boolean).length;return `<div class="summary-strip">발견한 장비 <b>${count} / ${PARTS.length*RAR.length}</b></div><p class="small">새 등급 발견 시 다이아 20개</p>${PARTS.map((name,i)=>{let found=Object.keys(s.unlocked).filter(k=>k.startsWith(i+'_')).length;return `<div class="pass-row">${art('gear'+i)}<div><strong>${name}</strong><small>발견 ${found}/${RAR.length} · 수령 ${s.collectionClaimed[i]||0}</small></div><button class="gold-button ${found>(s.collectionClaimed[i]||0)?'':'purple'}" onclick="openMenu('collectionPart',${i})">도감 보기</button></div>`}).join('')}`};
skillsScreen = function skillsScreen(){if(screenTab==='summon')return summonScreen('skills');const list=SK.map((_,i)=>i).filter(i=>screenFilter==='전체'||SKILL_TYPES[i]===screenFilter);return `<div class="section-label" style="margin-top:0"><span>전투 스킬</span><small>4개 슬롯 · 자동 시전</small></div><div class="skill-equipped">${s.slots.map((k,i)=>`<button onclick="${k<0?"openMenu('info','skills')":`openMenu('skillDetail',${k})`}" aria-label="슬롯 ${i+1} ${k<0?'비어 있음':SK[k][0]}">${art(k<0?'skills':'s'+k%10)}<span class="slot-number">${i+1}</span><small>${k<0?'빈 슬롯':'Lv.'+s.skills[k]}</small></button>`).join('')}</div><div class="summary-strip">보유 스킬 ${Object.keys(s.skills).length}/${SK.length}<b>스킬 조각 ${num(s.shards)}</b></div><div class="filter-chips">${['전체','무속성','화염','냉기','신성','암흑'].map(t=>`<button class="${screenFilter===t?'active':''}" onclick="setFilter('${t}')">${t}</button>`).join('')}</div><div class="item-grid">${list.map(i=>`<button class="item-card ${s.slots.includes(i)?'equipped':''} ${s.skills[i]?'':'locked'}" onclick="openMenu('skillDetail',${i})">${art('s'+i%10)}${s.slots.includes(i)?'<span class="item-tag">장착</span>':''}<b>${SK[i][0]}</b><small>${s.skills[i]?'Lv.'+s.skills[i]:'미습득'}</small></button>`).join('')}</div><div class="action-row sticky-actions"><button class="gold-button purple" onclick="autoEquipSkills()">추천 장착</button><button class="gold-button" onclick="levelAllSkills(false)">일괄 강화</button><button class="gold-button purple" onclick="switchScreenTab('summon')">스킬 소환</button></div>`};
autoEquipSkills = function autoEquipSkills(){const learned=Object.keys(s.skills).map(Number).sort((a,b)=>s.skills[b]-s.skills[a]);s.slots=Array.from({length:4},(_,i)=>learned[i]??-1);cooldowns=cooldowns.map(x=>Math.max(5,x));paint();save();notice('레벨이 높은 스킬을 장착했습니다')};
forgeScreen = function forgeScreen(){return `<div class="forge-showcase"><button class="muted-button" onclick="openMenu('forgeRates')">등급 확률 <ui-mark data-shape=info aria-hidden=true></ui-mark></button>${art('forge')}<strong>천공의 모루 Lv.${s.forgeLevel}</strong><small>${s.forgeLevel===FORGE_MAX_LEVEL?'모든 등급이 해금되었습니다':RAR[unlockedR()]+' 등급까지 제작 가능'}</small></div><div class="forge-experience"><div class="between"><span>모루 경험치</span><b>${s.forgeLevel===FORGE_MAX_LEVEL?'MAX':num(s.forgeExp)+' / '+num(NEED[s.forgeLevel-1])}</b></div><div class="bar"><i style="width:${s.forgeLevel===FORGE_MAX_LEVEL?100:s.forgeExp/NEED[s.forgeLevel-1]*100}%"></i></div></div><div class="resource-note">${art('ore')}보유 성운석 <b>${num(s.ore)}</b></div><div class="forge-actions">${[1,10,100].map(n=>`<button class="gold-button ${n===1?'purple':''}" onclick="make(${n})" ${s.ore<1?'disabled':''}>${n}회 제작<span>${art('ore')}${n}</span></button>`).join('')}</div><div class="action-row"><button class="muted-button" onclick="openMenu('forgeRates')">모루 성장 · 확률 보기</button><button class="muted-button" onclick="openMenu('inventory')">장비 가방</button></div><div class="toggle-list"><label>더 강한 장비 자동 장착<input type="checkbox" ${s.autoEquip?'checked':''} onchange="s.autoEquip=this.checked;save()"></label><label>일반 · 매직 자동 분해<input type="checkbox" ${s.autoSalvage?'checked':''} onchange="s.autoSalvage=this.checked;save()"></label></div><p class="small">모루 레벨이 오르면 상위 등급 장비를 제작할 수 있습니다.</p>`};
forgeProb = function forgeProb(level){const max=level>=20?10:level>=18?9:level>=15?8:level>=12?7:level>=9?6:level>=7?5:level>=5?4:level>=3?3:level>=2?2:1;const sum=Array.from({length:max+1},(_,i)=>Math.pow(2.9,max-i)).reduce((a,b)=>a+b,0);return RAR.map((_,i)=>i>max?0:Math.pow(2.9,max-i)/sum*100)};
forgeBoostCost = function forgeBoostCost(){return 120+s.forgeLevel*s.forgeLevel*40};
boostForge = function boostForge(){if(s.forgeLevel>=FORGE_MAX_LEVEL){notice('최대 레벨입니다');return}const cost=forgeBoostCost();if(s.gold<cost){notice('골드가 부족합니다');return}s.gold-=cost;s.forgeExp+=20;s.forgeBoosts=(s.forgeBoosts||0)+1;while(s.forgeLevel<FORGE_MAX_LEVEL&&s.forgeExp>=NEED[s.forgeLevel-1]){s.forgeExp-=NEED[s.forgeLevel-1];s.forgeLevel++}paint();save();notice('모루 경험치 +20');playSound('reward')};
forgeRatesPopup = function forgeRatesPopup(){const current=forgeProb(s.forgeLevel),next=forgeProb(Math.min(FORGE_MAX_LEVEL,s.forgeLevel+1));return `<div class="prob-head"><b>장비 등급</b><b>현재 Lv.${s.forgeLevel}</b><b>다음 ${s.forgeLevel===FORGE_MAX_LEVEL?'MAX':'Lv.'+(s.forgeLevel+1)}</b></div>${RAR.map((name,i)=>`<div class="prob-row"><span class="rar${i}">${name}</span><span>${current[i].toFixed(3)}%</span><strong>${next[i].toFixed(3)}%</strong></div>`).join('')}<div class="card" style="margin-top:12px;margin-bottom:3px"><div class="between"><b>모루 경험치</b><span class="small">${s.forgeLevel===FORGE_MAX_LEVEL?'MAX':num(s.forgeExp)+' / '+num(NEED[s.forgeLevel-1])}</span></div><div class="bar"><i style="width:${s.forgeLevel===FORGE_MAX_LEVEL?100:s.forgeExp/NEED[s.forgeLevel-1]*100}%"></i></div><div class="action-row"><button class="gold-button" onclick="boostForge()" ${s.forgeLevel>=FORGE_MAX_LEVEL||s.gold<forgeBoostCost()?'disabled':''}>경험치 +20 · ${compact(forgeBoostCost())} 골드</button></div><p class="small">보유 골드 ${num(s.gold)} · 제작 1회당 경험치 1도 획득합니다.</p></div>`};
dungeonScreen = function dungeonScreen(){if(screenTab==='records')return `<div class="section-label"><span>던전 진행 기록</span><small>단계별 기록</small></div>${['황금 광산','고대 무기고','마법 도서관'].map((name,i)=>`<div class="pass-row">${art('dungeon'+i)}<div><strong>${name}</strong><small>최고 도전 ${s.dungeonLevel[i]}단계 · 클리어 ${(s.dungeonWins||[])[i]||0}회</small></div><b>${s.tickets[i]}장</b></div>`).join('')}<div class="card"><h3>내일의 도전</h3><p>매일 기기 시간 0시, 던전별 입장권 2장 충전</p></div>`;return `<div class="resource-note">남은 입장권 <b>${s.tickets.reduce((a,b)=>a+b,0)}장</b><span class="small">매일 자정 충전</span></div>${['황금 광산','고대 무기고','마법 도서관'].map((name,i)=>`<article class="dungeon-banner">${art('dungeon'+i)}<div><h3>${name}</h3><p>${s.dungeonLevel[i]}단계 · 입장권 ${s.tickets[i]}/2</p><small>보상 ${['골드','성운석','스킬 조각'][i]} ${num([500,15,12][i]*s.dungeonLevel[i])}</small><button class="gold-button" onclick="startDungeon(${i})" ${s.tickets[i]<=0||dungeonRun?'disabled':''}>도전하기</button></div></article>`).join('')}<div class="small" style="text-align:center">40초 안에 수호자를 쓰러뜨리세요.<br>입장 시 입장권 1장을 사용합니다.</div>${dungeonRun?'<div class="action-row"><button class="gold-button" onclick="navigate(\'home\')">전투로 돌아가기</button><button class="gold-button purple" onclick="finishDungeon(false)">도전 포기</button></div>':''}`};
startDungeon = function startDungeon(i){if(dungeonRun||s.tickets[i]<=0){notice('입장할 수 없습니다');return}navigate('home');dungeon(i)};
shopScreen = function shopScreen(){if(screenTab==='pass')return passPopup();if(screenTab==='summon')return summonScreen('all');return `<div class="shop-banner">${art('shop')}<div><h3>별빛 교환소</h3><p>모험에서 얻은 재화로<br>다음 성장을 준비하세요.</p></div></div><div class="offer-grid"><div class="offer-card"><small>하루 한 번</small><strong>오늘의 모험 선물</strong>${art('gem')}<button class="gold-button" onclick="claimShopDaily()" ${s.daily.shopGift?'disabled':''}>${s.daily.shopGift?'수령 완료':'무료 · 다이아 30'}</button></div>${[['ore',30,100,'성운석 30','ore'],['ore',100,300,'성운석 100','ore'],['stones',50,100,'강화석 50','stone'],['shards',10,120,'스킬 조각 10','shard'],['gold',2000,100,'골드 2,000','coin']].map(([k,n,c,name,a])=>`<div class="offer-card"><small>재화 교환</small><strong>${name}</strong>${art(a)}<button class="gold-button purple" onclick="buy('${k}',${n},${c})" ${s.gems<c?'disabled':''}>다이아 ${num(c)}</button></div>`).join('')}</div><p class="small" style="text-align:center;margin-top:15px">보유 다이아 ${num(s.gems)}</p>`};
claimShopDaily = function claimShopDaily(){resetDay();if(s.daily.shopGift){notice('오늘의 선물을 이미 받았습니다');return}if(saveGuard.usesServer())return claimAccountReward('shopDaily','gems');s.daily.shopGift=true;s.gems+=30;paint();save();notice('오늘의 선물 · 다이아 +30');playSound('reward')};
summonScreen = function summonScreen(kind){return `<div class="resource-note">${art('gem')}보유 다이아 <b>${num(s.gems)}</b></div><div class="forge-showcase" style="background:radial-gradient(ellipse at 50% 50%,#63418b88,#20182c)">${art('skills','large-relic')}<strong>성운의 스킬 소환</strong><small>스킬 1종과 조각 5개를 획득합니다.</small><div class="action-row"><button class="gold-button purple" onclick="summon(1)" ${s.gems<150?'disabled':''}>1회 · 150</button><button class="gold-button" onclick="summon(10)" ${s.gems<1350?'disabled':''}>10회 · 1,350</button></div></div><p class="small" style="text-align:center">13개 스킬 중 무작위 획득 · 중복 시 스킬 조각 지급</p>${kind==='all'?`<div class="forge-showcase" style="margin-top:18px;background:radial-gradient(ellipse at 50% 60%,#6e405b88,#22192e)"><div class="paperdoll" style="height:145px;width:190px;margin:auto"></div><strong>별의 스킨 소환</strong><small>100회마다 천상의 용사 확정</small><div class="action-row"><button class="gold-button purple" onclick="rollCostume(1)" ${s.gems<300?'disabled':''}>1회 · 300</button><button class="gold-button" onclick="rollCostume(10)" ${s.gems<2700?'disabled':''}>10회 · 2,700</button></div></div><p class="small" style="text-align:center">각 스킨 확률 12.5% · 누적 ${s.rolls}회<br>중복 스킨은 강화석 10개로 지급됩니다.</p>`:''}`};
skillDetail = function skillDetail(k){openMenu('skillDetail',k)};
skillPopup = function skillPopup(){const k=Number(tab),lv=s.skills[k]||0,slot=s.slots.indexOf(k);return `<div class="popup-hero">${art('s'+k%10)}<div><span class="badge">${SKILL_TYPES[k]} · ${slot>=0?'슬롯 '+(slot+1)+' 장착':'미장착'}</span></div><h3>${SK[k][0]}</h3><p>Lv.${lv} / 100</p><p>${lv?'공격력의 '+Math.round((2+lv*.15)*100)+'% 피해':'스킬 조각 10개로 습득할 수 있습니다.'}</p></div><div class="effect-table"><div><span>현재 스킬 피해</span><b>${lv?Math.ceil(power()*(2+lv*.15)).toLocaleString('ko-KR'):'미습득'}</b></div><div><span>다음 레벨</span><b>${Math.ceil(power()*(2+Math.min(100,lv+1)*.15)).toLocaleString('ko-KR')}</b></div><div><span>보유 스킬 조각</span><b>${num(s.shards)}</b></div></div><div class="action-row"><button class="gold-button" onclick="skillLevel(${k})" ${s.shards<10||lv>=100?'disabled':''}>${lv?'강화':'습득'} · 조각 10</button><button class="gold-button purple" onclick="slotSkill(${k})" ${!lv||slot>=0?'disabled':''}>${slot>=0?'장착 중':'장착'}</button></div>`};
slotSkill = function slotSkill(k){if(!s.skills[k]){notice('스킬을 먼저 습득하세요');return}if(s.slots.includes(k)){notice('이미 장착한 스킬입니다');return}openMenu('slot',k)};
slotPopup = function slotPopup(){const k=Number(tab);return `<p class="small" style="text-align:center">${SK[k][0]}을 장착할 슬롯을 선택하세요.</p>${s.slots.map((v,i)=>`<div class="pass-row">${art(v<0?'skills':'s'+v%10)}<div><strong>슬롯 ${i+1}</strong><small>${v<0?'빈 슬롯':SK[v][0]+' Lv.'+s.skills[v]}</small></div><button class="gold-button" onclick="setSlot(${i},${k})">선택</button></div>`).join('')}`};
setSlot = function setSlot(slot,k){if(!s.skills[k]||slot<0||slot>3)return;s.slots[slot]=k;cooldowns[slot]=Math.max(5,cooldowns[slot]);closeMenu();paint();save();notice(SK[k][0]+' 장착 완료')};
inventoryPopup = function inventoryPopup(){const list=[...s.gear].filter(g=>inventoryPart<0||g.p===inventoryPart).sort((a,b)=>b.r-a.r||b.plus-a.plus);return `<div class="filter-chips"><button class="${inventoryPart<0?'active':''}" onclick="inventoryFilter(-1)">전체</button>${PARTS.map((n,i)=>`<button class="${inventoryPart===i?'active':''}" onclick="inventoryFilter(${i})">${n}</button>`).join('')}</div><div class="between"><span class="small">보유 ${s.gear.length}/${GEAR_CAPACITY}</span><button class="muted-button" onclick="salvageLow()">일반 · 매직 분해</button></div><div class="item-grid">${list.map(g=>`<button class="item-card ${s.equipped[g.p]===g.id?'equipped':''}" onclick="openMenu('gearDetail','${g.id}')">${gearArt(g)}${s.equipped[g.p]===g.id?'<span class="item-tag">착용</span>':''}<b class="rar${g.r}">${equipmentTitle(g)}</b><small>${RAR[g.r]} · +${g.plus}</small></button>`).join('')}</div>${!list.length?'<div class="empty-state">이 부위의 장비가 없습니다.</div>':''}`};
inventoryFilter = function inventoryFilter(i){inventoryPart=i;refreshBagFilter()};
gearPopup = function gearPopup(){const g=s.gear.find(g=>g.id===tab);if(!g)return '<div class="empty-state">분해되어 가방에서 제거된 장비입니다.</div>';const equipped=s.equipped[g.p]===g.id,cost=10*(g.plus+1)*(g.r+1);return `<div class="popup-hero">${gearArt(g)}<div><span class="badge rar${g.r}">${RAR[g.r]} · ${equipped?'착용 중':'보관 중'}</span></div><h3>${equipmentTitle(g)} +${g.plus}</h3><p>장비 효과 ${Math.floor((g.r+1)*12*(1+g.plus*.2))}</p></div><div class="effect-table"><div><span>다음 강화 효과</span><b>${Math.floor((g.r+1)*12*(1+Math.min(15,g.plus+1)*.2))}</b></div><div><span>보유 강화석</span><b>${num(s.stones)}</b></div></div><div class="action-row"><button class="gold-button" onclick="improve('${g.id}')" ${g.plus>=15||s.stones<cost?'disabled':''}>${g.plus>=15?'최대 강화':'강화 · '+num(cost)+'석'}</button><button class="gold-button purple" onclick="equip('${g.id}')" ${equipped?'disabled':''}>${equipped?'착용 중':'장착'}</button></div>${!equipped?`<div style="text-align:center;margin-top:12px"><button class="muted-button" onclick="salvage('${g.id}');closeMenu()">분해 · 강화석 ${((g.r+1)*5+g.plus*3)}</button></div>`:'<p class="small" style="text-align:center">착용 중인 장비는 분해할 수 없습니다.</p>'}`};
relicPopup = function relicPopup(){const i=Number(tab),lv=s.relics[i],cost=5+lv*2,unlocked=s.maxStage>=REL[i][2],factor=[4,4,2.5,3][i];return `<div class="popup-hero">${art('relic'+i)}<div><span class="badge">${unlocked?'유물 Lv.'+lv:'STAGE '+stageText(REL[i][2])+' 해금'}</span></div><h3>${REL[i][0]}</h3></div><div class="effect-table"><div><span>${['공격력','체력','스킬 피해','골드 획득'][i]}</span><b>+${lv*factor}% → +${Math.min(50,lv+1)*factor}%</b></div><div><span>보유 조각</span><b>${num(s.shards)}</b></div></div><div class="action-row"><button class="gold-button" onclick="relicLevel(${i})" ${!unlocked||lv>=50||s.shards<cost?'disabled':''}>${!unlocked?'스테이지 미달':lv>=50?'최대 레벨':'강화 · 조각 '+cost}</button></div>`};
attendancePopup = function attendancePopup(){const cycle=s.attendance%7,done=s.lastAttendance===today(),claimedCount=done&&cycle===0?7:cycle;return `<p class="small" style="text-align:center;margin:1px 0 14px">매일 빛나는 보상 · 누적 출석 ${s.attendance}일</p><div class="attendance-grid">${ATT.map(([_,n],i)=>`<div class="day-card ${i<claimedCount?'claimed':''} ${!done&&i===cycle?'today':''} ${i===6?'final-day':''}"><strong>${i+1}일차</strong>${art(['gem','ore','ticket','gem','shard','ticket','gem'][i])}<b>${num(n)}</b><small>${['다이아','성운석','스킬북','다이아','스킬 조각','입장권','다이아'][i]}</small></div>`).join('')}</div><div class="action-row" style="margin-top:15px"><button class="gold-button" onclick="claimAttendance()" ${done?'disabled':''}>${done?'오늘 보상 수령 완료':'오늘의 보상 받기'}</button></div>`};
questsPopup = function questsPopup(){const daily=tab==='daily';return `<div class="tabs"><button class="${!daily?'active':''}" onclick="switchTab('main')">진행 퀘스트</button><button class="${daily?'active':''}" onclick="switchTab('daily')">일일 미션</button></div>${daily?[['kills','몬스터 처치',30],['crafted','장비 제작',10],['upgrades','능력 강화',5],['dungeons','던전 클리어',1]].map(([key,name,goal])=>`<div class="card"><h3>${name}</h3><div class="between"><span class="small">${Math.min(s.daily[key]||0,goal)} / ${goal}</span><b>다이아 50</b></div><div class="bar"><i style="width:${Math.min(100,(s.daily[key]||0)/goal*100)}%"></i></div><div class="action-row"><button class="gold-button" onclick="dailyClaim('${key}')" ${s.daily.claimed[key]||(s.daily[key]||0)<goal?'disabled':''}>${s.daily.claimed[key]?'수령 완료':'보상 받기'}</button></div></div>`).join(''):mainQuestPopup()}`};
mainQuestPopup = function mainQuestPopup(){const q=Q[s.quest],[v,max]=questProgress(s.quest);if(!q)return '<div class="empty-state">모든 진행 퀘스트를 완료했습니다.</div>';return `<div class="popup-hero">${art('quests')}<div><span class="badge">${s.quest+1} / 22</span></div><h3>${q[0]}</h3></div><div class="bar"><i style="width:${Math.min(100,v/max*100)}%"></i></div><div class="between"><span class="small">${Math.min(v,max)} / ${max}</span><b style="color:#e1c896">${orderRewardText(growthQuestReward(s.quest))}</b></div><div class="action-row"><button class="gold-button" onclick="claimQuest()" ${!q[1]()?'disabled':''}>보상 받기</button><button class="gold-button purple" onclick="questDestination()">목표로 이동</button></div>`};
questDestination = function questDestination(){const text=Q[s.quest]?.[0]||'';if(text.includes('제작')||text.includes('모루'))navigate('forge');else if(text.includes('공격'))navigate('character','growth');else navigate('home')};
passPopup = function passPopup(){return `<div class="shop-banner">${art('pass')}<div><h3>성장 패스</h3><p>최고 STAGE ${stageText(s.maxStage)}<br>모험의 발자취가 보상이 됩니다.</p></div></div>${[5,10,20,30,50,75,100,150].map((n,i)=>`<div class="pass-row">${art('gem')}<div><strong>STAGE ${stageText(n)}</strong><small>다이아 ${50+i*25}</small></div><button class="gold-button ${s.maxStage<n?'purple':''}" onclick="claimPass(${n},${50+i*25})" ${s.passClaimed[n]||s.maxStage<n?'disabled':''}>${s.passClaimed[n]?'완료':s.maxStage<n?'진행 중':'수령'}</button></div>`).join('')}`};
rankingPopup = function rankingPopup(){return rankBoard.panel()};
eventPopup = function eventPopup(){return `<div class="popup-hero">${art('event')}<h3>성운기사의 모험</h3><p>오늘의 선물을 확인하고 성장을 이어가세요.</p></div><div class="menu-directory"><button onclick="openMenu('attendance')">${art('attendance')}출석 보상</button><button onclick="openMenu('pass')">${art('pass')}성장 패스</button><button onclick="openMenu('quests','daily')">${art('quests')}일일 미션</button></div>`};
morePopup = function morePopup(){return `<div class="menu-directory">${[['attendance','출석','attendance'],['quests','퀘스트','quests'],['pass','성장 패스','pass'],['relics','유물','relics'],['costume','스킨','costume'],['collection','도감','collection'],['ranking','랭킹','ranking'],['vip','모험 VIP','vip'],['settings','설정','settings']].map(([k,n,a])=>`<button onclick="openMenu('${k}')">${art(a)}${n}</button>`).join('')}</div>`};
infoPopup = function infoPopup(){const text={character:'장비를 누르면 강화와 장착 창이 열립니다. 아래 탭에서 성장·유물·스킨·도감을 전환할 수 있습니다.',forge:'성운석을 사용해 장비를 제작합니다. 제작 경험치로 모루가 성장하며, 등급 확률 버튼에서 현재와 다음 레벨을 비교할 수 있습니다.',skills:'스킬을 눌러 습득·강화·장착하세요. 최대 4개를 장착할 수 있으며, 재사용 시간은 슬롯에 따라 5·8·11·14초입니다.',dungeon:'각 던전은 입장권 1장으로 도전합니다. 40초 안에 수호자를 처치하면 보상을 받고 다음 난이도가 열립니다.',shop:'모험에서 얻은 다이아를 재료로 교환합니다. 매일 무료 선물을 받을 수 있으며, 소환·성장 패스는 아래 탭에서 열 수 있습니다.',home:'자동 전투로 스테이지를 돌파하세요. 화면 아래 버튼을 눌러 캐릭터·제작·스킬·던전·상점으로 이동할 수 있습니다.'};return `<div class="card"><h3>${SCREEN_META[tab]?.[0]||'모험'} 안내</h3><p>${text[tab]||text.home}</p><p class="small">뒤로 가기는 이전 창, 모험은 전투 화면으로 이동합니다.</p></div>`};
'use strict';
