const SCREEN_TABS={character:[['equipment','장비'],['growth','성장'],['relics','유물'],['costume','스킨'],['collection','도감']],skills:[],forge:[['craft','장비 제작']],dungeon:[['challenges','일일 던전'],['records','도전 기록']],shop:[['exchange','재화 교환'],['summon','소환'],['pass','성장 패스']]};
const SHORTCUTS={growth:['character','growth'],equipment:['character','equipment'],relics:['character','relics'],costume:['character','costume'],collection:['character','collection'],forge:['forge','craft'],skills:['skills','library'],dungeon:['dungeon','challenges'],shop:['shop','exchange']};


