 attendance:'attendance',relicDetail:'relics',pass:'pass',passExchange:'pass',event:'event',
 petDetail:'pets',petRates:'pets',petSummonResult:'pets',costumeDetail:'costume',
 normalSkin:'costume',normalCostumeRates:'costume',collectionPart:'collection',collectionItem:'collection',
 mineExit:'mine',ranking:'ranking',guildMember:'guild',guildNotice:'guild',
 guildLeave:'guild',havenShop:'havenShop',wbRanks:'worldBoss',wbRewards:'worldBoss',
 raidComing:'partyRaid',partyRaidHelp:'partyRaid',royalEvent:'roulette',royalRates:'roulette',
 royalSlot:'roulette',wheelMissions:'roulette',dungeonResult:'material'
