forgeProb = function forgeProb(level){level=Math.max(1,Math.min(FORGE_MAX_LEVEL,level));const keys=Object.keys(FORGE_ANCHORS).map(Number),lo=Math.max(...keys.filter(k=>k<=level)),hi=Math.min(...keys.filter(k=>k>=level)),t=lo===hi?0:(level-lo)/(hi-lo);const raw=RAR.map((_,i)=>FORGE_UNLOCK[i]>level?0:(FORGE_ANCHORS[lo][i]||0)*(1-t)+(FORGE_ANCHORS[hi][i]||0)*t);const sum=raw.reduce((a,b)=>a+b,0);return raw.map(x=>x*100/sum)};
