forgeCraft = function forgeCraft(n,quiet=false){if(!Number.isFinite(n)||n<1)return 0;const room=Math.max(0,GEAR_CAPACITY-s.gear.length);if(!room){if(!quiet)notice('장비 가방이 가득 찼습니다. 장비를 정리한 뒤 제작하세요');return 0}const count=Math.min(Math.floor(n),Math.floor(s.ore),100,room);if(count<=0){if(!quiet)notice('성운석이 부족합니다');return 0}lastLoot=[];for(let i=0;i<count;i++){s.ore--;s.crafted++;const g={id:'g_'+Date.now().toString(36)+'_'+s.crafted+'_'+i,p:1+Math.floor(Math.random()*6),r:rollR(),plus:0,set:rollCraftSet(),locked:false};lastLoot.push(obtainGear(g));advanceForge(1)}s.lastLoot=lastLoot;trackOrderEvent('crafted',count);s.daily.crafted=(s.daily.crafted||0)+count;s.weekly.crafted=(s.weekly.crafted||0)+count;paint();save();if(!quiet){playSound('forge');openMenu('loot')}return count};
