rewardsHTML = function rewardsHTML(r){return `<div class="reward-chips">${Object.entries(r).filter(([,n])=>n>0).map(([k,n])=>`<span>${art(RESOURCE_ART[k]||'gem')}<b>${num(n)}</b><small>${RESOURCE_NAMES[k]||k}</small></span>`).join('')}</div>`};
backContent = function backContent(){return `<button class="muted-button content-back" onclick="navigate('dungeon','content')"><ui-mark data-shape=chevron-left aria-hidden=true></ui-mark> 모험 콘텐츠 목록</button>`};
showcasePopup = function showcasePopup(){return `<div class="summary-strip">영구 공격력 <b>+${(s.showcase.reduce((a,b)=>a+b,0)*.1).toFixed(1)}%</b></div><p class="small">미착용 장비를 소모해 영구 보너스를 얻습니다.</p>${PARTS.map((n,i)=>`<div class="pass-row">${art('gear'+i)}<div><strong>${n} 진열장</strong><small>${s.showcase[i]}점 · 공격력 +${(s.showcase[i]*.1).toFixed(1)}%</small></div></div>`).join('')}<div class="action-row">${button('가방에서 등록할 장비 선택',"openMenu('inventory')")}</div>`};
showcaseConfirm = function showcaseConfirm(){const g=s.gear.find(x=>x.id===tab);if(!g)return '<p>장비가 없습니다.</p>';return `<div class="popup-hero">${gearArt(g)}<h3>${equipmentTitle(g)} +${g.plus}</h3>${isNewDiscovery(g.p,g.r)?'<p class="small">NEW · 도감 발견 보상 수령 가능</p>':''}<p>이 장비를 소모하고<br>공격력 +${((g.r+1)*.1).toFixed(1)}%를 영구 획득합니다.</p></div><div class="action-row">${button('등록 · 장비 소모',`showcaseGear('${g.id}');closeMenu()`)}${button('취소','closeMenu()',false,true)}</div>`};
forgePreview = function forgePreview(d){forgePreviewLevel=Math.max(1,Math.min(FORGE_MAX_LEVEL,(forgePreviewLevel||s.forgeLevel)+d));render()};
relicEffectText = function relicEffectText(i,lv){return ['공격력 +'+lv*3+'%','체력 +'+lv*4+'%','스킬 피해 +'+lv*3+'%','골드 +'+lv*3+'% · 치명타 +'+(lv*.5).toFixed(1)+'%p','공격속도 +'+lv+'%','방어 관통력 +'+(lv*.2).toFixed(1)+'%p','오프라인 시간 +'+lv*6+'분','치명타 피해 +'+lv+'%'][i]};
petsScreen = function petsScreen(){return `<div class="pet-showcase">${art('pet')}<h3>${s.activePet<0?'함께할 별의 동료':PETS[s.activePet]}</h3><p>${s.activePet<0?'아기용을 소환해 모험을 함께하세요.':'Lv.'+s.pets[s.activePet]+' · 공격력·골드 +'+(petHoldingBonus()*100).toFixed(1)+'%'}</p></div><div class="action-row">${button('펫 소환 · 다이아 200','animatePetSummon()',s.gems<200)}</div><p class="small">중복 1개당 동료 조각 10~20개</p><div class="item-grid">${PETS.map((n,i)=>`<button class="item-card ${s.pets[i]?'':'locked'} ${s.activePet===i?'equipped':''}" onclick="openMenu('petDetail',${i})"><span style="filter:hue-rotate(${i*55}deg)">${art('pet')}</span><b>${n}</b><small>${s.pets[i]?'Lv.'+s.pets[i]:'미보유'}</small></button>`).join('')}</div>`};
petDetail = function petDetail(){
 const i=Number(tab),p=COMPANIONS[i];if(!p)return '';
 const lv=s.pets[i]||0,next=lv>0&&lv<50,cost=petCost(i);
 const previewLevel=lv||1;
 const row=(label,read,kind)=>`<div><span>${label}</span><b>+${petEffectText(kind,read(previewLevel))}${next?' <i>→</i> +'+petEffectText(kind,read(lv+1)):''}</b></div>`;
 const heldRow=row('공격력·골드',level=>petHoldingEffect(i,level));
 const activeRows=Object.keys(p[2]).map(kind=>row(PET_EFFECT_LABELS[kind],level=>petEffectValue(i,kind,level),kind)).join('');
 const buttonText=!lv?'미보유':lv>=50?'최대 강화':'강화 · '+cost+'개';
 return petMaterialHUD(i)+`<div class="ability-sheet pet-sheet" style="--rim:${petTier(i).color}">${petArt(i)}<div><small>${petTier(i).name}</small><h3>${p[0]}</h3><b>${lv?'Lv.'+lv:'미보유'}</b></div></div>
 <div class="pet-effect-heading">${next?'현재 → 다음 레벨':lv?'현재 효과':'획득 시 효과'}</div>
 <div class="effect-table pet-effects"><h4>보유 효과 <small>수집 시 상시 적용</small></h4>${heldRow}<h4>동행 효과 <small>${s.activePet===i?'적용 중':'동행 시 적용'}</small></h4>${activeRows}</div>
 <div class="action-row">${button(s.activePet===i?'동행 중':'동행하기','equipPet('+i+')',!lv||s.activePet===i,true)}${button(buttonText,'levelPet('+i+')',!next||s.petShards<cost)}</div>`;
};
contentHub = function contentHub(){return ['mine','explore'].map(k=>dungeonBanner(k)).join('')};
mineScreen = function mineScreen(){return mineScene.render()};
expeditionScreen = function expeditionScreen(){return backContent()+`<div class="shop-banner">${art('explore')}<div><h3>별길 탐험대</h3><p>최대 3개 지역 동시 파견<br>접속하지 않아도 시간이 흐릅니다.</p></div></div>${EXPEDITIONS.map(([name,hours,days,a],i)=>{const e=s.expeditions[i],ready=e&&Date.now()>=e.end,available=days.includes(new Date().getDay());return `<div class="card expedition-card">${art(a)}<div><h3>${name}</h3><small>${hours}시간 · ${days.length===7?'매일':days.map(d=>'일월화수목금토'[d]).join('·')}</small><p data-expedition-clock="${i}">${e?durationLeft(e.end-Date.now()):available?'파견 가능':'오늘은 휴식 중'}</p></div>${rewardsHTML(expeditionRewards(hours))}<div class="action-row">${e?`<button id="expClaim${i}" class="gold-button" onclick="claimExpedition(${i})" ${ready?'':'disabled'}>탐험 보상 수령${rewardDot('explore:'+i)}</button>`:button('파견',`sendExpedition(${i})`,!available)}</div></div>`}).join('')}`};
rushScreen = function rushScreen(){return `<button class="muted-button content-back" onclick="navigate('dungeon','challenges')"><ui-mark data-shape=chevron-left aria-hidden=true></ui-mark> 던전 목록</button>`+`<div class="content-hero">${art('dungeon2')}<h2>보스 러시</h2><p>60초 동안 보스에게 준 피해를 합산합니다.</p></div>${recommendedPowerHTML(rushRecommendedPower(),'시작 보스 기준 · 자동 조정')}${entrySummary('rush')}<div class="effect-table"><div><span>최고 누적 피해</span><b>${compact(s.rushBest)}</b></div><div><span>이번 주 누적 피해</span><b>${compact(s.rushWeekly)}</b></div></div><div class="action-row">${button(entryButton('rush','러시 시작'),'startRush()',!!dungeonRun||!entryAvailability('rush').can)}</div><p class="small">입장권 1장 소모. 돌파 수에 따라 다이아·소환권 지급.</p>`};
dungeonFollowup = function dungeonFollowup(r){
 if(!r||!['daily','rush'].includes(r.mode))return null;
 const daily=r.mode==='daily',n=daily&&r.win?r.n+1:r.n;
 const label=daily?n+'단계 '+(r.win?'도전':'재도전'):'러시 재도전';
 const can=entryAvailability(daily?MATERIAL_ENTRIES[r.i]:'rush').can;
 const action=can?label:'입장권 부족';
 return {label:daily?materialEntryLabel(r.i,n,action):action,disabled:!can,n};
};
continueDungeonResult = function continueDungeonResult(){
 const r=challengeResult;
 if(view!=='challengeResult'||dungeonRun||!r||!['daily','rush'].includes(r.mode))return false;
 resetDay();
 const next=dungeonFollowup(r);
 if(next.disabled)return false;
 if(r.mode==='daily'){s.dungeonSelected[r.i]=next.n;startDungeon(r.i)}
 else startRush();
 return !!dungeonRun;
};
challengePopup = function challengePopup(){const r=challengeResult;if(r?.mode==='trial')return trialResultPopup(r);const next=dungeonFollowup(r);if(!next)return '<p>도전 기록이 없습니다.</p>';return `<div class="popup-hero">${art('dungeon'+r.i)}<div class="badge">${r.mode==='rush'?'누적 피해 '+compact(r.damage):r.win?'CLEAR':'도전 종료'}</div><h3>${r.mode==='rush'?'보스 '+r.bosses+'마리 돌파':DUNGEON_NAMES[r.i]+' '+r.n+'단계'}</h3></div>${(r.win||Object.keys(r.rewards||{}).length)?rewardsHTML(r.rewards):r.abandoned?'<p class="small">전투를 포기했습니다.</p>':'<p class="small">시간 초과 또는 체력 소진으로 도전이 끝났습니다.</p>'}<div class="action-row">${button('확인','closeMenu()',false,true)}${button(next.label,'continueDungeonResult()',next.disabled||!!dungeonRun)}</div>` };
summonResult = function summonResult(){return drawResultPanel('skill',summonResults)};
summonRates = function summonRates(){return `<div class="effect-table">${SK.map(([n],i)=>{const t=SKILL_RULES[i].tier,c=SKILL_RULES.filter(r=>r.tier===t).length;return `<div><span>${n} · ${['하급','중급','상급'][t]}</span><b>${([70,25,5][t]/c).toFixed(3)}%</b></div>`}).join('')}</div><p class="small">10회 소환도 매회 개별 추첨합니다.</p>`};
costumeRoulette = function costumeRoulette(){return `<div class="resource-note">${art('rouletteCoin')}룰렛 코인 <b>${s.rouletteCoins}</b>${art('gem')}<b>${num(s.gems)}</b></div><div class="roulette-wheel"><div class="wheel-runes"><ui-mark data-shape=spark aria-hidden=true></ui-mark></div>${costumeSprite(s.wear)}</div><div class="summary-strip">전설 확정까지 <b>${100-s.rolls%100}회</b></div><div class="action-row">${button('1회 · 다이아 300','spinCostume(1)',s.gems<300,true)}${button('10회 · 다이아 2,700','spinCostume(10)',s.gems<2700)}</div><div class="action-row">${button('코인 1개','spinCostume(1,true)',s.rouletteCoins<1,true)}${button('코인 10개','spinCostume(10,true)',s.rouletteCoins<10,true)}</div><div class="probability-summary"><span>일반 <b>60%</b></span><span>희귀 <b>30%</b></span><span>영웅 <b>9%</b></span><span>전설 <b>1%</b></span></div><p class="small">등급 내 확률 동일 · 100회째 전설 확정 · 중복으로 별 강화</p><div class="action-row">${button('보유 스킨',"navigate('character','costume')",false,true)}</div>`};
spinCostume = function spinCostume(n,useCoin=false){return beginResultAction({kind:'costume',n,ticket:useCoin})};
costumeResult = function costumeResult(){return `<div class="loot-grid">${costumeResults.map(({i,result},j)=>`<div class="loot-card" style="--result-delay:${Math.min(j,8)*35}ms">${costumeSprite(i,'costume-result-hero')}<b>${COSTUME_NAMES[i]}</b><small>${TIER_NAMES[COSTUME_TIERS[i]]} · ${result}</small></div>`).join('')}</div>${resultFooter(currentResultAction('costumeResult'))}`};
passExchange = function passExchange(){return `<div class="summary-strip">보유 패스 코인 <b>${s.passCoins}</b></div>${PASS_COIN_OFFERS.map(([k,n,c])=>`<div class="pass-row">${art(RESOURCE_ART[k])}<div><strong>${RESOURCE_NAMES[k]} ${n}</strong><small>패스 코인 ${c}</small></div>${purchaseButton('교환',`buyItem('${k}',${n},${c},'passCoins')`,s.passCoins<c)}</div>`).join('')}`};
packageSection = function packageSection(title,offers){
 const cards=offers.map(([name,contents,price,stage,artKey])=>`<article class="offer-card package-card">
  <img class="package-loot-art" src="./assets/package-loot/${artKey}.webp" width="192" height="192" alt="" loading="lazy" decoding="async">
  <div class="package-description"><div class="package-heading"><strong>${name}</strong><b>${price}</b></div>
   ${stage>1?`<small>스테이지 ${stage} 해금</small>`:''}<p>${contents}</p></div></article>`).join('');
 return `<section class="package-section"><h2>${title}</h2><div class="offer-grid">${cards}</div></section>`;
};
packagesScreen = function packagesScreen(){
 const limited=PACKAGES.filter(([, , ,stage])=>stage===1);
 const milestones=PACKAGES.filter(([, , ,stage])=>stage>1).sort((a,b)=>a[3]-b[3]);
 return '<div class="card"><h3>패키지 안내</h3><p class="small">결제 연결 후 구매와 유료 보상 수령이 가능합니다.</p></div>'+
  packageSection('한정 구성',limited)+packageSection('스테이지 해금 패키지',milestones)+
  '<div class="action-row">'+button('누적 VIP 혜택',"openMenu('vip')",false,true)+'</div>';
};
missionCard = function missionCard(n,v,max,done,fn,reward){return `<div class="card"><h3>${n}</h3><div class="between"><small>${Math.min(v,max)} / ${max}</small><small>${reward}</small></div><div class="bar"><i style="width:${Math.min(100,v/max*100)}%"></i></div><div class="action-row">${button(done?'완료':'보상 수령',fn,done||v<max)}</div></div>`};
achievementsPopup = function achievementsPopup(){return ACTIVE_ACHIEVEMENT_IDS.map(i=>{const [type,name,n,reward]=ACHIEVEMENTS[i];return missionCard(name,achieveValue(type),n,!!s.achievements[i],`claimAchievement(${i})`,'칭호 · 다이아 '+reward)}).join('')};
sevenAttendance = function sevenAttendance(){
 const pending=s.attendanceBook.pending,paid=s.attendance%7;
 const claimed=!pending&&s.attendance>0&&paid===0?7:paid;
 return `<p class="monthly-caption">접속한 날마다 한 칸씩 진행됩니다.</p><div class="attendance-grid">${SEVEN_ATTENDANCE_REWARDS.map((reward,i)=>{
  const ready=i>=claimed&&i<claimed+pending;
  return `<div class="day-card ${i<claimed?'claimed':''} ${ready?'today':''} ${i===6?'final-day':''}"><strong>${i+1}일차</strong>${rewardsHTML(reward)}${ready?'<small>수령 가능</small>':''}</div>`;
 }).join('')}</div><div class="action-row">${button(attendanceButton(pending),'claimAttendance()',!pending)}</div>`;
};
selectMonthlyReward = function selectMonthlyReward(day){if(!Number.isInteger(day)||day<1||day>28)return false;selectedMonthReward=day;selectedMonthKey=attendanceDay().slice(0,7);render();return true};
monthAttendance = function monthAttendance(){
 const key=attendanceDay().slice(0,7),m=monthlyRecord(key),pending=monthlyPending(),carry=pending-(m.earned-m.count);
 if(selectedMonthKey!==key||!selectedMonthReward){selectedMonthKey=key;selectedMonthReward=m.count<m.earned?m.count+1:Math.max(1,m.count)}
 const selected=selectedMonthReward,reward=monthlyReward(selected,m);
 return `<div class="summary-strip">이번 달 출석 <b>${m.earned} / 28일</b></div><p class="monthly-caption">매 7일 특별 보너스 · 칸을 눌러 확인</p><div class="month-calendar monthly-rewards" role="group" aria-label="28일 월 출석 보상">${MONTHLY_ATTENDANCE_REWARDS.map((_,i)=>{
  const day=i+1,r=monthlyReward(day,m),entries=Object.entries(r),[resource,n]=entries[0],received=day<=m.count,ready=!received&&day<=m.earned;
  const label=received?'수령 완료':ready?'수령 가능':'예정';
  return `<button class="month-day ${received?'claimed':''} ${day%7===0?'special':''} ${selected===day?'selected':''} ${ready?'ready':''}" onclick="selectMonthlyReward(${day})" aria-pressed="${selected===day}" aria-label="${day}일차 · ${passRewardText(r)} · ${label}"><span class="month-day-number">${day}</span>${art(RESOURCE_ART[resource])}<b>${num(n)}</b><small>${received?'<ui-mark data-shape=check aria-hidden=true></ui-mark> 수령':ready?'받기':entries.length>1?'+1종':'예정'}</small></button>`;
 }).join('')}</div><p class="monthly-selection-line" aria-live="polite"><b>${selected}일차</b> ${passRewardText(reward)}${selected<=m.count?' · <ui-mark data-shape=check aria-hidden=true></ui-mark> 수령':selected<=m.earned?' · 수령 가능':''}${selected<=m.legacyCount?' · 업데이트 전에 수령한 기존 보상':''}</p>${carry?'<p class="monthly-caption">이전 달 미수령 '+carry+'일분 포함</p>':''}<div class="action-row">${button(!pending&&m.count===28?'이번 달 28일 완료':attendanceButton(pending),'claimMonthDay()',!pending)}</div><details class="monthly-totals"><summary>이번 달 전체 보상 구성</summary>${rewardsHTML(monthlyRewardTotals(m))}</details>`;
};
resourcePopup = function resourcePopup(){return `<div class="effect-table">${Object.entries(RESOURCE_NAMES).filter(([k])=>k!=='tickets'&&(k!=='costumeShards'||s[k]>0)).map(([k,n])=>`<div><span>${art(RESOURCE_ART[k])}${n}</span><b>${num(s[k])}</b></div>`).join('')}</div>`};
offlinePopup = function offlinePopup(){const r=s.offlineRewards,ready=r.seconds>0,used=s.daily.fastBattle||0;return `<div class="popup-hero offline-hero">${art('offlineChest')}<h3>모험가의 보물상자</h3><div class="offline-duration"><span>적립 시간</span><strong>${offlineTime()}</strong><small>최대 ${offlineTime(offlineCap())}</small></div></div>${rewardsHTML({gold:r.gold,ore:r.ore})}<div class="summary-strip">경험치 <b>+${num(r.xp)}</b>무기 숙련 <b>+${num(Math.floor(r.seconds/60))}</b></div><button class="gold-button profile-wide" onclick="claimOffline()" ${ready?'':'disabled'}>${ready?'오프라인 보상 수령':'적립된 보상 없음'}</button><p class="small offline-help">게임을 1분 이상 비우면 보상이 쌓입니다.</p><section class="offline-quick"><div><b>빠른 전투</b><span>30분 보상을 즉시 획득</span><small>오늘 ${used} / 5회 사용 · 오프라인 적립과 별개</small></div><button class="gold-button purple" onclick="askDiamondUse('빠른 전투',${FAST_BATTLE_OFFER.cost},()=>fastBattle())" ${transactionAttrs(s.gems<FAST_BATTLE_OFFER.cost||used>=FAST_BATTLE_OFFER.limit)}>${art('gem')} ${FAST_BATTLE_OFFER.cost}</button></section>`};
onlinePopup = function onlinePopup(){const text={guild:['길드','생성·가입, 최대 30명, 기부와 버프, 길드 보스·던전·상점·채팅'],raid:['월드 보스','서버 공용 HP, 하루 3회 도전, 누적 피해와 기여도 보상'],arena:['비동기 아레나','다른 플레이어의 저장 데이터와 대결, 티어·점수·시즌 보상']};const [n,d]=text[tab]||['온라인 연결','길드·월드 보스·아레나·온라인 랭킹·클라우드 저장'];return `<div class="popup-hero">${art('guild')}<h3>${n}</h3><p>${d}</p></div><div class="card"><h3>게임 서버 연결이 필요합니다</h3><p>현재 진행은 이 브라우저에 저장됩니다. 공용 보스·결제·광고 검증은 연결 전입니다.</p><p class="small">설정에서 진행 기록을 파일로 내보낼 수 있습니다.</p></div>`};
'use strict';
SCREEN_META.dungeon=['모험 콘텐츠','REALMS OF STARLIGHT','dungeon'];
SCREEN_TABS.character.push(['pets','펫']);
SCREEN_TABS.dungeon=[['challenges','던전'],['content','모험 콘텐츠'],['records','기록']];
SCREEN_TABS.shop=[['exchange','교환'],['summon','스킬 소환'],['costumes','스킨'],['packages','패키지']];
const oldCharacterScreen=characterScreen,oldEquipmentScreen=equipmentScreen,oldCollectionScreen=collectionScreen,oldForgeScreen=forgeScreen,oldMorePopup=morePopup,oldAttendancePopup=attendancePopup,oldRenderExpansion=render,oldInfoPopup=infoPopup;
let missionTab='daily',attendanceMode='seven',passMode='growth';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,fn,disabled=false,alt=false,guide='',transaction=false)=>`<button${guide?' data-guide="'+guide+'"':''} class="gold-button ${alt?'purple':''}" onclick="${fn}" ${/^(animateForge|animateSummon|animatePetSummon|animateMasterwork|spinCostume|repeatResult)\(/.test(fn)?'data-result-action':''} ${transaction?transactionAttrs(disabled):disabled?'disabled':''}>${label}${buttonRewardDot(fn)}</button>`;
const purchaseButton=(label,fn,disabled=false,alt=false)=>button(label,fn,disabled,alt,'',true);
const head=(title,desc='')=>`<div class="section-label"><span>${title}</span>${desc?'<small>'+desc+'</small>':''}</div>`;
const RESOURCE_NAMES={gold:'골드',gems:'다이아',ore:'성운석',stones:'강화석',shards:'스킬 조각',petShards:'동료 조각',relicShards:'유물 조각',summonTickets:'소환권',petTickets:'동료 소환권',rouletteCoins:'스킨 코인',costumeShards:'스킨 조각',passCoins:'패스 코인',tickets:'던전 입장권'};
const RESOURCE_ART={gold:'coin',gems:'gem',ore:'ore',stones:'stone',shards:'shard',petShards:'petShard',relicShards:'relicShard',summonTickets:'summonTicket',petTickets:'summonTicket',rouletteCoins:'rouletteCoin',costumeShards:'costumeShard',passCoins:'passCoin',tickets:'ticket'};


characterScreen=function(){if(screenTab==='pets')return petsScreen();return oldCharacterScreen()};
equipmentScreen=function(){return oldEquipmentScreen()+equippedSetSummary()+`<div class="action-row">${button('진열장',"openMenu('showcase')",false,true)}</div>`};
growthScreen=function(){return `<div class="summary-strip">공격력 <b>${compact(power())}</b> 체력 <b>${compact(health())}</b></div><div class="stat-chips"><div><small>치명타</small><b>${(criticalChance()*100).toFixed(1)}%</b></div><div><small>공격속도</small><b>${attackSpeed().toFixed(2)}×</b></div><div><small>컬렉션 레벨</small><b>${skillCollection()}</b></div></div>${head('기본 능력 강화')}<div class="batch-controls">${GROWTH_BATCHES.map(n=>`<button class="${s.growthBatch===n?'active':''}" onclick="growthBatch(${n})">×${n}</button>`).join('')}</div>${STAT_NAMES.map((n,i)=>`<div class="growth-row"><span class="growth-stat-icon">${growthStatIcon(i)}</span><div><b>${n} Lv.${s.stats[i]}</b><small>${['레벨당 공격력 +8%','레벨당 +2% · 최대 +200%','레벨당 획득량 +3%','레벨당 체력 +8%','레벨당 +1% · 최대 60%'][i]}</small></div>${button('강화<small>'+compact(statCost(i))+' 골드/회</small>',`upgrade(${i})`,s.gold<statCost(i))}</div>`).join('')}<div class="effect-table"><div><span>스킬 컬렉션 공격 보너스</span><b>+${(skillCollection()*.5).toFixed(1)}%</b></div><div><span>도감 공·체 보너스</span><b>+${(collectionBonus()*100).toFixed(1)}%</b></div><div><span>스킨 보유 보너스</span><b>+${(costumeBonus()*100).toFixed(1)}%</b></div></div>`};
gearPopup=function(){const g=s.gear.find(x=>x.id===tab);if(!g)return '<div class="empty-state">소모된 장비입니다.</div>';const c=upgradeCost(g),worn=s.equipped[g.p]===g.id,old=equippedItem(g.p),delta=gearValue(g)-gearValue(old);return `<div class="popup-hero">${gearArt(g)}<div class="badge rar${g.r}">${RAR[g.r]} · ${g.locked?'잠금':worn?'착용 중':'보관 중'}</div><h3>${equipmentTitle(g)} +${g.plus}</h3>${isNewDiscovery(g.p,g.r)?'<p class="small">NEW · 도감 발견 보상 수령 가능</p>':''}<p>${REGION_SETS[g.set]}</p></div><div class="effect-table"><div><span>장비 효과</span><b>${compact(gearValue(g))}</b></div><div><span>현재 착용 대비</span><b class="${delta>=0?'positive':'negative'}">${delta>=0?'+':''}${compact(Math.abs(delta))}</b></div><div><span>강화 비용</span><b>${compact(c.gold)} 골드${c.stones?' · '+c.stones+' 강화석':''}</b></div><div><span>보유 재료</span><b>${compact(s.gold)} 골드 · ${num(s.stones)} 강화석</b></div></div><div class="action-row">${button('1회 강화',`improve('${g.id}')`,g.plus>=15||s.gold<c.gold||s.stones<c.stones)}${button('최대 강화',`improve('${g.id}',true)`,g.plus>=15||s.gold<c.gold||s.stones<c.stones,true)}</div><div class="action-row">${button(worn?'착용 중':'장착',`equip('${g.id}')`,worn)}<button class="gear-lock-switch" role="switch" aria-checked="${!!g.locked}" aria-label="장비 잠금" onclick="toggleGearLock('${g.id}')"><span>장비 잠금</span>${switchFace(!!g.locked)}</button></div><div class="action-row">${button('분해',`salvage('${g.id}');closeMenu()`,worn||g.locked,true)}${button('진열장 등록',`openMenu('showcaseConfirm','${g.id}')`,worn||g.locked,true)}</div><p class="small">착용·잠금 장비는 소모되지 않습니다.</p>`};


collectionScreen=function(){return `<div class="summary-strip">도감 영구 보너스 <b>공·체 +${(collectionBonus()*100).toFixed(1)}%</b></div>`+oldCollectionScreen()};
forgeScreen=function(){if(screenTab==='records')return oldForgeScreen();return `<div class="forge-showcase"><button class="muted-button" onclick="forgePreviewLevel=s.forgeLevel;openMenu('forgeRates')">등급 확률 <ui-mark data-shape=info aria-hidden=true></ui-mark></button>${art('forge','forge-hd')}<strong>천공의 모루 Lv.${s.forgeLevel}</strong><small>무기를 제외한 6부위 · 10종 세트 랜덤 제작</small></div><div class="forge-random-note"><span>세트별 10% · 전 지역 공통</span><button class="muted-button" onclick="openMenu('equipmentSets')">세트 효과 보기 <ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></button></div><div class="forge-experience"><div class="between"><b>제작 경험치</b><span>${s.forgeLevel>=FORGE_MAX_LEVEL?'MAX':num(s.forgeExp)+' / '+num(NEED[s.forgeLevel-1])}</span></div><div class="bar"><i style="width:${s.forgeLevel>=FORGE_MAX_LEVEL?100:s.forgeExp/NEED[s.forgeLevel-1]*100}%"></i></div></div><div class="resource-note"><span>가방 ${s.gear.length} / ${GEAR_CAPACITY}</span></div><div class="forge-actions">${[1,10,100].map(n=>button(n+'회 제작<small>성운석 '+n+'</small>',`animateForge(${n})`,s.ore<1||s.gear.length>=GEAR_CAPACITY,n===1,n===1?'craft':'')).join('')}</div><div class="action-row">${button('가방',"openMenu('inventory')",false,true)}</div><div class="switch-list compact-switches">${settingRow('autoForge','자동 제작','3초마다 최대 10회','forgeIcon')}${settingRow('autoEquip','좋은 장비 자동 장착','획득한 장비의 성능 비교','equipment')}</div><p class="small">제작 1회 = 경험치 1 · 가방이 가득 차면 멈춥니다.</p>`};

forgeRatesPopup=function(){const level=forgePreviewLevel||s.forgeLevel,p=forgeProb(level),next=forgeProb(Math.min(FORGE_MAX_LEVEL,level+1));return `<div class="level-preview">${button('<ui-mark data-shape=chevron-left role=img aria-label=이전></ui-mark>','forgePreview(-1)',level===1,true)}<div><b>모루 Lv.${level}</b><small>현재 보유 Lv.${s.forgeLevel}</small></div>${button('<ui-mark data-shape=chevron-right role=img aria-label=다음></ui-mark>','forgePreview(1)',level===FORGE_MAX_LEVEL,true)}</div><div class="prob-head"><b>등급</b><b>Lv.${level}</b><b>${level===FORGE_MAX_LEVEL?'MAX':'Lv.'+(level+1)}</b></div>${RAR.map((r,i)=>`<div class="prob-row"><span class="rar${i}">${r}</span><span>${p[i].toFixed(3)}%</span><strong>${next[i].toFixed(3)}%</strong></div>`).join('')}<div class="card"><p class="small">등급·부위·세트는 별도 추첨. 6부위는 균등하며 지역 세트 10종은 각각 10%입니다.</p></div>`};
skillsScreen=function(){if(screenTab==='summon')return summonScreen('skills');const list=SK.map((_,i)=>i).filter(i=>screenFilter==='전체'||SKILL_TYPES[i]===screenFilter);return `${head('전투 스킬','슬롯 3·4는 STAGE 10·30 해금')}<div class="skill-equipped">${s.slots.map((k,i)=>`<button class="${!slotOpen(i)?'locked':''}" onclick="${slotOpen(i)&&k>=0?`openMenu('skillDetail',${k})`:"notice('3번 슬롯 STAGE 10 / 4번 슬롯 STAGE 30 해금')"}">${art(!slotOpen(i)?'lock':k<0?'skills':'s'+k)}<span class="slot-number">${i+1}</span><small>${!slotOpen(i)?'STAGE '+(i===2?10:30):k<0?'빈 슬롯':'Lv.'+s.skills[k]}</small></button>`).join('')}</div><div class="summary-strip">컬렉션 Lv.${skillCollection()} <b>공격력 +${(skillCollection()*.5).toFixed(1)}%</b></div><div class="resource-note">${art('shard')}스킬 조각 <b>${num(s.shards)}</b></div><div class="filter-chips">${['전체',...new Set(SKILL_TYPES)].map(t=>`<button class="${screenFilter===t?'active':''}" onclick="setFilter('${t}')">${t}</button>`).join('')}</div><div class="item-grid">${list.map(i=>`<button class="item-card ${s.slots.includes(i)?'equipped':''} ${s.skills[i]?'':'locked'}" onclick="openMenu('skillDetail',${i})">${art('s'+i)}${s.slots.includes(i)?'<span class="item-tag">장착</span>':''}<b>${SK[i][0]}</b><small>${s.skills[i]?'Lv.'+s.skills[i]:'미습득'}</small></button>`).join('')}</div><div class="action-row sticky-actions">${button('추천 장착','autoEquipSkills()',false,true)}${button('일괄 강화','levelAllSkills(false)')}${button('최대 강화','levelAllSkills(true)',false,true)}</div>`};
skillPopup=function(){const k=Number(tab),lv=s.skills[k]||0,r=SKILL_RULES[k],slot=s.slots.indexOf(k);return `<div class="popup-hero">${art('s'+k)}<div class="badge">${SKILL_TYPES[k]} · ${['하급','중급','상급'][r.tier]}</div><h3>${SK[k][0]} Lv.${lv}</h3><p>${r.hits>1?r.hits+'연타 · ':''}재사용 ${r.cd}초${k===8?' · 4초 둔화':''}${k===10?' · 체력 15% 회복':''}</p></div><div class="effect-table"><div><span>총 스킬 피해</span><b>${lv?compact(skillDamage(k)):'미습득'}</b></div><div><span>다음 레벨 피해</span><b>${compact(skillDamage(k,Math.min(100,lv+1)))}</b></div><div><span>스킬 조각</span><b>${num(s.shards)} / ${skillCost(k)}</b></div></div><div class="action-row">${button(lv?'1회 강화':'습득',`skillLevel(${k})`,lv>=100||s.shards<skillCost(k))}${button('최대 강화',`skillLevel(${k},true)`,lv>=100||s.shards<skillCost(k),true)}</div><div class="action-row">${button(slot>=0?'장착 중':'슬롯에 장착',`slotSkill(${k})`,!lv||slot>=0,true)}</div>`};
slotPopup=function(){const k=Number(tab);return `<p class="small">${SK[k][0]}을 장착할 슬롯을 선택하세요.</p>${s.slots.map((v,i)=>`<div class="pass-row">${art(!slotOpen(i)?'lock':v<0?'skills':'s'+v)}<div><strong>슬롯 ${i+1}</strong><small>${!slotOpen(i)?'STAGE '+(i===2?10:30)+' 해금':v<0?'빈 슬롯':SK[v][0]}</small></div>${button('장착',`setSlot(${i},${k})`,!slotOpen(i))}</div>`).join('')}`};
relicsScreen=function(){const opened=REL.filter((r,i)=>s.maxStage>=r[2]||s.relics[i]>0).length;return `<div class="relic-vault-hero">${art('relicSanctum')}<div><h2>별의 유산</h2><p>별길에 잠든 고대 유물</p><small>${opened} / ${REL.length} 해금 · STAGE ${REL[0][2]}–${REL[REL.length-1][2]}</small></div></div><div class="resource-note">${art('relicShard')}유물 조각 <b>${num(s.relicShards)}</b></div><div class="relic-vault-grid">${REL.map(([n,,stage],i)=>{const unlocked=s.maxStage>=stage||s.relics[i]>0,lv=s.relics[i];return `<button class="relic-vault-card ${unlocked?'unlocked':'locked'}" onclick="openMenu('relicDetail',${i})" aria-label="${n} · ${unlocked?'레벨 '+lv:'스테이지 '+stage+' 해금'}"><div class="relic-vault-icon codex-gear-art">${art('relic'+i)}${!unlocked?'<span class="relic-vault-lock">'+lockMark()+' 잠김</span>':''}</div><strong>${n}</strong><small>STAGE ${stage} · ${stageText(stage)}</small><b>${unlocked?'Lv.'+lv+' / 50':'미해금'}</b><em>${relicEffectText(i,lv)}</em></button>`}).join('')}</div><p class="small">지정 스테이지에서 해금됩니다. 유물 조각으로 강화하면 효과가 영구 적용됩니다.</p>`};

relicPopup=function(){
 const i=+tab;if(!Number.isInteger(i)||!REL[i])return '';
 const lv=s.relics[i]||0,cost=5+lv*2,locked=s.maxStage<REL[i][2]&&lv===0;
 return `<div class="popup-hero relic-item-hero"><span class="codex-gear-art">${art('relic'+i)}</span><h3>${REL[i][0]}</h3><p>${locked?'STAGE '+REL[i][2]+' 해금':'Lv.'+lv+' / 50'}</p></div><div class="effect-table"><div><span>현재 효과</span><b>${relicEffectText(i,lv)}</b></div>${lv<50?`<div><span>다음 효과</span><b>${relicEffectText(i,lv+1)}</b></div>`:''}<div><span>유물 조각</span><b>${num(s.relicShards)} / ${lv===50?'MAX':cost}</b></div></div><div class="action-row">${button('1회 강화',`relicLevel(${i})`,locked||lv>=50||s.relicShards<cost)}${button('최대 강화',`relicLevel(${i},true)`,locked||lv>=50||s.relicShards<cost,true)}</div>`;
};
costumeScreen=function(){const i=selectedCostume,owned=s.costumes.includes(i);return `<div class="costume-stage">${costumeSprite(i)}<button onclick="changeCostume(-1)" aria-label="이전 스킨"><ui-mark data-shape=chevron-left aria-hidden=true></ui-mark></button><button onclick="changeCostume(1)" aria-label="다음 스킨"><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></button><div class="costume-name"><strong>${COSTUME_NAMES[i]}</strong><small>${TIER_NAMES[COSTUME_TIERS[i]]} · ${owned?'Lv.'+s.costumeLevels[i]:'미보유'}</small></div></div><div class="action-row">${button(s.wear===i?'착용 중':'착용',`wear(${i})`,!owned||s.wear===i)}${button('룰렛으로',"navigate('shop','costumes')",false,true)}</div><div class="summary-strip">${s.costumes.length}종 보유 <b>합산 효과 +${(costumeBonus()*100).toFixed(1)}%</b></div><div class="costume-thumbs">${COSTUME_NAMES.map((n,j)=>`<button class="${i===j?'active':''} ${s.costumes.includes(j)?'':'locked'}" onclick="selectCostume(${j})">${costumeSprite(j)}<small>${n}<br>${s.costumeLevels[j]?'Lv.'+s.costumeLevels[j]:TIER_NAMES[COSTUME_TIERS[j]]}</small></button>`).join('')}</div><p class="small">같은 스킨을 모아 별을 강화합니다.</p><div class="effect-table">${costumeSets().map(t=>`<div><span>${t.name} 3종</span><b>${t.complete?'세트 효과 +1%':'미완성'}</b></div>`).join('')}</div>`};


dungeonScreen=function(){if(screenTab==='content')return contentHub();if(screenTab==='mine')return mineScreen();if(screenTab==='explore')return expeditionScreen();if(screenTab==='rush')return rushScreen();if(screenTab==='records')return `${head('내 도전 기록')}<div class="effect-table"><div><span>최고 스테이지</span><b>${stageText(s.maxStage)}</b></div><div><span>보스 러시 최고 피해</span><b>${compact(s.rushBest)}</b></div><div><span>이번 주 러시 피해</span><b>${compact(s.rushWeekly)}</b></div></div>${DUNGEON_NAMES.map((n,i)=>`<div class="pass-row">${art('dungeon'+i)}<div><strong>${n}</strong><small>해금 ${s.dungeonLevel[i]}단계 · 클리어 ${s.dungeonWins[i]}회</small></div></div>`).join('')}`;return `<div class="resource-note">입장권 <b>${s.tickets.reduce((a,b)=>a+b,0)}장</b><small>매일 자정 충전 · 제한 30초</small></div>${DUNGEON_NAMES.map((n,i)=>{const lv=s.dungeonSelected[i];return `<article class="dungeon-banner">${art('dungeon'+i)}<div><h3>${n}</h3><div class="difficulty"><button aria-label="이전 난이도" onclick="selectDifficulty(${i},-1)" ${lv===1?'disabled':''}><ui-mark data-shape=minus aria-hidden=true></ui-mark></button><b>${lv}단계</b><button aria-label="다음 난이도" onclick="selectDifficulty(${i},1)" ${lv>=s.dungeonLevel[i]?'disabled':''}><ui-mark data-shape=plus aria-hidden=true></ui-mark></button></div><small>권장 공격력 ${compact(recommendedPower(lv))}</small><small>입장권 ${s.tickets[i]}장 · ${materialLootLabel(i,lv)}</small>${button('도전하기',`startDungeon(${i})`,s.tickets[i]<1||!!dungeonRun)}</div></article>`}).join('')}<p class="small">클리어하면 다음 단계가 열립니다. 무기고 보상은 강화석과 별철입니다.</p>${dungeonRun?button('진행 중인 전투로',"navigate('home')"):''}`};









summonScreen=function(){return `<div class="resource-note">${art('gem')}다이아 <b>${num(s.gems)}</b>${art('summonTicket')}소환권 <b>${s.summonTickets}</b></div><div class="summon-stage">${art('summonBook','summon-book')}<h2>성운의 스킬 소환</h2><p>스킬과 스킬 조각을 획득합니다.</p></div><div class="action-row">${button('1회 · 다이아 150','animateSummon(1)',s.gems<150,true)}${button('10회 · 다이아 1,350','animateSummon(10)',s.gems<1350)}</div><div class="action-row">${button('소환권 1장','animateSummon(1,true)',s.summonTickets<1,true)}${button('소환권 10장','animateSummon(10,true)',s.summonTickets<10,true)}</div><div class="probability-summary"><span>하급 <b>70%</b></span><span>중급 <b>25%</b></span><span>상급 <b>5%</b></span></div><p class="small">같은 등급 내 확률 동일 · 중복 1개당 스킬 조각 10~20개</p><div class="action-row">${button('전체 확률 보기',"openMenu('summonRates')",false,true)}</div>`};



