shopScreen=function(){
 if(screenTab==='summon')return summonScreen();
 if(screenTab==='costumes')return costumeRoulette();
 if(screenTab==='pass')return passPopup();
 if(screenTab==='packages')return packagesScreen();
 const cards=SHOP_EXCHANGE_OFFERS.map(([key,amount,price,unit=''])=>{
  const label=RESOURCE_NAMES[key]+' '+amount;
  const purchase=`askDiamondUse('${label}${unit||'개'}',${price},()=>buyItem('${key}',${amount},${price}))`;
  return `<div class="offer-card"><small>재화 교환</small><strong>${label}${unit}</strong>${art(RESOURCE_ART[key])}${purchaseButton('다이아 '+num(price),purchase,s.gems<price,true)}</div>`;
 }).join('');
 return `<div class="shop-banner">${art('shop')}<div><h3>별빛 교환소</h3><p>패스 코인 ${s.passCoins}</p></div></div><div class="offer-grid">${dailyShopCards()}${cards}</div>${admissionShopCards()}${head('골드 상자')}<div class="offer-grid">${SHOP_GOLD_BOXES.map(([h,c,b])=>`<div class="offer-card"><small>${h}시간 보상${b>1?' +'+Math.round((b-1)*100)+'%':''}</small><strong>골드 ${compact(goldBoxAmount(h,b))}</strong>${art('coin')}${purchaseButton('다이아 '+c,`askDiamondUse('골드 상자 ${h}시간',${c},()=>buyGoldBox(${h},${c},${b}))`,s.gems<c,true)}</div>`).join('')}</div><div class="action-row">${button('패스 코인 교환',"openMenu('passExchange')",false,true)}</div>`};

const PACKAGES=[
 ['초보자 패키지','다이아 100 · 골드 10,000 · 성운석 50 · 소환권 2','1,200원',1,'starter'],
 ['일일 패키지','다이아 100 · 성운석 100 · 별의 광산 입장권 2','1,200원',1,'daily'],
 ['광석 패키지 I','성운석 300 · 별철 30 · 다이아 300','5,900원',1,'ore-1'],
 ['광석 패키지 II','성운석 600 · 별철 100 · 별의 광산 입장권 5 · 다이아 1,500','19,000원',1,'ore-2'],
 ['성장 패키지 I','다이아 300 · 별철 50 · 강화석 300 · 골드 30,000','5,900원',20,'growth-1'],
 ['성장 패키지 II','다이아 700 · 스킬 조각 100 · 유물 조각 30 · 소환권 10','12,000원',50,'growth-2'],
 ['성장 패키지 III','다이아 3,000 · 별철 200 · 강화석 1,500 · 성운석 500 · 골드 150,000','33,000원',100,'growth-3'],
 ['성장 패키지 IV','다이아 5,000 · 별철 350 · 강화석 2,500 · 성운석 900 · 골드 250,000','55,000원',150,'growth-4'],
 ['성장 패키지 V','다이아 8,500 · 별철 600 · 강화석 4,500 · 성운석 1,500 · 골드 450,000','89,000원',200,'growth-5']
];


questsPopup=function(){return `<div class="tabs">${[['main','진행'],['daily','일일'],['weekly','주간'],['achievements','업적']].map(([k,n])=>`<button class="${missionTab===k?'active':''}" onclick="missionTab='${k}';render()">${n}</button>`).join('')}</div>${missionTab==='main'?mainQuestPopup():missionTab==='achievements'?achievementsPopup():missionTab==='daily'?DAILY_GOALS.map(([k,n,goal])=>missionCard(n,s.daily[k]||0,goal,!!s.daily.claimed[k],`dailyClaim('${k}')`,'다이아 50 · 패스 코인 5 · 시즌 20P')).join(''):WEEKLY_GOALS.map(([k,n,goal])=>missionCard(n,s.weekly[k]||0,goal,!!s.weekly.claimed[k],`weeklyClaim('${k}')`,'다이아 200 · 소환권 2 · 시즌 100P')).join('')}`};


attendancePopup=function(){return `<div class="tabs"><button class="${attendanceMode==='seven'?'active':''}" onclick="attendanceMode='seven';render()">7일 출석${rewardDot('attendance:seven')}</button><button class="${attendanceMode==='month'?'active':''}" onclick="attendanceMode='month';render()">월 출석${rewardDot('attendance:month')}</button></div>${attendanceMode==='seven'?sevenAttendance():monthAttendance()}`};

let selectedMonthReward=0,selectedMonthKey='';


morePopup=function(){return `<div class="menu-directory">${[['attendance','출석','attendance'],['quests','미션·업적','quests'],['pass','성장·시즌 패스','pass'],['event','이벤트','event'],['ranking','랭킹','ranking'],['resources','재화 가방','inventory'],['vip','누적 VIP','vip'],['online','온라인 안내','guild'],['settings','설정','settings']].map(([k,n,a])=>`<button onclick="openMenu('${k}')">${art(a)}${n}</button>`).join('')}</div><div class="action-row">${button('모험 콘텐츠',"navigate('dungeon','content')",false,true)}${button('오프라인 보상',"openMenu('offline')",false,true)}</div>`};



infoPopup=function(){if(tab==='forge')return '<div class="card"><h3>모루 안내</h3><p>성운석 1개로 제작 1회. 모루 경험치는 제작으로 얻습니다.</p></div>';if(tab==='skills')return '<div class="card"><h3>스킬 안내</h3><p>3·4번 슬롯은 STAGE 10·30에서 열립니다. 스킬을 눌러 강화·장착하세요.</p></div>';if(tab==='dungeon')return '<div class="card"><h3>모험 콘텐츠</h3><p>던전에서 재료 던전·보스 러시·오늘의 탑·광산·탐험을 선택하세요.</p></div>';return oldInfoPopup()};
const EXTRA_POPUPS={showcase:['장비 진열장',showcasePopup],showcaseConfirm:['진열장 등록',showcaseConfirm],petDetail:['동료 관리',petDetail],summonResult:['스킬 소환 결과',summonResult],summonRates:['스킬 소환 확률',summonRates],costumeResult:['룰렛 결과',costumeResult],passExchange:['패스 코인 교환',passExchange],challengeResult:['도전 결과',challengePopup],resources:['재화 가방',resourcePopup],offline:['오프라인 보상',offlinePopup],online:['온라인 콘텐츠',onlinePopup]};
render=function(){
 if(!view)return;
 const entry=EXTRA_POPUPS[view],el=$('content');
 el.dataset.surface=/skill|^slot$|saveBuild|summonResult|summonRates/i.test(view)?'skills':'interface';
 if(!entry){delete el.dataset.disclosureView;return oldRenderExpansion()}
 // Combat refreshes the popup periodically. Keep this form, its caret and receipt intact.
 if(view==='rewardCode' && document.getElementById('rewardCodeForm'))return;
 // The paused choice is stable until a floor changes. Keep keyboard and screen-reader focus.
 if(view==='trialChoice'&&dungeonRun?.choosing&&el.querySelector('[data-trial-choice]')?.dataset.trialChoice===trialChoiceIdentity(dungeonRun))return;
 if(view==='settings' && el.querySelector('.pref-sheet')?.dataset.page===(settingsIsTest()?'test':'basic')){
  for(const row of el.querySelectorAll('[data-pref]')){
   const on=!!s[row.dataset.pref];
   if(row.getAttribute('aria-checked')===String(on))continue;
   row.setAttribute('aria-checked',String(on));
   row.querySelector('.switch-face').outerHTML=switchFace(on);
  }
  return;
 }
 if(view==='audioOptions' && el.querySelector('#musicVolume'))return;
 if(view==='testDiagnostics' && el.querySelector('#diagnosticCopy'))return;
 const [name,fn]=entry,scroll=el.scrollTop;
 const keepDetails=['support','notices','ranking'].includes(view);
 const states=keepDetails&&el.dataset.disclosureView===view?Array.from(el.querySelectorAll('details'),x=>x.open):[];
 $('heading').textContent=typeof name==='function'?name():name;
 const markup=fn(),rankingView=['ranking','wbRanks'].includes(view);
 if(rankingView&&el.firstElementChild?.rankMarkup===markup)return;
 el.innerHTML=markup;
 if(rankingView&&el.firstElementChild)el.firstElementChild.rankMarkup=markup;
 el.dataset.disclosureView=keepDetails?view:'';
 if(states.length)el.querySelectorAll('details').forEach((x,i)=>{if(i<states.length)x.open=states[i]});
 hydrateArt(el);el.scrollTop=scroll;setPopupInert(true);
};
SCREEN_META.dungeon[0]='던전';

;
// game script 10
paintWorld = function paintWorld(){
 document.body.classList.toggle('dungeon-combat',!!dungeonRun);$('dungeonLeave').hidden=$('dungeonHeading').hidden=!dungeonRun;
 if(dungeonRun){
  const r=dungeonRun,floor=r.mode==='tower'||r.mode==='trial',rush=r.mode==='rush';
  const name=floor||rush?DUNGEON_BANNERS[r.mode].name:DUNGEON_NAMES[r.i];
  const progress=floor?r.n+'층':rush?r.bosses+'보스 돌파':r.n+'단계';
  const seconds=Math.max(0,Math.ceil(r.time))+'초';
  $('stage').textContent=name;
  $('region').textContent=progress+' · '+seconds;
  $('dungeonName').textContent=rush?name:name+' '+progress;
  $('dungeonClock').textContent='남은 시간 '+seconds;
 }
 const e=encounterFor(s.stage,dungeonRun),b=BIOMES[e.region],land=document.querySelector('.landscape'),mob=$('mobActor');
 const key=e.art+':'+e.background+':'+s.activePet;
 if(!dungeonRun)$('region').textContent=b.name+' · '+(e.boss?'지역 보스':((s.stage-1)%10+1)+'/10');
 if(key!==lastEncounterKey){
  lastEncounterKey=key;
  if(e.mini){
   $('battle').dataset.towerMini='true';$('battle').dataset.miniScale=e.scale;
   const field=$('battle');field.style.setProperty('--tower-mini-size',Math.round(Math.min(field.clientWidth*e.scale,field.clientHeight*.53))+'px');
  }else{delete $('battle').dataset.towerMini;delete $('battle').dataset.miniScale}
  land.style.filter='none';land.style.backgroundImage='var(--'+e.background+')';
  $('battle').style.setProperty('--biome-accent',b.color);$('battle').setAttribute('data-region',e.region);
  mob.classList.add('world-creature');
  if(!isDuoBattle()){mob.setAttribute('data-art',e.art);mob.setAttribute('aria-label',e.name);hydrateArt($('battle'))}
  $('mobTwo').hidden=true;$('mobThree').hidden=true;
  const pet=$('battlePet');if(pet){pet.hidden=s.activePet<0;if(s.activePet>=0&&pet.dataset.companion!==String(s.activePet)){pet.dataset.companion=String(s.activePet);pet.innerHTML=petArt(s.activePet,'','battle');pet.setAttribute('aria-label',PETS[s.activePet]);hydrateArt(pet)}}
 }
 mob.classList.toggle('region-boss',e.boss);
 $('battleWeather').className='battle-weather region-weather-'+e.region;
};
initDiversity = function initDiversity(){
 const pet=document.createElement('div');pet.id='battlePet';pet.className='battle-pet';pet.setAttribute('role','img');$('battle').appendChild(pet);
 lastEncounterKey='';paintWorld();
};
petDisplayOrder = function petDisplayOrder(){return PET_TIERS.slice().reverse().flatMap(t=>t.pets)};
petSummonPopup = function petSummonPopup(){return drawResultPanel('pet',petSummonResults)};
petRatesPopup = function petRatesPopup(){
 const groups=PET_TIERS.map(t=>summonOddsGroup({name:t.name,color:t.color,chance:t.weight/100},
  t.pets.map(i=>({name:PETS[i],icon:petArt(i),chance:petProbability(i)})))).join('');
 return '<p class="small">같은 등급 내 확률 동일 · 10회도 개별 추첨 · 중복 시 동료 조각 10~20개(희귀 ×1.2 · 영웅 ×1.5 · 전설 ×2 · 신화 ×2.5 · 천상 ×3). 강화에 드는 조각도 같은 배수입니다</p>'+groups;
};
diamondShop = function diamondShop(){return `<div class="diamond-banner"><div><h2>별의 다이아 상점</h2><p>모험을 위한 빛나는 선택</p></div>${art('diamonds4')}</div><div class="shop-status"><span class="status-lamp"></span><div><b>결제 오픈 준비 중</b><small>상품을 누르면 구성과 첫 충전 혜택을 볼 수 있습니다.</small></div></div><div class="diamond-grid">${DIAMOND_PRODUCTS.map((p,i)=>`<button class="diamond-product ${i===DIAMOND_PRODUCTS.length-1?'grand':''}" onclick="openMenu('diamondProduct',${i})"><span class="first-charge">첫 충전 2배</span>${art(p.art)}<span class="product-copy"><small>${p.name}</small><strong>${num(p.gems)} <em>다이아</em></strong><span class="bonus">첫 구매 보너스 +${num(p.gems)}</span></span><span class="product-price">${num(p.price)}원 <small>구성 보기 <ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></small></span></button>`).join('')}</div><p class="small shop-footnote">상품별 첫 유료 구매는 다이아 2배입니다. 결제 연결 후 적용됩니다.</p>`};
diamondProductPopup = function diamondProductPopup(){const i=+tab,p=DIAMOND_PRODUCTS[i];if(!p)return '<p>상품을 선택하세요.</p>';return `<div class="popup-hero diamond-detail">${art(p.art)}<h3>${p.name}</h3><p>다이아 ${num(p.gems)}개</p></div><div class="effect-table"><div><span>기본 수량</span><b>${num(p.gems)} 다이아</b></div><div><span>첫 구매 추가 수량</span><b>+${num(p.gems)} 다이아</b></div><div class="purchase-total"><span>첫 구매 시 총 수량</span><b>${num(p.gems*2)} 다이아</b></div><div><span>상품 가격</span><b>${num(p.price)}원</b></div></div><div class="payment-notice"><b>아직 구매할 수 없습니다</b><p>결제 연결 전입니다. 현재 구매와 다이아 지급은 불가합니다.</p></div><div class="action-row">${button('결제 연결 전','',true)}${button('상점으로 돌아가기','closeMenu()',false,true)}</div>`};
worldMapPopup = function worldMapPopup(){return `<div class="atlas-intro"><h3>여덟 세계를 잇는 별길</h3><p>지역마다 9번의 사냥과 1번의 보스전.<br>배경·몬스터 3종·지역 보스가 함께 바뀝니다.</p></div><div class="world-grid">${BIOMES.map((b,i)=>`<button class="world-card ${currentRegion()===i?'current':''}" style="--world-bg:var(--region_${i})" onclick="openMenu('regionDetail',${i})"><span class="world-number">${String(i+1).padStart(2,'0')}</span><div><small>STAGE ${i*10+1}–${i*10+10}</small><b>${b.name}</b><em>${s.maxStage>=i*10+1?'지역 정보 보기':'미탐험 · 미리보기'}</em></div></button>`).join('')}</div><p class="small">STAGE 81부터 8개 지역을 순환하며 적이 강해집니다. 현재 ${Math.floor((s.stage-1)/80)+1}회차 · 최고 STAGE ${s.maxStage}</p>`};
regionDetailPopup = function regionDetailPopup(){const i=+tab,b=BIOMES[i];if(!b)return '<p>지역을 선택하세요.</p>';const cycle=Math.floor((s.stage-1)/80),start=cycle*80+i*10+1,target=start<=s.maxStage?start:i*10+1;return `<div class="region-preview" style="background-image:var(--region_${i})"><span>REGION ${String(i+1).padStart(2,'0')}</span><h3>${b.name}</h3><p>${b.sub}</p></div><p class="small">${b.desc}</p>${head('이 지역의 몬스터','스테이지마다 순서대로 등장')}<div class="bestiary-grid">${b.mobs.map((mob,j)=>`<div>${art('creature_'+i+'_'+j)}<b>${mob.name}</b><small>${j+1} · ${j+4} · ${j+7}번째 사냥</small></div>`).join('')}</div><div class="region-boss-preview">${art('creature_'+i+'_3')}<div><span>REGION BOSS · 10 / 10</span><h3>${b.boss}</h3><small>지역의 마지막 스테이지에서 등장</small></div></div><div class="action-row">${button('STAGE '+target+'로 이동',`travelToRegion(${i})`,target>s.maxStage||!!dungeonRun)}${button('지역 목록','closeMenu()',false,true)}</div>`};
travelToRegion = function travelToRegion(i){if(!Number.isInteger(i)||i<0||i>=8||dungeonRun)return;const start=Math.floor((s.stage-1)/80)*80+i*10+1,target=start<=s.maxStage?start:i*10+1;if(target>s.maxStage){notice('아직 탐험하지 않은 지역입니다');return}s.stage=target;s.enemyHp=maxHp();heroCurrentHp=health();battleElapsed=0;navigate('home');paint();save()};
