// game script 11
safeText = function safeText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};
validNickname = function validNickname(value,minLength=1){const n=String(value||'').normalize('NFKC').trim().replace(/\s+/gu,' ');return /^[\p{L}\p{N} _-]{1,12}$/u.test(n)&&Array.from(n).length>=minLength?n:null};
extendProfileSave = function extendProfileSave(a){
 a.nickname=validNickname(a.nickname)||'성운기사';
 a.localId=/^NK-[A-Z0-9]{8}$/.test(a.localId||'')?a.localId:'NK-'+Math.random().toString(36).slice(2,10).padEnd(8,'0').toUpperCase();
 a.soundVolume=Number.isFinite(a.soundVolume)?Math.max(0,Math.min(100,Math.round(a.soundVolume))):55;
 a.musicVolume=Number.isFinite(a.musicVolume)?Math.max(0,Math.min(100,Math.round(a.musicVolume))):45;
 a.musicTrack=['auto','starlit-path','moonlit-forge','astral-trial'].includes(a.musicTrack)?a.musicTrack:'auto';
 a.readNotices=Array.isArray(a.readNotices)?a.readNotices.filter(id=>GAME_NOTICES.some(n=>n.id===id)):[];
 for(const key of ['music','haptics','powerSaving'])a[key]=a[key]===true;
 delete a.darkMode;
 return a;
};
