setPreference = function setPreference(key){
 if(!SETTINGS_ALLOWED.has(key))return false;
 if(key==='autoForge')forgeNextAt=Date.now()+3000;
 if(key==='haptics'&&(typeof navigator==='undefined'||!('vibrate' in navigator))){notice('이 기기에서는 진동을 지원하지 않습니다');return false}
 s[key]=!s[key];applyPreferences();save();paint();
 if(key==='sound'&&s.sound){wakeAudio();playSound('reward')}if(key==='music'&&s.music)wakeAudio();
 if(key==='haptics'&&s.haptics)navigator.vibrate(35);
 return true;
};
