profileTab = function profileTab(name){if(name==='settings'){openMenu('settings');return}profileNameDraft=null;view='profile';tab=['stats','identity','settings'].includes(name)?name:'stats';$('content').scrollTop=0;render()};
statSection = function statSection(title,rows){return `<section class="spec-section"><h3><span><ui-mark data-shape=spark aria-hidden=true></ui-mark></span> ${title}</h3><dl>${rows.map(([label,value,note])=>`<div><dt>${Object.hasOwn(ADVENTURE_TERMS,label)?termButton(label,label):label}${note?`<small>${note}</small>`:''}</dt><dd>${value}</dd></div>`).join('')}</dl></section>`};
skillDamageFactor = function skillDamageFactor(){
 return (1+s.relics[2]*.03)*(1+petSpecial('skill'))*(1+setBonuses().skill)*
  weaponModifier('fire')*(1+skinBonus('skill'))*(s.classId==='mage'?1.1:1);
};
ratingText = function ratingText(value){return ratingNumberFormat.format(value)};
combatPowerFactors = function combatPowerFactors(){
 const attack=Math.max(1,power());
 // Auto-combat polls every 100 ms. Average half a tick of waiting to keep small speed gains continuous.
 const cadence=1.15/attackSpeed()+.05,pierce=penetrationMultiplier(.15);
 const critical=1+criticalChance()*criticalDamageBonus();
 const basic=adventureBasicMultiplier()*weaponModifier('storm');
 let freeTime=1,skillRate=0,boost=0,armorBreak=0;
 const dots={burn:{uptime:0,rate:0},poison:{uptime:0,rate:0}};
 for(const [slot,k] of s.slots.entries()){
  if(k<0||!slotOpen(slot)||!skillUnlocked(k))continue;
  const rule=SKILL_RULES[k],meta=skillMeta(k);
  if(meta.status==='heal'&&meta.target!=='all')continue;
  // Skills occupy an attack opportunity. A longer cast also delays the next basic attack.
  const lock=Math.max(cadence,.680,.270+rule.hits*.070);
  // A ready skill waits for the next available attack opportunity.
  const casts=Math.min(1/(rule.cd+cadence/2),freeTime/lock);
  freeTime=Math.max(0,freeTime-casts*lock);
  if(meta.target!=='self'){
   const execute=meta.status==='execute'?1+.35*.6:1;
   skillRate+=casts*skillDamage(k,s.skills[k],true)/attack*meta.factor*execute;
  }
  if(meta.status==='boost')boost+=casts*(k===9?4:6);
  if(meta.status==='break')armorBreak+=casts*6;
  if(dots[meta.status]){
   const dot=dots[meta.status],uptime=casts*4;
   dot.uptime+=uptime;
   dot.rate+=uptime*skillDotRatio(k,s.skills[k],true);
  }
 }
 const armorFactor=pierce+(1.25-pierce)*Math.min(1,armorBreak);
 const direct=(freeTime/cadence*basic+skillRate)*critical*armorFactor*(1+.5*Math.min(1,boost));
 // Reapplications refresh the same status. Its ticks cannot stack or critically strike.
 const ongoing=Object.values(dots).reduce((sum,dot)=>sum+dot.rate/Math.max(1,dot.uptime),0);
 return {offense:direct+ongoing*pierce,effectiveHp:health()/weaponModifier('frost')};
};
combatPower = function combatPower(attack=power(),factors=combatPowerFactors()){
 const dps=attack*factors.offense;
 if(dps<=0)return 0;
 const hp=factors.effectiveHp;
 // Effective health adds at most 5% of damage output, with diminishing returns.
 return Math.round(100*dps*(1+.05*hp/(hp+6*dps)))/100;
};
detailedStats = function detailedStats(){
 const sets=setBonuses(),pct=n=>(n*100).toFixed(1)+'%',goldFactor=(1+growthBonus(2))*(1+s.relics[3]*.03)*(1+s.legacyGrowth[1]*.05)*(1+petHoldingBonus())*(1+petSpecial('gold'));
 return {attack:power(),hp:health(),defense:armor(),speed:attackSpeed(),crit:criticalChance(),goldFactor,sets,pct};
};
statsPane = function statsPane(){const v=detailedStats(),p=v.pct;
 return `<div class="spec-identity">${faceControl()}<div><strong>${safeText(s.nickname)}</strong>${profileTitleControl()}<span>Lv.${s.level} · STAGE ${stageText(s.stage)}</span></div><b>${ratingText(combatPower(v.attack))}<small>전투력</small></b></div>`+
 statSection('기본 능력',[
 ['최대 체력',num(v.hp)],['공격력',num(v.attack)],['방어력',num(v.defense),'받는 피해 '+(100*armorMitigation(v.defense)).toFixed(1)+'% 감소'],['공격속도',v.speed.toFixed(2)+'×'],['초당 공격 횟수',(v.speed/1.15).toFixed(2)+'회','기본 속도 기준 · 배속 제외']
 ])+statSection('전투 · 획득 효과',[
 ['방어 관통력',p(armorPenetration()),'대상 방어로 막히는 피해의 일부를 회복'],['치명타 확률',p(v.crit)],['치명타 피해',criticalDamageText(100*criticalDamageBonus()),'일반 피해에 더해지는 비율'],['스킬 피해 보너스','+'+p(skillDamageFactor()-1)],['골드 획득 배율',v.goldFactor.toFixed(2)+'×'],['현재 지역 처치 골드',num(campaignKillGold())],['오프라인 보상 최대 시간',Math.min(24,8+s.legacyGrowth[3]*.3+s.relics[6]*.1).toFixed(1)+'시간']
 ])+statSection('수집 · 장착 효과',[
 ['세트 공격력','+'+p(v.sets.attack)],['세트 체력','+'+p(v.sets.hp)],['세트 공격속도','+'+p(v.sets.speed)],['세트 치명타 확률','+'+p(v.sets.critical)+'p'],['세트 치명타 피해','+'+p(v.sets.critDamage)],['세트 스킬 피해','+'+p(v.sets.skill)],['장비 도감','+'+p(collectionBonus())],['스킨 보유 효과',outfitEffectText(holdingOutfitStats())],['스킨 착용 효과',outfitEffectText(wornOutfitStats())],['동료 보유 효과','공격력·골드 +'+p(petHoldingBonus())],['동행 동료',s.activePet>=0?COMPANIONS[s.activePet][0]+' Lv.'+s.pets[s.activePet]:'미장착']
 ])+`<p class="profile-footnote">방어율 15% 기준, 전투력은 예상 초당 피해에 생존 보너스(최대 5%)를 더합니다.<br>방어력에 따른 피해 감소는 최대 40%입니다.</p><button class="gold-button profile-wide" onclick="navigate('character','equipment')">장비 관리로 이동</button>`;
};
