identityPane = function identityPane(){return `<div class="identity-heading">${faceControl()}<div><strong>${safeText(s.nickname)}</strong>${profileTitleControl()}<span>Lv.${s.level} · 성운의 기사</span><small>로컬 ID ${safeText(s.localId)}</small></div><button class="edit-name" onclick="openNameEditor()" aria-label="기사 이름 변경"><ui-mark data-shape=edit aria-hidden=true></ui-mark></button></div><div class="profile-body"><div class="profile-character">${wornCostumeSprite()}<small>${safeText(wornCostumeName())}</small><button class="gold-button purple" onclick="navigate('character','costume')">꾸미기</button></div><div class="profile-links"><span class="server-status"><i></i> ${testSession?'테스트 세션':'계정 모험'}</span><small>이 기기에서 플레이 중</small>${[
 ['servers','서버 선택','dungeon'],['notices','게임 공지','quests'],['support','도움말 · 지원','mail'],['saveManager','저장 관리','inventory']
 ].map(([key,label,icon])=>`<button onclick="${key==='notices'?'openGameNotices()':`openMenu('${key}')`}">${art(icon)}<span>${label}</span>${key==='notices'&&hasUnreadNotices()?'<i class="notice-pip"></i>':'<span class="link-arrow"><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></span>'}</button>`).join('')}</div></div><div class="local-account-note"><b>기기 저장 방식</b><p>이 기기의 저장 ID입니다. 기기 간 자동 동기화는 지원하지 않습니다.</p></div>`};
