 return `<button type="button" class="pref-switch" role="switch" aria-checked="${!!s[key]}" aria-label="${label}" data-pref="${key}" onclick="setPreference('${key}')">${icon}<strong>${label}</strong>${switchFace(s[key])}</button>`;
