openTownPlace = function openTownPlace(id){if(!TOWN_PLACES.some(p=>p.id===id)||!canOpenHaven(id))return false;if(id==='havenShop')openMenu('havenShop','guild');else if(id==='raidComing')openMenu('raidComing');else openMenu('online',id);return true};
townPlaceStatus = function townPlaceStatus(){return '준비 중'};
townPlaceReady = function townPlaceReady(){return false};
townScreen = function townScreen(){
 return `<div class="town-map-viewport"><h2 class="haven-heading">성운의 거점</h2><div class="town-map" role="group" aria-label="성운의 거점 · 다섯 건물">${TOWN_PLACES.map(p=>`<button class="town-building ${p.group}" data-feature="${featureForHavenPlace(p.id)}" style="--place-x:${p.x}%;--place-y:${p.y}%" onclick="openTownPlace('${p.id}')" aria-label="${p.name}"><span class="town-hit-area"></span><span class="town-nameplate"><b>${p.name}</b></span></button>`).join('')}</div></div>`;
};
townDirectoryCard = function townDirectoryCard(p){return `<button class="town-directory-card place-${p.id}" onclick="openTownPlace('${p.id}')">${art(p.art)}<span><strong>${p.name}</strong><small>${p.desc}</small><em>${townPlaceStatus(p)}</em></span><b><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></b></button>`};
extendMailbox = function extendMailbox(a){const old=a.mailbox&&typeof a.mailbox==='object'&&!Array.isArray(a.mailbox)?a.mailbox:{};a.mailbox={};for(const m of MAIL_DEFINITIONS){const st=old[m.id]&&typeof old[m.id]==='object'?old[m.id]:{};const claimed=m.id==='welcome'?(a.mailClaimed===true||st.claimed===true):st.claimed===true;a.mailbox[m.id]={read:claimed||st.read===true,claimed,archived:st.archived===true&&(claimed||!Object.keys(m.rewards).length),receivedAt:Number.isFinite(st.receivedAt)&&st.receivedAt>0&&st.receivedAt<=Date.now()?st.receivedAt:Date.now()};}a.mailClaimed=a.mailbox.welcome.claimed;return a};
mailState = function mailState(id){if(!s.mailbox)extendMailbox(s);return s.mailbox[id]};
mailboxEntries = function mailboxEntries(filter=mailboxFilter){return MAIL_DEFINITIONS.filter(m=>{const st=mailState(m.id);return !st.archived&&(filter==='all'||(filter==='pending'&&Object.keys(m.rewards).length&&!st.claimed)||(filter==='received'&&st.claimed))}).sort((a,b)=>mailRank(a)-mailRank(b))};
mailRank = function mailRank(m){const st=mailState(m.id);return Object.keys(m.rewards).length&&!st.claimed?0:!st.read?1:st.claimed?3:2};
hasMailNotification = function hasMailNotification(){return MAIL_DEFINITIONS.some(m=>{const st=mailState(m.id);return !st.archived&&(!st.read||Object.keys(m.rewards).length&&!st.claimed)})};
mailDate = function mailDate(m){if(m.date)return m.date;const d=new Date(mailState(m.id).receivedAt);return d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0')};
setMailFilter = function setMailFilter(filter){if(!['all','pending','received'].includes(filter))return;mailboxFilter=filter;$('content').scrollTop=0;render()};
mailRewardMini = function mailRewardMini(m){return Object.entries(m.rewards).map(([key,count])=>`<span class="mail-mini-reward ${mailState(m.id).claimed?'claimed':''}" aria-label="${RESOURCE_NAMES[key]} ${count}${mailState(m.id).claimed?' 수령 완료':''}">${art(RESOURCE_ART[key])}<b>${num(count)}</b>${mailState(m.id).claimed?'<i class="received-check"><ui-mark data-shape=check aria-hidden=true></ui-mark></i>':''}</span>`).join('')};
openMail = function openMail(id){const m=MAIL_DEFINITIONS.find(m=>m.id===id);if(!m||mailState(id).archived)return false;mailState(id).read=true;save();paint();openMenu('mailDetail',id);return true};
claimMailById = function claimMailById(id,quiet=false){
 const m=MAIL_DEFINITIONS.find(m=>m.id===id),st=mailState(id);
 if(!m||!st||st.claimed||st.archived||!Object.keys(m.rewards).length)return false;
 if(saveGuard.usesServer())return claimAccountReward('mail',id,quiet).then(receipt=>{
  if(receipt){
   mailClaimEffectUntil=Date.now()+1000;
   if(!quiet&&view==='mailDetail'&&tab===id)$('content').querySelector('.mail-detail')?.classList.add('mail-claim-animation');
  }
  return receipt;
 });
 st.claimed=true;st.read=true;if(id==='welcome')s.mailClaimed=true;grant(m.rewards);mailClaimEffectUntil=Date.now()+1000;
 if(!quiet){paint();save();notice('우편 보상을 수령했습니다')}return true;
};
claimAllMail = function claimAllMail(){
 if(saveGuard.usesServer()){
  if(pendingMailBatch)return pendingMailBatch;
  const owner=s,messages=mailboxEntries('pending');
  if(!messages.length)return 0;
  pendingMailBatch=Promise.all(messages.map(m=>claimMailById(m.id,true))).then(receipts=>{
   if(owner!==s)return 0;
   const paid=receipts.filter(Boolean),rewards={};
   for(const receipt of paid){
    for(const [key,n] of Object.entries(receipt.rewards))rewards[key]=(rewards[key]||0)+n;
   }
   if(paid.length){rewardNotice(rewards,'우편 '+paid.length+'건 보상 수령');playSound('reward');paint()}
   return paid.length;
  }).finally(()=>{pendingMailBatch=null;if(owner===s&&(view==='mail'||view==='mailDetail'))render()});
  if(view==='mail')render();
  return pendingMailBatch;
 }
 let count=0;for(const m of MAIL_DEFINITIONS)if(claimMailById(m.id,true))count++;if(count){paint();save();playSound('reward');notice('우편 '+count+'건의 보상을 모두 수령했습니다')}return count};
archiveReadMail = function archiveReadMail(){lastArchivedMailIds=mailboxEntries('all').filter(m=>{const st=mailState(m.id);return st.read&&(st.claimed||!Object.keys(m.rewards).length)}).map(m=>m.id);for(const id of lastArchivedMailIds)mailState(id).archived=true;paint();save();return lastArchivedMailIds.length};
undoArchiveMail = function undoArchiveMail(){for(const id of lastArchivedMailIds)mailState(id).archived=false;lastArchivedMailIds=[];paint();save()};
mailDetail = function mailDetail(){const m=MAIL_DEFINITIONS.find(m=>m.id===tab);if(!m)return '<p>우편을 찾을 수 없습니다.</p>';const st=mailState(m.id),hasRewards=Object.keys(m.rewards).length;return `<article class="mail-detail ${st.claimed?'mail-received':''} ${st.claimed&&Date.now()<mailClaimEffectUntil?'mail-claim-animation':''}"><div class="mail-detail-sender">${art('mail')}<span>${m.sender}<small>${mailDate(m)}</small></span><b>${st.claimed?'<ui-mark data-shape=check aria-hidden=true></ui-mark> 수령 완료':st.read?'읽음':'새 우편'}</b></div><h3>${m.title}</h3><p>${m.body}</p>${hasRewards?`<div class="mail-detail-rewards">${Object.entries(m.rewards).map(([key,count],i)=>`<div class="mail-reward ${st.claimed?'claimed':''}" style="--claim-delay:${i*90}ms"><div class="mail-reward-icon">${art(RESOURCE_ART[key])}${st.claimed?'<span class="received-check"><ui-mark data-shape=check aria-hidden=true></ui-mark></span>':''}</div><strong>${RESOURCE_NAMES[key]} <b>${num(count)}</b></strong>${st.claimed?'<span class="received-stamp">수령 완료</span>':''}</div>`).join('')}</div><button class="gold-button profile-wide mail-claim-button" onclick="claimMailById('${m.id}')" ${st.claimed?'disabled':''}>${st.claimed?'<ui-mark data-shape=check aria-hidden=true></ui-mark> 수령 완료':'보상 받기'}</button>`:`<button class="gold-button profile-wide" onclick="navigate('content')">콘텐츠 거점으로</button>`}</article>`};
costumeSprite = function costumeSprite(i,cls=''){const id=Number.isInteger(i)&&i>=0&&i<OUTFITS.length?i:0;return `<div class="paperdoll costume-sprite costume-${id} ${cls}" data-costume="${id}" role="img" aria-label="${COSTUME_NAMES[id]}"></div>`};
paintHeroCostume = function paintHeroCostume(){const id=Number.isInteger(s.wear)&&s.costumes.includes(s.wear)?s.wear:0,hero=$('heroActor');hero.dataset.costume=String(id);hero.classList.toggle('dressed-hero',id>0);hero.style.setProperty('--worn-costume','var(--costume-'+id+')');hero.style.filter='drop-shadow(0 7px 5px #1119)';hero.setAttribute('aria-label',COSTUME_NAMES[id])};
initTownWardrobe = function initTownWardrobe(){extendMailbox(s);lastArchivedMailIds=[];const shortcut=document.querySelector('.content-shortcut');if(shortcut){shortcut.setAttribute('onclick',"navigate('content')");shortcut.setAttribute('aria-label','콘텐츠 거점')}paint();save()};
