mailUI=function(){const rows=mailboxEntries(),pending=mailboxEntries('pending').length,canArchive=mailboxEntries('all').some(m=>mailState(m.id).read&&(mailState(m.id).claimed||!Object.keys(m.rewards).length));return `<div class="mailbox-summary"><b>받은 우편 <span>${mailboxEntries('all').length}</span></b><small>${pending?'수령할 보상 '+pending+'건':'모든 보상을 수령했습니다'}</small></div><div class="mailbox-tabs">${[['all','전체'],['pending','미수령'],['received','수령 완료']].map(([k,n])=>`<button class="${mailboxFilter===k?'active':''}" onclick="setMailFilter('${k}')" aria-pressed="${mailboxFilter===k}">${n}</button>`).join('')}</div><div class="mailbox-list ${Date.now()<mailClaimEffectUntil?'mail-claim-animation':''}">${rows.map(m=>{const st=mailState(m.id),reward=Object.keys(m.rewards).length;return `<button class="mail-list-row ${st.read?'read':'unread'} ${st.claimed?'mail-received':''}" data-mail-id="${m.id}" onclick="openMail('${m.id}')">${art('mail','mail-row-envelope')}<span class="mail-row-text"><strong>${m.title}</strong><small>${mailDate(m)} <i>·</i> ${st.claimed?'<ui-mark data-shape=check aria-hidden=true></ui-mark> 수령 완료':reward?'보상 수령 가능':st.read?'읽음':'새 소식'}</small></span><span class="mail-row-rewards">${mailRewardMini(m)}${!reward?'<b class="mail-info-label">안내</b>':''}</span><span class="mail-row-arrow"><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></span></button>`}).join('')||'<div class="mailbox-empty">'+art('mail')+'<b>표시할 우편이 없습니다</b><small>새로운 소식과 보상은 이곳에 도착합니다.</small></div>'}</div><div class="mailbox-actions"><button class="muted-button" onclick="archiveReadMail()" ${canArchive?'':'disabled'}>읽은 우편 정리</button><button class="gold-button" onclick="claimAllMail()" ${pending&&!pendingMailBatch?'':'disabled'}>${pending?'전부 수령':'수령 완료'}</button></div>${lastArchivedMailIds.length?'<button class="mail-undo" onclick="undoArchiveMail()">방금 정리한 우편 되돌리기</button>':''}`};


