spawnClassFx = function spawnClassFx(effect,big=false,phase='impact',skillId=-1,echo=false,factor=1){
 if(!motionAllowed()||activeScreen!=='home'||view||document.hidden)return;const layer=$('classFx');if(!layer)return;
 const visual=SKILL_VFX[skillId>=0?skillId:classSkillIds().find(k=>CLASS_SKILLS[k][1]===effect)??classSkillIds()[0]];
 if(!visual)return;
 // A stationary melee wind-up sprite floats beside the waist, detached from the weapon.
 // Let the character's swing provide the wind-up; show the painted slash on impact only.
 if(phase==='charge'&&!visual.travel&&['cleave','cross','quake','storm','holy','shield'].includes(visual.effect))return;
 const node=document.createElement('div');node.className=`painted-impact effect-${visual.effect} phase-${phase} ${big?'skill-impact':'normal-impact'} ${echo?'impact-echo':''} ${visual.travel?'travelling':''}`;
 node.dataset.skill=String(visual.id);node.style.setProperty('--vfx-atlas','var(--vfx-'+visual.atlas+')');node.style.setProperty('--vfx-row',visual.row*100/3+'%');node.style.setProperty('--vfx-size',visual.size+'%');node.style.setProperty('--vfx-duration',(echo?.24:phase==='charge'?.27:.64)*factor+'s');
 const rect=$('battle').getBoundingClientRect(),hero=$('heroActor').getBoundingClientRect(),enemy=combatTargetNode().getBoundingClientRect();
 const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
 const source={x:clamp(hero.left-rect.left+hero.width*.67,rect.width*.15,rect.width*.65),y:clamp(hero.top-rect.top+hero.height*.43,rect.height*.2,rect.height*.74)};
 const target={x:clamp(enemy.left-rect.left+enemy.width*.5,rect.width*.35,rect.width*.84),y:clamp(enemy.top-rect.top+enemy.height*.48,rect.height*.25,rect.height*.70)};
 const descending=['meteor','judgment','rain','lightning'].includes(visual.effect);
 const anchor=phase==='charge'?(descending?{x:target.x,y:Math.max(40,target.y-rect.height*.15)}:source):skillId>=0&&skillMeta(skillId).target==='self'?{x:hero.left-rect.left+hero.width*.5,y:hero.top-rect.top+hero.height*.5}:target;
 node.style.left=anchor.x+'px';node.style.top=anchor.y+'px';
 node.style.setProperty('--flight-x',target.x-source.x+'px');node.style.setProperty('--flight-y',target.y-source.y+'px');
 node.innerHTML=phase==='charge'||echo?'<i class="painted-vfx-frame"></i>':'<i class="painted-vfx-frame frame-peak"></i><i class="painted-vfx-frame frame-spread"></i><i class="painted-vfx-frame frame-decay"></i>';layer.appendChild(node);setTimeout(()=>node.remove(),(phase==='charge'?285:echo?260:700)*factor);while(layer.children.length>6)layer.firstElementChild.remove();
};
combatImpact = function combatImpact(d,crit,e,token,effect,big,skillId=-1,echo=false,factor=1){if(token!==combatSerial||!sameEncounter(e))return false;const mob=$('mobActor');if(motionAllowed()){mob.classList.remove('damaged');void mob.offsetWidth;mob.classList.add('damaged');setTimeout(()=>mob.classList.remove('damaged'),240*factor)}spawnClassFx(effect,big,'impact',skillId,echo,factor);playSound('impact',{effect,big,crit,echo,skillId});applyDamage(d,crit);paintBattle();return true};
