const beforeClassPower=power,beforeClassHealth=health,beforeClassCrit=criticalChance,beforeClassSpeed=attackSpeed,beforeClassDamage=skillDamage;
power=function(){return Math.floor(beforeClassPower()*(s.classId==='warrior'?1.08:1))};
health=function(){return Math.floor(beforeClassHealth()*(s.classId==='paladin'?1.2:1))};
criticalChance=function(){return Math.min(.68,beforeClassCrit()+(s.classId==='shadow'?.08:0))};
attackSpeed=function(){return beforeClassSpeed()*(s.classId==='archer'?1.12:1)};
skillDamage=function(k,...args){if(!SKILL_RULES[k])return 0;return Math.ceil(beforeClassDamage(k,...args)*(s.classId==='mage'?1.1:1))};
