costumeSprite=function(i,extra=''){i=Number.isInteger(i)&&i>=0&&i<30?i:0;return classSprite(CLASSES[Math.floor(i/OUTFIT_STRIDE)].id,i%OUTFIT_STRIDE,'paperdoll costume-sprite costume-'+i+' '+extra)};
paintHeroCostume=function(){if(!s)return;const hero=$('heroActor'),c=currentClass(),rank=s.wear%OUTFIT_STRIDE,a=classAtlas(c.id,rank);hero.classList.remove('dressed-hero','attacking');hero.classList.add('class-hero');hero.dataset.profession=c.id;hero.dataset.costume=String(s.wear);hero.style.setProperty('--class-atlas',a.image);hero.style.setProperty('--atlas-size',a.size);hero.style.setProperty('--rank-y',a.y+'%');hero.style.setProperty('--sprite-scale',a.scale);$('battle').style.setProperty('--hero-health-height',CLASS_HEALTH_ANCHORS[c.id][rank]+'cqw');hero.style.filter='drop-shadow(0 7px 5px #1119)';hero.setAttribute('aria-label',c.name+' · '+COSTUME_NAMES[s.wear])};
