wear=function(i){if(!s.classId||!s.costumes.includes(i)||!classOutfitIds().includes(i))return false;s.wear=i;rememberClass();paint();save();return true};
costumeScreen=function(){const c=currentClass(),ids=classOutfitIds();if(!ids.includes(selectedCostume))selectedCostume=s.wear;const i=selectedCostume,owned=s.costumes.includes(i),eventWorn=eventSkinEquipped();return `<div class="wardrobe-heading"><span>${c.name}의 스킨 목록</span><button onclick="navigate('character','class')">직업 정보 <ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></button></div><div class="wardrobe-stage tier-${i%OUTFIT_STRIDE}"><div class="wardrobe-stars"></div><div class="wardrobe-pedestal"></div>${costumeSprite(i)}<button class="wardrobe-prev" onclick="changeCostume(-1)" aria-label="이전 스킨"><ui-mark data-shape=chevron-left aria-hidden=true></ui-mark></button><button class="wardrobe-next" onclick="changeCostume(1)" aria-label="다음 스킨"><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></button><span class="wardrobe-rarity">${CLASS_RANKS[i%OUTFIT_STRIDE]} · ${owned?'Lv.'+s.costumeLevels[i]:'미보유 미리보기'}</span></div><div class="wardrobe-title"><h2>${COSTUME_NAMES[i]}</h2><p>${c.role} · ${CLASS_RANKS[i%OUTFIT_STRIDE]} 스킨</p><small>스킨을 바꿔도 직업과 전용 스킬은 유지됩니다.</small></div><div class="action-row">${button(!eventWorn&&s.wear===i?'<ui-mark data-shape=check aria-hidden=true></ui-mark> 착용 중':owned?'이 스킨 착용':'미보유',`wear(${i})`,!owned||!eventWorn&&s.wear===i)}${button('스킨 룰렛',"navigate('shop','costumes')",false,true)}</div><div class="wardrobe-grid class-wardrobe">${ids.map(j=>`<button class="wardrobe-card ${j===i?'selected':''} ${!eventWorn&&s.wear===j?'worn':''} ${s.costumes.includes(j)?'owned':'unowned'}" onclick="selectCostume(${j})" aria-pressed="${j===i}">${costumeSprite(j)}<strong>${COSTUME_NAMES[j]}</strong><small>${CLASS_RANKS[j%OUTFIT_STRIDE]} · ${!eventWorn&&s.wear===j?'착용 중':s.costumes.includes(j)?'보유':'미보유'}</small></button>`).join('')}</div><div class="wardrobe-collection"><span>모든 직업 스킨 <b>${s.costumes.length} / 30</b></span></div><p class="small">현재 직업 스킨만 등장하며, 중복은 별 강화에 사용합니다.</p>`};
costumeRoulette=function(){return `<div class="summary-strip"><b>${currentClass().name} 전용 스킨</b><span>6등급 · 직업별 6종</span></div><div class="resource-note">${art('rouletteCoin')}룰렛 코인 <b>${s.rouletteCoins}</b>${art('gem')}<b>${num(s.gems)}</b></div><div class="roulette-wheel"><div class="wheel-runes"><ui-mark data-shape=spark aria-hidden=true></ui-mark></div>${costumeSprite(s.wear)}</div><div class="costume-pity"><span>전설 이상 확정 <b>${100-s.rolls%100}회</b></span><span>천상 확정 <b>${500-s.rolls%500}회</b></span></div><div class="action-row">${button('1회 · 다이아 300','spinCostume(1)',s.gems<300,true)}${button('10회 · 다이아 2,700','spinCostume(10)',s.gems<2700)}</div><div class="action-row">${button('코인 1개','spinCostume(1,true)',s.rouletteCoins<1,true)}${button('코인 10개','spinCostume(10,true)',s.rouletteCoins<10,true)}</div><div class="probability-summary six-ranks">${CLASS_RANKS.map((r,i)=>`<span>${r} <b>${COSTUME_RATES[i]}%</b></span>`).join('')}</div><p class="small">현재 직업 전용. 100회마다 전설 이상, 500회마다 천상 확정. 누적 횟수는 직업 공통이며 중복은 별 강화에 사용합니다.</p><div class="action-row">${button('보유 스킨',"navigate('character','costume')",false,true)}</div>`};


const beforeClassArt=art;
art=function(name,cls=''){const match=/^s(\d+)$/.exec(name);return match&&CLASS_SKILLS[+match[1]]?skillArt(+match[1]):beforeClassArt(name,cls)};
const beforeClassSkillLevel=skillLevel;
skillLevel=function(k,max=false){if(!skillUnlocked(k)){notice('현재 직업과 해금 스테이지를 확인하세요');return false}beforeClassSkillLevel(k,max);return true};
levelAllSkills=function(maximum=false){let count=0;for(let r=0;r<(maximum?100:1);r++){let done=0;for(const k of classSkillIds()){if(skillUnlocked(k)&&s.skills[k]&&s.skills[k]<100&&s.shards>=skillCost(k)){s.shards-=skillCost(k);s.skills[k]++;done++;count++}}if(!done)break}s.daily.upgrades=(s.daily.upgrades||0)+count;paint();save();if(!count)notice('강화 가능한 스킬이 없습니다')};
const beforeClassSetSlot=setSlot;
setSlot=function(slot,k){if(!Number.isInteger(slot)||slot<0||slot>3||!skillUnlocked(k))return false;beforeClassSetSlot(slot,k);rememberClass();save();return true};
slotSkill=function(k){if(!skillUnlocked(k)||!s.skills[k]){notice('아직 사용할 수 없는 스킬입니다');return}openMenu('slot',k)};
autoEquipSkills=function(){unlockClassSkills();s.slots=classSkillIds().map((k,i)=>slotOpen(i)&&skillUnlocked(k)?k:-1);rememberClass();paint();save()};
summonRates=function(){return `<p class="small">${currentClass().name} 전용 스킬만 소환됩니다. 미해금 스킬은 보관되며 STAGE 10·30에 사용할 수 있습니다.</p><div class="effect-table">${classSkillIds().map((k,i)=>`<div><span>${SK[k][0]}</span><b>${[35,35,25,5][i]}%</b></div>`).join('')}</div>`};
EXTRA_POPUPS.summonRates=['직업 스킬 소환 확률',summonRates];
skillsScreen=function(){if(screenTab==='summon')return `<div class="summary-strip">${currentClass().name} 전용 스킬 소환</div>`+summonScreen('skills');unlockClassSkills();return `<div class="class-skill-heading"><div><h2>${currentClass().name}</h2></div><button class="muted-button" onclick="navigate('character','class')">직업 정보</button></div><p class="small">${currentClass().passive} · 스킬 3·4는 STAGE 10·30에 해금</p><div class="skill-equipped">${s.slots.map((k,i)=>`<button onclick="${k>=0?`openMenu('skillDetail',${k})`:"notice('STAGE 10·30에서 해금됩니다')"}">${k>=0?skillArt(k):skillLock()}<span class="slot-number">${i+1}</span><small>${k>=0?SK[k][0]:'STAGE '+CLASS_GATES[i]}</small></button>`).join('')}</div><div class="resource-note">${art('shard')}스킬 조각 <b>${num(s.shards)}</b></div><div class="class-skill-list">${classSkillIds().map((k,i)=>`<button class="class-skill-card ${skillUnlocked(k)?'':'locked'}" onclick="openMenu('skillDetail',${k})">${skillArt(k)}<span><strong>${SK[k][0]} <em>${s.skills[k]?'Lv.'+s.skills[k]:''}</em></strong><small>${CLASS_SKILLS[k][5]}</small><b>${skillUnlocked(k)?'재사용 '+SKILL_RULES[k].cd+'초 · '+SKILL_RULES[k].hits+'회 타격':'STAGE '+CLASS_GATES[i]+' 해금'}</b></span><i><ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></i></button>`).join('')}</div><div class="action-row">${button('추천 장착','autoEquipSkills()',false,true)}${button('일괄 강화','levelAllSkills(false)')}${button('최대 강화','levelAllSkills(true)',false,true)}</div>`};
skillPopup=function(){const k=Number(tab),r=SKILL_RULES[k];if(!r)return '<p>스킬을 찾을 수 없습니다.</p>';const lv=s.skills[k]||0,ready=skillUnlocked(k);return `<div class="popup-hero class-skill-detail">${skillArt(k)}<div class="badge">${CLASSES[Math.floor(k/4)].name} 전용</div><h3>${SK[k][0]} · Lv.${lv}</h3><p>${CLASS_SKILLS[k][5]}</p></div><div class="effect-table"><div><span>총 피해 · ${r.hits}회 타격</span><b>${compact(skillDamage(k))}</b></div><div><span>재사용 대기</span><b>${r.cd}초</b></div><div><span>해금</span><b>STAGE ${CLASS_GATES[k%4]}</b></div><div><span>강화 재료</span><b>조각 ${s.shards} / ${skillCost(k)}</b></div></div><div class="action-row">${button('강화',`skillLevel(${k})`,!ready||lv>=100||s.shards<skillCost(k))}${button('슬롯에 장착',`slotSkill(${k})`,!ready||!lv,true)}</div>`};
paintSkillButtons=function(){$('skillbuttons').innerHTML=s.slots.map((k,i)=>`<button class="${!slotOpen(i)||k<0?'locked':''}" onclick="cast(${i})" aria-label="${k<0?'STAGE '+CLASS_GATES[i]+' 해금':SK[k][0]}">${k<0?skillLock():skillArt(k)}<small id="cool${i}" style="display:${cooldowns[i]>0?'grid':'none'}">${Math.ceil(cooldowns[i])}</small><em>${i+1}</em><span class="battle-skill-name">${k<0?'잠김':SK[k][0]}</span></button>`).join('')};
const beforeClassPaint=paint,beforeClassBattle=paintBattle,beforeClassSave=save;
paint=function(){if(s?.classId)unlockClassSkills();beforeClassPaint();if(s){paintHeroCostume();showClassOnboarding()}};
paintBattle=function(){beforeClassBattle();if(s)paintHeroCostume()};
save=function(){rememberClass();recordPower();beforeClassSave()};
const beforeClassIdentity=identityPane,beforeClassStats=statsPane;
identityPane=function(){return `<button class="class-profile-link" onclick="navigate('character','class')"><span>${currentClass().name} · ${currentClass().role}</span><b>직업 정보 <ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></b></button>`+beforeClassIdentity()};
statsPane=function(){return `<div class="class-profile-stat"><b>${currentClass().name}</b><span>${currentClass().passive}</span></div>`+beforeClassStats()};





// Each skill owns a painted four-frame sequence; shared mechanics never share visual identity.
const SKILL_VFX=CLASS_SKILLS.map((v,k)=>({id:k,atlas:CLASSES[Math.floor(k/4)].id,row:k%4,effect:v[1],travel:[4,12,16,17,18].includes(k),size:[62,65,78,82,60,66,73,80,68,72,70,82,73,78,76,86,59,70,72,82][k]}));



hit=function(){return performClassAttack()};
cast=function(i,automatic=false){if(!Number.isInteger(i)||i<0||i>3||!s.classId)return false;const k=s.slots[i];if(!slotOpen(i)||!skillUnlocked(k)||!s.skills[k]){if(!automatic)notice('스킬 해금과 장착 상태를 확인하세요');return false}if(cooldowns[i]>0){if(!automatic)notice('재사용 대기 '+Math.ceil(cooldowns[i])+'초');return false}if(!performClassAttack(k,automatic))return false;cooldowns[i]=SKILL_RULES[k].cd;paintCooldowns();return true};
