// A delayed impact belongs to one encounter and must never follow a reset or travel.
const classBeforeTravel=travel,classBeforeRegionTravel=travelToRegion,classBeforeRetry=retryBoss,classBeforeRetreat=retreatBoss,classBeforeTestReset=resetTestCombat;
travel=function(d){cancelCombatAnimation();return classBeforeTravel(d)};
travelToRegion=function(i){cancelCombatAnimation();return classBeforeRegionTravel(i)};
retryBoss=function(){cancelCombatAnimation();return classBeforeRetry()};
retreatBoss=function(){cancelCombatAnimation();return classBeforeRetreat()};
