passTotals = function passTotals(track='free'){return (track==='premium'?PREMIUM_PASS_REWARDS:SEASON_PASS_REWARDS).reduce((sum,r)=>{for(const [k,n]of Object.entries(r.reward))sum[k]=(sum[k]||0)+n;return sum},{})};
passSeasonEnd = function passSeasonEnd(now=Date.now()){return seasonStart+(seasonCycle(now)+1)*seasonLength};
seasonDaysLeft = function seasonDaysLeft(now=Date.now()){return Math.ceil((passSeasonEnd(now)-now)/86400000)};
