 layer.innerHTML='<div class="fallen-creature '+(e.boss?'fallen-boss':'')+'">'+art(e.art)+'</div><div class="defeat-caption"><b>'+(e.boss?'BOSS CLEAR':'처치 완료')+'</b><span>'+safeText(e.name)+'</span></div>';
