masterworkDef = function masterworkDef(g){const i=g?.masterwork;return Number.isInteger(i)&&MASTERWORKS[i]&&g.r===MASTERWORKS[i].r&&Number.isInteger(g.p)&&g.p>=0&&g.p<7?MASTERWORKS[i]:null};
normalizeMasterworks = function normalizeMasterworks(a,raw=a){if(raw.masterworkVersion!==1){a.legacyShowcasePower=a.showcase.reduce((sum,n)=>sum+n,0)*(.001-.00003)}a.legacyShowcasePower=bounded(a.legacyShowcasePower,0,7);for(const g of a.gear){if(masterworkDef(g)){g.set=MASTERWORK_SET_OFFSET+g.masterwork;}else{delete g.masterwork;if(!isPlainStarter(g))g.set=REGIONAL_SET_IDS.includes(g.set)?g.set:Math.floor(bounded(g.set,0,MASTERWORK_SET_OFFSET-1))}}a.masterworkVersion=1;return a};
masterworkSample = function masterworkSample(i,p){return {id:'masterwork_preview',p,r:MASTERWORKS[i].r,plus:0,set:MASTERWORK_SET_OFFSET+i,masterwork:i,locked:true}};
masterworkUnlocked = function masterworkUnlocked(i){const t=MASTERWORKS[i];return !!t&&s.campaignCleared>=t.stage&&s.level>=t.level&&s.forgeLevel>=t.forge};
masterworkBlock = function masterworkBlock(i,p){const t=MASTERWORKS[i];if(!t||!Number.isInteger(p)||p<1||p>6)return '장비를 선택하세요';if(dungeonRun||forgeBusy)return '전투 도전·제작 완료 후 이용하세요';if(!masterworkUnlocked(i))return '해금 조건을 달성하세요';if(s.gear.length>=GEAR_CAPACITY)return '장비 가방에 빈칸이 필요합니다';if(Object.entries(t.cost).some(([k,n])=>s[k]<n))return '제작 재료가 부족합니다';return ''};
craftMasterwork = function craftMasterwork(i,p){const block=masterworkBlock(i,p);if(block){notice(block);return false}const t=MASTERWORKS[i];for(const[k,n]of Object.entries(t.cost))s[k]-=n;s.crafted++;const g={...masterworkSample(i,p),id:'mw_'+Date.now().toString(36)+'_'+s.crafted};g.discovered=!s.unlocked[g.p+'_'+g.r];s.gear.push(g);s.unlocked[g.p+'_'+g.r]=true;if(s.autoEquip&&gearValue(g)>gearValue(equippedItem(g.p)))s.equipped[g.p]=g.id;advanceForge(1);trackOrderEvent('crafted');s.daily.crafted=(s.daily.crafted||0)+1;s.weekly.crafted=(s.weekly.crafted||0)+1;lastLoot=[g];s.lastLoot=lastLoot;save();paint();openMenu('loot');playSound('forge');return true};
selectMasterwork = function selectMasterwork(i){if(!Number.isInteger(i)||!MASTERWORKS[i])return;masterworkTier=i;renderScreen(false)};
selectMasterworkPart = function selectMasterworkPart(p){if(!Number.isInteger(p)||p<1||p>6)return;masterworkPart=p;renderScreen()};
equipmentStatsPreview = function equipmentStatsPreview(g){const previousGear=s.gear,previousEquipped=s.equipped;const stats=()=>({attack:power(),health:health(),speed:attackSpeed(),critical:criticalChance(),penetration:armorPenetration(),critDamage:criticalDamageBonus(),skill:setBonuses().skill});const before=stats();try{s.gear=[...previousGear.filter(x=>x.id!==g.id),g];s.equipped={...previousEquipped,[g.p]:g.id};return{before,after:stats()}}finally{s.gear=previousGear;s.equipped=previousEquipped}};
masterworkRequirements = function masterworkRequirements(t){return [['스테이지',stageText(t.stage)+' 클리어',s.campaignCleared>=t.stage],['캐릭터','Lv.'+t.level,s.level>=t.level],['모루','Lv.'+t.forge,s.forgeLevel>=t.forge]].map(([label,value,ready])=>'<span class="'+(ready?'ready':'')+'"><small>'+label+'</small><b>'+(ready?'<ui-mark data-shape=check aria-hidden=true></ui-mark> ':'')+value+'</b></span>').join('')};
masterworkScreen = function masterworkScreen(){const i=masterworkTier,p=masterworkPart,t=MASTERWORKS[i],g=masterworkSample(i,p),preview=equipmentStatsPreview(g),worn=equippedItem(p),delta=gearValue(g)-gearValue(worn),block=masterworkBlock(i,p);return `<div class="masterwork-intro"><h2>모험으로 여는 명장 장비</h2><p>필요한 부위를 선택해 확정 제작하세요.</p></div><div class="masterwork-tiers">${MASTERWORKS.map((x,j)=>`<button class="${i===j?'active':''}${masterworkUnlocked(j)?'':' locked'}" onclick="selectMasterwork(${j})" aria-pressed="${i===j}">${gearArt(masterworkSample(j,0))}<b>${x.short}</b><small>${masterworkUnlocked(j)?'해금':lockMark()+' 잠김'}</small></button>`).join('')}</div><section class="masterwork-card" style="--masterwork-color:${t.color}"><div class="masterwork-hero">${gearArt(g)}<div><small>${t.name} · ${RAR[t.r]}</small><h3>${equipmentTitle(g)}</h3><span>${PARTS[p]} 슬롯 +${s.gearSlotLevels[p]} / +15</span></div></div><div class="masterwork-requirements">${masterworkRequirements(t)}</div><div class="masterwork-parts">${PARTS.map((name,j)=>j===0?'':`<button class="${j===p?'selected':''}" onclick="selectMasterworkPart(${j})" aria-pressed="${j===p}" aria-label="${t.names[j]} 선택">${gearArt(masterworkSample(i,j))}<small>${name}</small></button>`).join('')}</div><div class="masterwork-effect"><div><span>장비 효과</span><b>${compact(gearValue(g))}</b><small>현재 착용 대비 ${delta>=0?'+':'−'}${compact(Math.abs(delta))}</small></div><div><span>착용 후 공격력</span><b>${compact(preview.after.attack)}</b><small>현재 ${compact(preview.before.attack)}</small></div><div><span>착용 후 체력</span><b>${compact(preview.after.health)}</b><small>현재 ${compact(preview.before.health)}</small></div></div><p class="small">착용 후 공격속도 ${preview.after.speed.toFixed(2)}× · 치명타 ${(preview.after.critical*100).toFixed(1)}%</p><p class="small">명장 장비는 같은 등급·강화에서 기본 효과 +5%. 무기·장갑은 공격, 방어구는 체력, 신발은 공속, 장신구는 치명타가 오릅니다.</p><div class="masterwork-costs">${Object.entries(t.cost).map(([k,n])=>`<div class="${s[k]>=n?'enough':''}">${art(RESOURCE_ART[k])}<span>${RESOURCE_NAMES[k]}</span><b>${compact(n)}</b><small>보유 ${compact(s[k])}</small></div>`).join('')}</div>${button(block||'선택 장비 확정 제작',`animateMasterwork(${i},${p})`,!!block)}<p class="small masterwork-rules">제작당 모루 경험치 +1. 전 직업 공용이며 제작 즉시 잠깁니다.</p></section>${masterworkSetPanel(MASTERWORK_SET_OFFSET+i)}`};
showcaseBonus = function showcaseBonus(){return (s.legacyShowcasePower||0)+Math.min(.21,s.showcase.reduce((sum,n)=>sum+n,0)*SHOWCASE_POINT_BONUS)};
