inventoryPopup=function(){
 if(inventorySet>=0&&!s.gear.some(g=>g.set===inventorySet))inventorySet=-1;
 const worn=PARTS.map((_,i)=>equippedItem(i));
 const list=s.gear.filter(g=>matchesBagFilters(g)&&(!bagSalvageSelection||s.equipped[g.p]!==g.id)).sort((a,b)=>b.r-a.r||a.p-b.p||a.set-b.set);
 const sets=[...new Set(s.gear.map(g=>g.set).filter(id=>SET_PROFILES[id]))].sort((a,b)=>a-b);
 return materialHUD('stone','강화석',s.stones,'',false)+`<div class="filter-chips"><button class="${inventoryPart<0?'active':''}" onclick="inventoryFilter(-1)">전체</button>${PARTS.map((n,p)=>`<button class="${inventoryPart===p?'active':''}" onclick="inventoryFilter(${p})">${n}</button>`).join('')}</div><label class="inventory-set-filter">세트별 보기<select onchange="filterInventorySet(Number(this.value))"><option value="-1">전체 세트</option>${sets.map(id=>`<option value="${id}" ${inventorySet===id?'selected':''}>${REGION_SETS[id]}</option>`).join('')}</select></label>${bagSalvageSelection?salvageBar(bagSalvageSelection,true):`<div class="bag-tools"><span class="small">보유 ${s.gear.length}/${GEAR_CAPACITY}</span><button class="gold-button" onclick="salvageLow()" ${list.some(g=>canSalvage(g)&&g.r<=1)?'':'disabled'}>일반 · 매직 분해</button><button class="gold-button" onclick="startBagSelection()"${list.some(canSalvage)?'':' disabled'}>분해</button></div>`}<div class="collection-grid4">${list.map(g=>equipmentTile(g,g,bagSalvageSelection,false,bagSalvageSelection?null:bagComparison(g,worn[g.p]))).join('')}</div>${list.length?'':`<div class="empty-state">${bagSalvageSelection?'이 조건에 맞는 미착용 장비가 없습니다.':'이 조건의 장비가 없습니다.'}</div>`}`;
};






