// game script 22
activeOutfitEventId = function activeOutfitEventId(now=Date.now()){
 return PHOENIX_EVENT.end!==null && now>=PHOENIX_EVENT.end ? SEASON_TWO_ID : PHOENIX_EVENT.id;
};
seasonTwoArt = function seasonTwoArt(job,kind){return './assets/season-outfits/'+job+'-'+kind+'.webp?v='+(job==='archer'?142:134)};
royalEventActive = function royalEventActive(now=Date.now()){
 const start=PHOENIX_EVENT.start;
 return start===null||now>=start&&now<start+2*PHOENIX_EVENT.duration;
};
royalEventState = function royalEventState(a=s,id=activeOutfitEventId()){return a?.costumeEvents?.[id]};
royalClassState = function royalClassState(a=s,job=a?.classId,id=activeOutfitEventId()){return royalEventState(a,id)?.classes[job]};
eventSkinOwned = function eventSkinOwned(a=s,job=a?.classId,id=activeOutfitEventId()){return royalClassState(a,job,id)?.owned===true};
eventSkinEquipped = function eventSkinEquipped(job=s?.classId){return !!wornEventId(job)};
outfitRigRank = function outfitRigRank(){const id=wornEventId();return id===SEASON_TWO_ID?'season2':id?'event':s.wear%OUTFIT_STRIDE};
eventCostumeName = function eventCostumeName(id=s.classId,season=activeOutfitEventId()){return season===SEASON_TWO_ID?SEASON_OUTFIT_NAMES[id]||SEASON_TWO_THEME:ROYAL_THEME+' · '+CLASSES[Math.max(0,classIndex(id))].name};
eventCostumeSprite = function eventCostumeSprite(id=s.classId,extra=''){
 const c=CLASSES[Math.max(0,classIndex(id))];
 return `<div class="class-sprite paperdoll costume-sprite event-costume-sprite ${extra}" data-event-profession="${c.id}" style="--class-atlas:var(--royal-${c.id});--atlas-size:400% 500%;--rank-y:100%;--sprite-scale:1;${displayFootStyle(c.id,6)}" role="img" aria-label="${eventCostumeName(c.id,PHOENIX_EVENT.id)} 이벤트 스킨"></div>`;
};
wornCostumeSprite = function wornCostumeSprite(extra=''){return eventSkinEquipped()?eventCostumeSprite(s.classId,extra,wornEventId()):costumeSprite(s.wear,extra)};
wornCostumeName = function wornCostumeName(){return eventSkinEquipped()?eventCostumeName(s.classId,wornEventId()):COSTUME_NAMES[s.wear]};
oldCostumeEffect = function oldCostumeEffect(a){
 let total=CLASSES.filter((_,i)=>[1,2,3].every(r=>a.costumes.includes(i*OUTFIT_STRIDE+r))).length*.01;
 for(const i of a.costumes){const r=i%OUTFIT_STRIDE,lv=a.costumeLevels[i]||1;total+=[.01,.03,.06,.12,.16,.2][r]+(lv-1)*[.005,.0125,.0225,.045,.06,.08][r]}
 return Math.min(.2,total);
};
normalizeRoyalRoulette = function normalizeRoyalRoulette(a,raw={}){
 const modern=raw.rouletteVersion>=2,priorEvent=raw.rouletteVersion===1;
 const prev=recordMap(recordMap(raw.costumeEvents)[PHOENIX_EVENT.id]),levels=recordMap(prev.levels);
 const separate=Number(raw.rouletteVersion)>=4;
 const count=(n,cap=Number.MAX_SAFE_INTEGER)=>Math.floor(bounded(n,0,cap));
 const oldRolls=count(modern?prev.rolls:priorEvent?raw.rolls:0);
 const oldPity=count(modern?prev.pity:priorEvent?raw.rouletteSkinPity:0,ROYAL_SKIN_PITY-1);
 const oldOwner=modern&&prev.owned===true||CLASSES.some(c=>count(levels[c.id])>0||priorEvent&&a.costumes.includes(classIndex(c.id)*6+5));
 let legacyEventLevel=0;
 a.royalTitlePity=count(separate?raw.royalTitlePity:oldRolls,ROYAL_TITLE_PITY-1);
 a.eventWear={};a.costumeEvents={};
 for(const id of [PHOENIX_EVENT.id,SEASON_TWO_ID]){
  const prior=recordMap(raw.costumeEvents?.[id]),classes={};
  for(const c of CLASSES){
   const saved=recordMap(prior.classes?.[c.id]);
   const legacy=!separate&&id===PHOENIX_EVENT.id,carry=legacy&&c.id===a.classId;
   const owned=separate?saved.owned===true:legacy&&oldOwner;
   classes[c.id]={owned,rolls:count(separate?saved.rolls:carry?oldRolls:0),
    pity:count(separate?saved.pity:carry?oldPity:0,ROYAL_SKIN_PITY-1)};
   const regular=classIndex(c.id)*6+5;
   const woreLegacy=legacy&&priorEvent&&(raw.classLoadouts?.[c.id]?.wear===regular||raw.classId===c.id&&raw.wear===regular);
   if(owned&&(raw.eventWear?.[c.id]===id||woreLegacy))a.eventWear[c.id]=id;
   if(legacy)legacyEventLevel=Math.max(legacyEventLevel,count(levels[c.id],5),woreLegacy?1:0);
  }
  a.costumeEvents[id]={missions:normalizeWheelJournal(prior.missions),rolls:count(separate?prior.rolls:id===PHOENIX_EVENT.id?oldRolls:0),classes};
 }
 a.normalCostumeRolls=Math.floor(bounded(modern?raw.normalCostumeRolls:raw.rolls));
 a.costumeLegacyFloor=bounded(raw.costumeLegacyFloor,0,.6);
 if(raw.costumeStatsVersion!==1){
  // Freeze previously earned effects once; legacy levels never remain active or grow.
  const legacySteps=[0,.0025,.005,.0075,.01,.025];
  const ranks=CLASS_RANKS.map((_,rank)=>Math.max(rank===5?legacyEventLevel:0,...a.costumes.filter(i=>i%OUTFIT_STRIDE===rank).map(i=>a.costumeLevels?.[i]||1)));
  const previous=raw.rouletteVersion?ranks.reduce((sum,level,rank)=>sum+(level?HOLD_BASE[rank]+(level-1)*legacySteps[rank]:0),0)+(ranks.slice(1).every(Boolean)?.01:0):oldCostumeEffect(a);
  a.costumeLegacyFloor=Math.min(.6,Math.max(a.costumeLegacyFloor,previous));
 }
 a.costumeStatsVersion=1;a.rouletteVersion=4;delete a.costumeLevels;delete a.rouletteSkinPity;return a;
};
royalDrawPool = function royalDrawPool(state=s,season=activeOutfitEventId()){
 const job=state.classId;
 const slots=ROYAL_SLOTS.map(slot=>{
  if(slot.kind==='eventSkin'){
   const row={event:true,job,season},owned=eventSkinOwned(state,job,season);
   return {...slot,name:eventCostumeName(job,season),owned,closed:owned&&skinCopies(row,state)>=copiesToFinish(row,skinRowLevel(row,state))};
  }
  const owned=slot.kind==='title'&&titleOwned(slot.title,state);return {...slot,owned,closed:owned};
 });
 const resources=slots.reduce((sum,slot)=>sum+(slot.kind==='resource'?slot.weight:0),0);
 const closedWeight=slots.reduce((sum,slot)=>sum+(slot.closed?slot.weight:0),0);
 return slots.map(slot=>({...slot,drawWeight:slot.closed?0:slot.kind==='resource'?slot.weight*(1+closedWeight/resources):slot.weight}));
};
royalPityFor = function royalPityFor(kind,progress=royalClassState(),state=s){
 if(kind==='eventSkin')return progress?.pity||0;
 return kind==='title'?state.royalTitlePity||0:0;
};
royalDue = function royalDue(pool,state=s,progress=royalClassState(state)){
 return pool.filter(slot=>!slot.closed&&ROYAL_LIMITS[slot.kind]&&royalPityFor(slot.kind,progress,state)>=ROYAL_LIMITS[slot.kind]-1);
};
royalDrawWeightTotal = function royalDrawWeightTotal(pool){return pool.reduce((sum,slot)=>sum+slot.drawWeight,0)};
royalPick = function royalPick(random,pool){
 const point=Math.max(0,Math.min(1,random))*royalDrawWeightTotal(pool);
 let total=0;
 return pool.find(slot=>{total+=slot.drawWeight;return point<total})||pool.filter(slot=>slot.drawWeight>0).at(-1);
};
royalSlotArt = function royalSlotArt(slot,job=s.classId){
 if(slot.kind==='eventSkin')return eventCostumeSprite(job,'royal-skin-icon',slot.season||activeOutfitEventId());
 if(slot.kind==='title')return titleEmblem();
 return art(RESOURCE_ART[Object.keys(slot.reward)[0]]);
};
royalSlotDetail = function royalSlotDetail(slot){
 return ROYAL_LABELS[slot.kind]||num(Object.values(slot.reward)[0])+(slot.id==='forgeGuard'?'장':'개');
};
addEventCostume = function addEventCostume(profession,state=s,season=activeOutfitEventId()){
 const progress=royalClassState(state,profession,season);
 if(!progress)return false;
 if(progress.owned)return addSkinCopy({event:true,job:profession,season},state);
 progress.owned=true;progress.pity=0;return CLASSES[classIndex(profession)].name+' 한정 스킨 획득';
};
