// game script 24
growthBonus = function growthBonus(i,level=s.stats[i]??1){
 const rule=GROWTH_RULES[i],end=Math.min(level,rule.max);
 let from=1,step=rule.step,total=0;
 for(let j=0;j<(rule.later?.length||0)&&end>GROWTH_THRESHOLDS[j];j++){
  const threshold=GROWTH_THRESHOLDS[j];
  total+=(threshold-from)*step;from=threshold;step=rule.later[j];
 }
 total+=Math.max(0,end-from)*step;
 return Math.min(rule.bonusCap??Infinity,Math.round(total*10000)/10000);
};
growthStepHint = function growthStepHint(i){
 const level=s.stats[i]??1;
 if(growthAtLimit(i))return '현재 최대 효과';
 return '다음 1회 '+growthPercent(i,growthBonus(i,level+1)-growthBonus(i,level));
};
growthCostAt = function growthCostAt(i,level){const r=GROWTH_RULES[i];return Math.ceil(r.base*Math.pow(1.13,(level-1)/r.split))};
growthAtLimit = function growthAtLimit(i,level=s.stats[i]){
 const rule=GROWTH_RULES[i],bonus=growthBonus(i,level);
 if(level>=rule.max||bonus>=(rule.bonusCap??Infinity))return true;
 const extra=bonus-growthBonus(i);
 if(i===1)return beforeClassSpeed()+extra>=3-1e-9;
 if(i===4)return criticalChance()+extra>=.6+(s.classId==='shadow'?.08:0)-1e-9;
 if(i===5)return armorPenetration()+extra>=1-1e-9;
 return false;
};
growthOffers = function growthOffers(i,limit=50){
 const offers=new Map(),level=s.stats[i]??1;
 let steps=0,total=0;
 for(const size of GROWTH_BATCHES){
  if(size>limit||growthAtLimit(i,level+size-1))break;
  while(steps<size){
   total+=growthCostAt(i,level+steps);
   if(total>s.gold)return offers;
   steps++;
  }
  offers.set(size,total);
 }
 return offers;
};
growthPreview = function growthPreview(i,exact,offers=growthOffers(i,exact??s.growthBatch)){
 const limit=exact??s.growthBatch,level=s.stats[i]??1;
 let count=0;
 for(const size of offers.keys())if(exact===undefined?size<=limit:size===exact)count=size;
 return {count,cost:offers.get(count)||0,level:level+count,before:growthBonus(i),after:growthBonus(i,level+count),capped:growthAtLimit(i)};
};
growthPercent = function growthPercent(i,value){return '+'+Number((value*100).toFixed(2))+(i>=4?'%p':'%')};
gearSpecialties = function gearSpecialties(g){
 const pair=GEAR_SPECIALTIES[g.set],weight=GEAR_SPECIALTY_BUDGET[g.r];
 if(!g.p||!pair||!weight)return {};
 const [primary,secondary]=pair,result={[primary]:GEAR_SPECIALTY_RATES[primary]*weight};
 if(g.r>=5)result[secondary]=GEAR_SPECIALTY_RATES[secondary]*(weight-GEAR_SPECIALTY_BUDGET[4])*.42;
 return result;
};
setEffects = function setEffects(id,count){const out={};for(let i=0;i<3;i++)if(count>=[2,4,6][i])for(const [key,n] of Object.entries(SET_PROFILES[id]?.[1][i]||{}))out[key]=(out[key]||0)+n;return out};
setBonusText = function setBonusText(effects){return Object.entries(effects).map(([key,n])=>SET_STAT_NAMES[key]+' +'+Number((n*100).toFixed(2))+(['critical','penetration'].includes(key)?'%p':'%')).join(' · ')};
criticalDamageBonus = function criticalDamageBonus(){return .10+growthBonus(6)+setBonuses().critDamage+costumeBonus('critDamage')+costumeWearBonus('critDamage')+petSpecial('critDamage')+(s.relics[7]||0)*.01+weaponEnhancementBonus('critDamage')+skinBonus('critDamage')+trialMod('critDamage')};
criticalDamageMultiplier = function criticalDamageMultiplier(){return 1+criticalDamageBonus()};
criticalDamageText = function criticalDamageText(percent){return '+'+Number(percent.toFixed(2))+'%'};
setBonusRows = function setBonusRows(id,count){return `<div class="set-bonus-list">${[2,4,6].map((need,i)=>`<div class="${count>=need?'bonus-active':''}"><span>${need}부위</span><b>${setBonusText(SET_PROFILES[id][1][i])}</b><small>${count>=need?'적용':'미적용'}</small></div>`).join('')}</div>`};
masterworkSetPanel = function masterworkSetPanel(id){return `<div class="card masterwork-set"><h3>${REGION_SETS[id]} · ${SET_PROFILES[id][0]}</h3>${setBonusRows(id,setBonuses().counts[id])}<p class="small">6부위 합계 · ${setBonusText(setEffects(id,6))}. 같은 세트끼리만 합산합니다.</p></div>`};
gearStat = function gearStat(g,level){const v=level===undefined?gearValue(g):baseGearValue(g,level)*(masterworkDef(g)?MASTERWORK_MULTIPLIER:1),p=g?.p;return p===0||p===4?{label:'기본 공격력',value:v,unit:'',digits:0}:p===5?{label:'공격속도',value:v*.05,unit:'%',digits:2}:p===6?{label:'치명타 확률',value:v*.005,unit:'%p',digits:2}:{label:'기본 체력',value:v*10,unit:'',digits:0}};
gearStatNumber = function gearStatNumber(effect,value=effect.value){return effect.digits?value.toFixed(effect.digits)+effect.unit:num(Math.round(value))};
signedNumber = function signedNumber(value,digits=0){return (value>0?'+':value<0?'−':'')+Math.abs(value).toFixed(digits)};
newbieReady = function newbieReady(i){
 if(!Number.isInteger(i)||!NEWBIE_MISSIONS[i]||s.eventClaims['newbieGift'+i])return false;
 const [,value,goal]=NEWBIE_MISSIONS[i];
 return !!s.eventClaims['newbie'+i]||value()>=goal;
};
newbieReward = function newbieReward(i){
 const reward=NEWBIE_MISSIONS[i][3];
 if(!s.eventClaims['newbie'+i]||s.eventClaims['newbieGift'+i])return reward;
 // Older saves already received a flat diamond and ore bundle for this mission.
 const extra={};
 for(const [key,amount] of Object.entries(reward)){
  const remaining=amount-(LEGACY_NEWBIE_REWARD[key]||0);
  if(remaining>0)extra[key]=remaining;
 }
 return extra;
};
newbieMissionRow = function newbieMissionRow([name,value,goal],i){
 const completed=!!s.eventClaims['newbie'+i],paid=!!s.eventClaims['newbieGift'+i];
 const progress=Math.min(value(),goal),ready=newbieReady(i);
 const action=paid?'수령 완료':completed?'추가 보상':ready?'보상 받기':'진행 중';
 const rewards=Object.entries(newbieReward(i)).map(([key,n])=>
  `<span>${art(RESOURCE_ART[key])}${RESOURCE_NAMES[key]} ${num(n)}</span>`
 ).join('');
 return `<article class="newbie-mission"><div><h3>${name}</h3><span>${completed?'<ui-mark data-shape=check aria-hidden=true></ui-mark> 완료':num(progress)+' / '+num(goal)}</span></div>
  <div class="bar"><i style="width:${completed?100:progress/goal*100}%"></i></div>
  <footer><small class="newbie-rewards">${rewards}</small>${button(action,`claimNewbie(${i})`,!ready)}</footer></article>`;
};
/* Shared balance data: the same values drive combat, previews and equipment UI. */
'use strict';
const GROWTH_BATCHES=[1,10,50];
// Thresholds refer to the current ability level before buying the next upgrade.
const GROWTH_THRESHOLDS=[25,50,100,200,400,800,1600,3200];
const GROWTH_RULES=[
 {step:.02,later:[.03,.04,.06,.08,.10,.12,.16,.20],max:3598,base:10,split:3,previousMax:1200},
 {step:.005,later:[.006,.0075,.01,.0125],bonusCap:1.5,max:301,base:100/3,split:3,previousMax:101},
 {step:.01,max:2399,base:75,split:2,previousMax:1200},
 {step:.035,later:[.04,.05,.06,.075,.09,.11,.13],max:2399,base:15,split:2,previousMax:1200},
 {step:.0025,later:[.005,.0075],max:100,base:60,split:2,previousMax:61},
 {step:.0025,later:[.005,.0075],max:100,base:90,split:2,previousMax:1},
 // 24, 25 and 50 purchases add 90 percentage points to the base 10%.
 {step:.005,later:[.008,.0116],max:100,base:90,split:2,previousMax:1}
];
// Convert old purchase counts once and respect each stat's current level limit.
const starterBeforeGrowthSteps=starter,migrateBeforeGrowthSteps=migrate;
starter=function(){const a=starterBeforeGrowthSteps();a.growthStepVersion=2;a.growthBatchVersion=1;return a};
migrate=function(raw){const a=migrateBeforeGrowthSteps(raw);
 a.growthBatch=raw?.growthBatchVersion===1&&GROWTH_BATCHES.includes(raw.growthBatch)?raw.growthBatch:50;
 a.growthBatchVersion=1;
 if((Number(raw?.growthStepVersion)||0)<2)a.stats=a.stats.map((level,i)=>{
  const rule=GROWTH_RULES[i];
  return Math.min(rule.max,1+(Math.min(level,rule.previousMax)-1)*rule.split);
 });
 a.growthStepVersion=2;return a};



statCost=i=>growthCostAt(i,s.stats[i]);

// Prices rise at each level; keep quotes only for complete batches.


upgrade=function(i,n,quotedCost){
 if(!Number.isInteger(i)||!GROWTH_RULES[i]||n!==undefined&&!GROWTH_BATCHES.includes(n))return;
 const p=growthPreview(i,n);
 if(!p.count){notice(p.capped?'현재 최대 효과입니다':'선택한 횟수만큼 강화할 수 없습니다');paint();return}
 if(quotedCost!==undefined&&p.cost!==quotedCost){notice('강화 비용이 바뀌었습니다. 표시된 비용을 확인하세요');paint();return}
 s.gold-=p.cost;s.stats[i]=p.level;s.daily.upgrades=(s.daily.upgrades||0)+p.count;
 paint();save();
};

growthScreen=function(){return `<div class="summary-strip">공격력 <b>${compact(power())}</b> 체력 <b>${compact(health())}</b></div><div class="stat-chips"><div><small>치명타</small><b>${(criticalChance()*100).toFixed(1)}%</b></div><div><small>공격속도</small><b>${attackSpeed().toFixed(2)}×</b></div><div><small>골드 배율</small><b>${detailedStats().goldFactor.toFixed(2)}×</b></div></div>${head('기본 능력 강화')}<div class="batch-controls">${GROWTH_BATCHES.map(n=>`<button class="${s.growthBatch===n?'active':''}" onclick="growthBatch(${n})">×${n}</button>`).join('')}</div><p class="growth-help">보유 골드로 가능한 횟수와 총비용입니다.</p>${STAT_NAMES.map((name,i)=>{const p=growthPreview(i);return `<article class="growth-row growth-comparison"><span class="growth-stat-icon">${growthStatIcon(i)}</span><div><b>${name} Lv.${s.stats[i]}</b><span class="growth-values">${growthPercent(i,p.before)} <span>→</span> <strong>${growthPercent(i,p.after)}</strong></span><small>${p.capped?'현재 최대 효과':p.count?'Lv.'+p.level+' · '+p.count+'회 강화':'다음 1회 '+growthPercent(i,growthBonus(i,s.stats[i]+1))}${i===4?' · 확률 가산':''}</small></div>${button(p.capped?'최대 효과':p.count?p.count+'회 강화<small>'+compact(p.cost)+' 골드</small>':'골드 부족<small>'+compact(statCost(i))+' 필요</small>',`upgrade(${i})`,!p.count)}</article>`}).join('')}<details class="balance-help"><summary>성장 보너스 안내</summary><p>강화 수치는 누적 성장 효과입니다. 최종 능력은 위에서 확인하세요.</p><p>전투 능력은 Lv.25부터 강화 폭이 커집니다. 골드는 회당 +1%. 공속·치명타 상한에서는 골드를 쓰지 않습니다.</p></details>`};

// IDs are save-compatible: regional 0–7, masterwork 8–12, regional 13–14.
const SET_PROFILES=[
 ['생존 · 균형',[{hp:.1},{attack:.06,penetration:.02},{hp:.3}]],
 ['치명타 사냥',[{critical:.03},{critDamage:.25},{critical:.05,hp:.1,attack:.05}]],
 ['강한 일격',[{attack:.06},{penetration:.04},{attack:.15,critDamage:.1}]],
 ['주술 · 스킬',[{skill:.1},{penetration:.04},{skill:.2,hp:.1}]],
 ['치명타 폭발',[{critDamage:.2},{critical:.04},{critDamage:.4,attack:.08}]],
 ['생명력 수호',[{hp:.15},{penetration:.03},{hp:.35}]],
 ['빠른 연격',[{speed:.06},{hp:.15},{speed:.12,attack:.04}]],
 ['군주의 강타',[{attack:.05},{critDamage:.15},{attack:.1,skill:.1,penetration:.03}]],
 ['명장 · 기동 수호',[{speed:.04},{hp:.25},{speed:.08,attack:.1}]],
 ['명장 · 치명 추격',[{critical:.02},{hp:.2},{critical:.04,critDamage:.4}]],
 ['명장 · 생명 주술',[{hp:.15},{skill:.1},{hp:.25,penetration:.05}]],
 ['명장 · 폭풍 연격',[{attack:.06},{hp:.15},{attack:.12,speed:.12}]],
 ['명장 · 극한 비술',[{skill:.1},{critical:.04},{skill:.18,critDamage:.3}]],
 ['성소의 가호',[{hp:.1},{penetration:.04},{hp:.15,critical:.04,speed:.04}]],
 ['공허의 속공',[{speed:.05},{penetration:.05},{speed:.1,skill:.12}]]
];
const GEAR_SPECIALTIES=[
 ['hp','speed'],['critical','speed'],['attack','penetration'],['skill','penetration'],['critDamage','critical'],
 ['hp','penetration'],['speed','attack'],['attack','skill'],['speed','hp'],['critical','critDamage'],
 ['hp','skill'],['attack','speed'],['skill','critDamage'],['penetration','hp'],['speed','skill']
];
const GEAR_SPECIALTY_BUDGET=[.10,.18,.27,.38,.50,.64,.79,.95,1.12,1.31,1.52];
const GEAR_SPECIALTY_RATES={attack:.018,hp:.036,speed:.012,critical:.007,critDamage:.05,skill:.022,penetration:.015};

const SET_STAT_NAMES={penetration:'방어 관통력',attack:'공격력',hp:'체력',speed:'공격속도',critical:'치명타 확률',critDamage:'치명타 피해',skill:'스킬 피해'};


setBonuses=function(){const counts=Array(REGION_SETS.length).fill(0),out={attack:0,hp:0,speed:0,critical:0,critDamage:0,skill:0,penetration:0,counts};for(let p=1;p<7;p++){const g=equippedItem(p);if(g&&Number.isInteger(g.set)&&SET_PROFILES[g.set]){counts[g.set]++;for(const [key,amount] of Object.entries(gearSpecialties(g)))out[key]+=amount}}counts.forEach((count,id)=>{for(const [k,n] of Object.entries(setEffects(id,count)))out[k]+=n});return out};



setEffectText=(count,id=0)=>setBonusText(setEffects(id,count))||'2부위부터 효과 적용';

equippedSetSummary=function(){const b=setBonuses();return `<div class="section-label"><span>착용 세트</span><button class="muted-button" onclick="openMenu('equipmentSets')">전체 세트 안내 <ui-mark data-shape=chevron-right aria-hidden=true></ui-mark></button></div><div class="equipped-set-list">${REGION_SETS.map((name,id)=>b.counts[id]?`<div><b>${name} <span>${b.counts[id]}/6</span></b><small>${SET_PROFILES[id][0]} · ${setEffectText(b.counts[id],id)}</small></div>`:'').join('')}</div>`};
equipmentSetsPopup=function(){const counts=setBonuses().counts;const card=(id,source)=>`<article class="equipment-set-card"><div class="set-card-heading">${gearArt(id>=8&&id<=12?masterworkSample(id-8,1):{p:1,r:0,set:id})}<h3>${REGION_SETS[id]}</h3><span>착용 ${counts[id]}/6</span></div><strong class="set-specialty">${SET_PROFILES[id][0]}</strong><p>${source}</p><div class="set-parts">${PARTS.map((name,p)=>p===0?'':`<span class="${equippedItem(p)?.set===id?'worn':''}">${name}</span>`).join('')}</div>${setBonusRows(id,counts[id])}<small>6부위 합계 · ${setBonusText(setEffects(id,6))}</small></article>`;return `<p class="set-rules">같은 세트의 2·4·6부위 효과는 등급과 관계없이 누적됩니다. 치명타 확률은 %p로 더하며 전체 상한을 따릅니다.</p><h3>지역 세트 · 10종</h3><p class="small">지역과 무관하게 처음부터 제작 · 세트별 10%</p>${REGIONAL_SET_IDS.map(id=>card(id,'무작위 장비 제작')).join('')}<h3>명장 세트 · 5종</h3>${MASTERWORKS.map((t,i)=>card(MASTERWORK_SET_OFFSET+i,(masterworkUnlocked(i)?'해금 · ':'미해금 · ')+stageText(t.stage)+' 클리어 · 캐릭터 Lv.'+t.level+' · 모루 Lv.'+t.forge)).join('')}`};
EXTRA_POPUPS.equipmentSets=['장비 세트 안내',equipmentSetsPopup];





gearPopup=function(){
 const g=s.gear.find(x=>x.id===tab);if(!g)return '<div class="empty-state">소모된 장비입니다.</div>';
 if(g.p===0)return legacyWeaponDetail(g);
 const worn=s.equipped[g.p]===g.id,old=equippedItem(g.p),current=gearStat(g),oldStat=old?gearStat(old):{...current,value:0},level=gearEnhancement(g),next=gearStat(g,Math.min(15,level+1)),c=upgradeCost(g),can=level<15&&s.gold>=c.gold&&s.stones>=c.stones,preview=equipmentStatsPreview(g),count=setBonuses().counts[g.set],nextCount=count+(worn||old?.set===g.set?0:1),t=masterworkDef(g);
 const inSlot=!popupStack.some(page=>['inventory','loot'].includes(page.view))&&worn;
 return (inSlot?gearMaterialHUD(g.p):'')+`<section class="gear-detail-compact"><header class="gear-detail-hero"><div class="gear-detail-picture">${gearArt(g)}</div><div><small class="rar${g.r}">${RAR[g.r]} · ${PARTS[g.p]} · ${worn?'착용 중':'보관 중'}</small><h3>${equipmentTitle(g)} ${inSlot?`<span>+${level}</span>`:''}</h3>${SET_PROFILES[g.set]?`<p class="gear-set-name">${setEmblem(g.set)}${REGION_SETS[g.set]} · ${SET_PROFILES[g.set][0]}</p>`:''}${t?'<small>명장 제작 · 기본 효과 +5%</small>':''}</div></header><div class="gear-help-links">${inSlot?termButton('슬롯 강화','슬롯 강화'):''}${termButton('방어 관통력','방어 관통력')}${termButton('진열장 등록','진열장 등록')}</div><div class="gear-main-stat"><span>${current.label}</span><strong>+${gearStatNumber(current)}</strong><small>${setBonusText(gearSpecialties(g))}</small>${g.p===5&&current.value>=200?'<small>공격속도 합산 상한 +200% · 적용 수치는 착용 능력에서 확인</small>':''}${worn?'':`<small>현재 착용 ${gearStatNumber(oldStat)} → 선택 장비 ${gearStatNumber(current)} <b class="${current.value>=oldStat.value?'positive':'negative'}">(${signedNumber(current.value-oldStat.value,current.digits)}${current.unit})</b></small>`}${inSlot?`<small>다음 슬롯 강화 ${level>=15?'최대 +15':'+ '+gearStatNumber(next)}</small>`:''}</div>${inSlot?`<div class="gear-cost-line">${level>=15?'슬롯 최대 강화':`강화 비용 <b>${num(c.gold)} 골드 · ${num(c.stones)} 강화석</b>`}<small>보유 ${compact(s.gold)} 골드 · ${num(s.stones)} 강화석</small></div><div class="action-row">${button('슬롯 강화',`improveGearSlot(${g.p})`,!can)}${button('슬롯 최대 강화',`improveGearSlot(${g.p},true)`,!can,true)}</div>`:''}<div class="action-row">${button(worn?'착용 중':'이 장비 장착',`equip('${g.id}')`,worn)}<button class="gear-lock-switch" role="switch" aria-checked="${!!g.locked}" aria-label="장비 잠금" onclick="toggleGearLock('${g.id}')"><span>장비 잠금</span>${switchFace(!!g.locked)}</button></div><details class="gear-compare gear-set-details"><summary>${worn?'현재 착용 능력':'교체 시 최종 능력'}</summary>${[['attack','공격력',0,''],['health','체력',0,''],['speed','공격속도',2,'×'],['critical','치명타',2,'%'],['penetration','방어 관통력',2,'%'],['critDamage','치명타 피해',2,'%'],['skill','장비 스킬 피해',2,'%']].map(([key,label,digits,unit])=>{const mul=['critical','penetration','critDamage','skill'].includes(key)?100:1,a=preview.before[key]*mul,b=preview.after[key]*mul;if(worn)return `<div><span>${label}</span><b>${digits?b.toFixed(digits):num(b)}${unit}</b></div>`;return `<div><span>${label}</span><span>${digits?a.toFixed(digits):num(a)} → <b>${digits?b.toFixed(digits):num(b)}${unit}</b></span><em class="${b>=a?'positive':'negative'}">${signedNumber(b-a,digits)}${key==='critical'?'%p':unit}</em></div>`}).join('')}</details>${SET_PROFILES[g.set]?`<details class="gear-set-details"><summary>${REGION_SETS[g.set]} · ${count}/6${worn?'':' → '+nextCount+'/6'} 부위</summary>${setBonusRows(g.set,nextCount)}<p class="small">${worn?'현재 적용':'교체 후 예상'} · ${setEffectText(nextCount,g.set)}</p>${!worn&&old&&SET_PROFILES[old.set]&&old.set!==g.set?`<p class="small">${REGION_SETS[old.set]}은 ${Math.max(0,(setBonuses().counts[old?.set]||0)-1)}부위로 변경됩니다.</p>`:''}</details>`:''}<div class="gear-secondary-actions"><button type="button" class="muted-button" onclick="salvage('${g.id}');closeMenu()" ${worn||g.locked?'disabled':''}>분해</button><button type="button" class="gold-button purple" onclick="openMenu('showcaseConfirm','${g.id}')" ${!canShowcaseGear(g)?'disabled':''}>진열장 등록</button></div></section>`;
};

