// game script 25
onlineDay = function onlineDay(){return new Date().toISOString().slice(0,10)};
onlineDaily = function onlineDaily(){return {orderVersion:2,arena:0,raid:0,donated:false,mission:false,shop:false,shopPurchases:{},raidClaimed:[],raidDamage:0,bossMax:0,arenaBase:null}};
onlineState = function onlineState(){
 let o=s.onlineTest;
 if(!o||o.version!==1)o=s.onlineTest={version:1,day:onlineDay(),guild:'',guildCoins:0,contribution:0,rating:1000,wins:0,losses:0,daily:onlineDaily(),lastResult:null};
 const raw=recordMap(o.daily),d=o.daily={...onlineDaily(),...raw};
 if(raw.orderVersion!==2){d.legacyGuildReady=[raw.donated===true,raw.arena>=1,raw.raid>=1,raw.skill>=12,raw.dungeon>=1].filter(Boolean).length>=3;d.orderVersion=2}
 for(const key of ['arena','raid'])d[key]=Math.floor(bounded(raw[key],0,ONLINE_LIMITS[key]));
 for(const key of ['donated','mission','shop'])d[key]=raw[key]===true;
 d.raidClaimed=Array.isArray(raw.raidClaimed)?[...new Set(raw.raidClaimed.filter(n=>[1,2,3].includes(n)))]:[];
 d.bossMax=bounded(raw.bossMax);d.raidDamage=bounded(raw.raidDamage);
 if(raw.legacyBossCleared===undefined)d.legacyBossCleared=d.bossMax>0&&d.raidDamage>=d.bossMax;
 o.raidLastCleared=Math.floor(bounded(o.raidLastCleared,0,100));
 if(!d.arenaBase||!['attack','hp','speed','crit','critDamage'].every(k=>Number.isFinite(d.arenaBase[k]))||d.arenaBase.hp<=0||d.arenaBase.attack<=0)d.arenaBase=null;
 for(const key of ['contribution','rating','wins','losses'])o[key]=Math.floor(bounded(o[key]??(key==='rating'?1000:0)));
 o.guild=typeof o.guild==='string'?o.guild:'';
 if(o.lastResult&&(!Array.isArray(o.lastResult.rounds)||!['arena','raid'].includes(o.lastResult.kind)))o.lastResult=null;
 if(o.lastResult?.kind==='raid')o.lastRaidResult=o.lastResult;
 o.raidBest=Math.max(bounded(o.raidBest),bounded(o.lastRaidResult?.damage));
 normalizeHavenCoins(o);
 const recovered=worldBoss.settleOutstanding(o);
 const today=onlineDay();
 if(o.day!==today){o.day=today;o.daily=onlineDaily();normalizeHavenCoins(o)}
 if(recovered)save();
 return o;
};
onlineFighter = function onlineFighter(){return {attack:power(),hp:health(),armor:armor(),speed:attackSpeed(),crit:criticalChance(),critDamage:criticalDamageMultiplier(),penetration:armorPenetration()}};
onlineArenaOpponents = function onlineArenaOpponents(){return communityRecords.arena()};
simulateArena = function simulateArena(player,enemy){
 let a=player.hp,b=enemy.hp;const rounds=[];
 const reduction=unit=>armorMitigation(unit.armor??Math.floor(unit.hp*.04));
 const damageRatio=(attacker,defender)=>1-reduction(defender)*(1-Math.max(0,Math.min(1,attacker.penetration||0)));
 for(let i=0;i<24&&a>0&&b>0;i++){
  const hit=Math.round(player.attack*player.speed*damageRatio(player,enemy)*(i%4===3?2.2:1)*(Math.random()<player.crit?player.critDamage:1));
  b=Math.max(0,b-hit);
  const counter=b>0?Math.round(enemy.attack*enemy.speed*damageRatio(enemy,player)*(i%4===3?2.2:1)*(Math.random()<enemy.crit?enemy.critDamage:1)):0;
  a=Math.max(0,a-counter);rounds.push({player:a,enemy:b,hit,counter});
 }
 return {won:b===0||(a>0&&a/player.hp>b/enemy.hp),rounds};
};
onlinePay = function onlinePay(rewards){for(const[k,n]of Object.entries(rewards))s[k]=(s[k]||0)+n};
onlineAct = function onlineAct(type,payload={}){
 const result=OnlineService.command(type,payload);
 if(!result.ok){notice(result.message);return false}
 paint();
 if(type==='arena'||type==='raid')openMenu('onlineResult');
 const spent=['donate','shop','townExchange'].includes(type);
 if(Object.keys(result.rewards).length){
  if(!spent)rewardNotice(result.rewards,result.message);
  playSound('reward');
 }else if(!spent)notice(result.message);
 return true;
};
