onlineResultPopup = function onlineResultPopup(){
 const r=OnlineService.snapshot().lastResult;if(!r)return '<p>아직 전투 기록이 없습니다.</p>';
 return `<section class="online-play"><header class="online-result-header"><h3>${r.kind==='arena'?(r.won?'승리':'패배'):'도전 완료'}</h3><p>${safeText(r.name)} · ${r.rounds.length}턴</p>${r.kind==='raid'?'<strong>누적 피해 +'+num(r.damage)+'</strong>':'<strong>보상 지급 완료</strong>'}</header>${rewardsHTML(r.rewards)}${havenCoinRewards(r.coinRewards)}<div class="online-battle-log">${r.rounds.map((x,i)=>`<div style="--turn:${Math.min(i,12)}"><small>${i+1}턴</small><span>${i%4===3?'강화 공격':'공격'} <b>${num(x.hit)}</b>${r.kind==='arena'?'<br><small>내 체력 '+num(x.player)+' · 상대 '+num(x.enemy)+'</small>':''}</span></div>`).join('')}</div><button class="gold-button profile-wide" onclick="closeMenu()">돌아가기</button></section>`;
};
/* Playable local service adapter. No fabricated live users or shared server state.
 * Replace OnlineService with an authenticated server adapter for release;
 * command validation, day limits and wallet settlement must then run server-side. */
'use strict';
let onlineGuildDraft='';
const ONLINE_LIMITS={arena:5,raid:3};
const TRAINING_OPPONENTS=[
 {id:'rookie',name:'수련 기사',factor:.72,art:'portrait'},
 {id:'veteran',name:'숙련 기사',factor:1,art:'arenaHall'},
 {id:'champion',name:'정예 기사',factor:1.3,art:'guildHall'}
];







const ONLINE_FEATURES={join:'guild',leave:'guild',donate:'guild',mission:'guild',guildNotice:'guild',shop:'havenShop',townExchange:'havenShop',arena:'arena'};
const LocalOnlineService={
 snapshot(){return onlineState()},
 command(type,payload={}){
  const fail=message=>({ok:false,message});
  const feature=type==='raid'&&payload.sweep?'worldBoss':ONLINE_FEATURES[type];
  if(feature&&!featureOpen(feature))return fail(featureLockText(feature));
  const o=onlineState(),d=o.daily;
  if(o.guild)guildProfile(o);
  if(dungeonRun||forgeBusy)return fail('현재 도전·제작이 끝난 뒤 이용하세요');
  let message='',rewards={};
  switch(type){
   case 'join': {
    if(o.guild)return fail('이미 길드에 가입되어 있습니다');
    const name=payload.name==='starlight'?'별빛 기사단':validNickname(payload.name||'');
    if(!name)return fail('길드 이름은 1~12자로 입력하세요');
    o.guild=name;o.guildProfile=newGuildProfile(name,payload.name==='starlight'?'member':'leader');guildSection='overview';guildLog(o,payload.name==='starlight'?'길드에 가입했습니다':'길드를 창설했습니다');message=name+' 가입 완료';break;
   }
   case 'leave':
    if(!o.guild)return fail('가입한 길드가 없습니다');
    o.guild='';o.guildProfile=null;guildSection='overview';message='길드에서 나왔습니다';break;
   case 'donate':
    if(!o.guild||d.donated)return fail('길드 기부는 하루 한 번 가능합니다');
    if(s.gold<500)return fail('500 골드가 필요합니다');
    s.gold-=500;d.donated=true;o.guildCoins+=20;o.contribution+=20;guildContribution(o,20,'500 골드 기부 · 기여도 +20');message='기여도 +20 · 길드 코인 +20';break;
   case 'mission':
    if(!o.guild||d.mission||guildOrdersDone(o)<3)return fail('오늘의 길드 임무를 먼저 완료하세요');
    d.mission=true;o.guildCoins+=20;o.contribution+=20;guildContribution(o,20,'일일 임무 완료 · 기여도 +20');rewards={ore:20,stones:20};message='길드 임무 완료 · 길드 코인 +20';break;
   case 'guildNotice': {
    if(!o.guild||guildProfile(o).role!=='leader')return fail('길드장만 공지를 수정할 수 있습니다');
    const value=String(payload.text||'').trim();
    if(!value||value.length>120)return fail('공지는 1~120자로 입력하세요');
    guildProfile(o).notice=value;guildLog(o,'길드 공지를 수정했습니다');message='길드 공지 저장 완료';break;
   }
   case 'shop':return this.command('townExchange',{id:'guild-ore'});
   case 'townExchange': {
    if(!saveGuard.canTransact(true))return fail(TRANSACTION_OFFLINE_MESSAGE);
    const item=TOWN_SHOP_ITEMS.find(i=>i.id===payload.id);
    if(!item)return fail('교환 상품을 확인하세요');
    const currency=HAVEN_COINS[item.kind];
    if(d.shopPurchases[item.id]>=item.limit)return fail('오늘 교환 횟수를 모두 사용했습니다');
    if(o[currency.key]<item.cost)return fail(currency.name+'이 부족합니다');
    o[currency.key]-=item.cost;d.shopPurchases[item.id]++;
    if(item.id==='guild-ore')d.shop=true;
    recordWheelGoal('haven');
    rewards={...item.reward};message=item.name+' 교환 완료';break;
   }
   case 'arena': {
    if(!entryAvailability('arena',d).can)return fail('아레나 입장권이 부족합니다');
    const opponent=onlineArenaOpponents(o).find(x=>x.id===payload.id);
    if(!opponent)return fail('등록된 상대를 선택하세요');
    const fighter=onlineFighter(),official=payload.server;
    if(communityRecords.available()&&(!official||official.name!==opponent.name||!official.id||o.lastArenaId===official.id))return fail('대결 기록을 다시 확인해 주세요.');
    const result=official||simulateArena(fighter,opponent);
    if(!spendEntry('arena',d))return fail('아레나 입장권이 부족합니다');if(official)o.lastArenaId=official.id;o.rating=Math.max(0,o.rating+(result.won?20:-10));o[result.won?'wins':'losses']++;
    rewards=result.won?{gold:1000,stones:10}:{gold:100};
    const coins=result.won?20:10;o.arenaCoins+=coins;
    o.lastResult={kind:'arena',name:opponent.name,won:result.won,rounds:result.rounds,playerMax:official?.playerMax||fighter.hp,enemyMax:official?.enemyMax||opponent.hp,rewards,coinRewards:{arena:coins},at:Date.now()};
    message=(result.won?'아레나 승리 · 점수 +20':'아레나 패배 · 점수 -10')+' · 아레나 코인 +'+coins;break;
   }
   case 'raid': {
    const result=worldBoss.settle(o,payload);
    if(!result.ok)return result;
    message=result.message;rewards=result.rewards;break;
   }
   default:return fail('알 수 없는 동작입니다');
  }
  if(type==='raid'&&saveGuard.usesServer())worldBoss.payWorldReceipt(o,d.raid,d.raidLoot[d.raid],rewards);
  else onlinePay(rewards);
  if(type==='townExchange')saveTransaction();else save();
  return {ok:true,message,rewards};
 }
};
