// game script 26
newGuildProfile = function newGuildProfile(name,role){return {name,role,xp:0,notice:'오늘의 길드 임무는 3개를 골라 달성하세요.',logs:[]}};
guildProfile = function guildProfile(o){
 if(!o.guild)return null;
 if(!o.guildProfile||o.guildProfile.name!==o.guild){o.guildProfile=newGuildProfile(o.guild,o.guild==='별빛 기사단'?'member':'leader');o.guildProfile.xp=Math.max(0,o.contribution||0)}
 const g=o.guildProfile;
 g.xp=Math.floor(bounded(g.xp));
 if(!['member','leader'].includes(g.role))g.role=o.guild==='별빛 기사단'?'member':'leader';
 g.notice=typeof g.notice==='string'?g.notice.slice(0,120):newGuildProfile(o.guild,g.role).notice;
 g.logs=Array.isArray(g.logs)?g.logs.filter(l=>l&&typeof l.text==='string'&&typeof l.name==='string'&&Number.isFinite(l.at)).slice(0,20):[];
 return g;
};
guildLog = function guildLog(o,text){const g=guildProfile(o);if(!g)return;g.logs.unshift({text,name:s.nickname||'성운기사',at:Date.now()});g.logs=g.logs.slice(0,20)};
guildContribution = function guildContribution(o,n,text){const g=guildProfile(o);g.xp+=n;g.weeklyActivity=guildWeekActivity(g)+n;g.activityWeek=weekKey();guildLog(o,text)};
guildGrowth = function guildGrowth(xp){let level=1,progress=xp;while(level<20&&progress>=level*200){progress-=level*200;level++}return {level,progress:level===20?0:progress,need:level===20?0:level*200}};
guildMembers = function guildMembers(o=OnlineService.snapshot()){
 if(!o.guild)return [];
 return communityRecords.roster(o.guild).map(m=>({...m,id:m.mine?'self':'member-'+encodeURIComponent(m.name).replace(/'/g,'%27'),self:!!m.mine,profession:m.job,rank:Number(m.outfit)||0}));
};
guildAvatar = function guildAvatar(m){return `<span class="guild-avatar">${m.self?wornCostumeSprite():CLASSES.some(c=>c.id===m.profession)?classSprite(m.profession,m.rank,'',false):art('guildHall')}</span>`};
guildMemberPopup = function guildMemberPopup(){
 const m=guildMembers().find(row=>row.id===tab);
 if(!m)return '<p>길드원 정보를 확인할 수 없습니다.</p>';
 const c=CLASSES.find(x=>x.id===m.profession);
 return `<section class="guild-member-detail"><div class="guild-detail-stage">${guildAvatar(m)}</div><span class="guild-role">${GUILD_ROLES[m.role]}</span><h3>${safeText(m.name)}${m.self?' · 나':''}</h3><p>${m.level?'Lv.'+num(m.level):''} ${c?.name||''}</p><dl><div><dt>인증 전투력</dt><dd>${m.power?ratingText(m.power):'집계 중'}</dd></div></dl><button class="gold-button purple profile-wide" onclick="closeMenu()">돌아가기</button></section>`
};
openGuildNotice = function openGuildNotice(){if(guildProfile(OnlineService.snapshot())?.role!=='leader')return;guildNoticeDraft=communityRecords.guildNotice(OnlineService.snapshot().guild);if(guildNoticeDraft==='등록된 공지가 없습니다.')guildNoticeDraft='';openMenu('guildNotice')};
guildNoticePopup = function guildNoticePopup(){if(guildProfile(OnlineService.snapshot())?.role!=='leader')return '<p>길드장만 공지를 수정할 수 있습니다.</p>';return `<div class="guild-notice-editor"><label for="guildNoticeText">기사단에 전할 한마디</label><textarea id="guildNoticeText" data-live-input="true" maxlength="120" oninput="guildNoticeDraft=this.value" rows="4">${safeText(guildNoticeDraft??guildProfile(OnlineService.snapshot()).notice)}</textarea><p class="online-note">길드원에게 공개됩니다.</p><button class="gold-button profile-wide" onclick="saveGuildNotice()">공지 저장</button></div>`};
saveGuildNotice = async function saveGuildNotice(){
 if(!guardFeature('guild'))return false;
 if(guildProfile(OnlineService.snapshot())?.role!=='leader'||!communityRecords.available())return;
 try{await communityRecords.editGuildNotice($('guildNoticeText').value);guildNoticeDraft=null;closeMenu();paint();notice('길드 공지를 저장했습니다.')}
 catch(error){notice(error.message||'공지 저장 실패')}
};
guildLeavePopup = function guildLeavePopup(){return `<div class="guild-leave"><h3>${safeText(OnlineService.snapshot().guild)}</h3><p>현재 길드를 탈퇴할까요?</p><p class="online-note">코인·기여도·오늘의 보상 기록은 유지됩니다. 이 길드의 공지·성장 기록은 종료됩니다.</p><div class="action-row"><button class="gold-button purple" onclick="closeMenu()">돌아가기</button><button class="muted-button" onclick="leaveCurrentGuild()">탈퇴하기</button></div></div>`};
leaveCurrentGuild = function leaveCurrentGuild(){if(!testSession&&typeof fetch==='function')return changeChatGuild('leave',onlineState().guild);const r=OnlineService.command('leave');if(!r.ok){notice(r.message);return false}closeMenu();paint();notice(r.message);return true};
