// ./weapon-audio.js

'use strict';
const weaponAudio=(()=>{
 // This is the material under the weapon. The foreground recording is unique to the performed skill.
 const accents = {
  sword:{steel:'swordSteel',wood:'swordWood',body:'cut',hard:'stoneCut'},
  knife:{steel:'knifeSteel',wood:'knifeWood',body:'stab',hard:'stonePoint'},
  mace:{steel:'maceSteel',wood:'maceWood',body:'thump',hard:'stoneBlow'},
  lance:{steel:'lanceSteel',wood:'wood',body:'stab',hard:'stonePoint'},
  arrow:{steel:'arrowHard',wood:'arrowWood',body:'arrowSoft',hard:'stonePoint'}
 };
 // Self buffs, terrain, and area spells have their own landings; no enemy contact is mixed into them.
 const contacts={
  0:'sword',1:'sword',20:'sword',22:'sword',40:'sword',42:'sword',43:'sword',
  24:'knife',25:'knife',26:'knife',44:'knife',45:'knife',46:'knife',47:'knife',
  28:'mace',31:'mace',48:'lance',50:'mace',51:'lance',
  36:'arrow',37:'arrow',39:'arrow',56:'arrow',57:'arrow',59:'arrow'
 };
 const creatures=[
  ['body','hard','body','hard'], ['body','body','wood','wood'], ['hard','body','body','hard'],
  ['body','body','body','body'], ['body','body','hard','hard'], ['body','hard','hard','body'],
  ['hard','hard','steel','steel'], ['steel','steel','body','steel'], ['body','steel','steel','body'],
  ['hard','hard','body','hard']
 ];
 function surface(region,species){return creatures[region]?.[species]||'body'}
 function recipe(id){return skillPerformances[id]}
 function layers(id,phase,options,sequence){
  const performance=recipe(id);
  if(!performance)return [];
  const take=sequence%2;
  if(phase==='cast'){
   const parts=[{clip:performance.cast[take],gain:1,delay:0}];
   if(performance.release){
    const scale=Math.max(.4,Math.min(1.4,options.motionScale||1));
    const releaseMs=rangedCombat.releaseTime(CLASSES[skillOwnerIndex(id)].id,id);
    const hits=id===19||id===57?1:options.hitCount||1;
    for(let n=0;n<hits;n++)parts.push({clip:performance.release[(take+n)%2],gain:n===0?1:.80,delay:(releaseMs+n*70)*scale/1000});
   }
   return parts;
  }
  const ordinal=options.ordinal??Number(!!options.echo);
  const impact=[performance.hit,performance.follow,performance.finish][ordinal]||performance.hit;
  const parts=[{clip:impact[take],gain:1,delay:0}];
  const instrument=accents[contacts[id]];
  // The first two cuts are close together. Let the final blow carry the full material resonance.
  if(instrument&&(id!==1||ordinal===2)){
   const surface=options.surface||'body';
   const job=CLASSES[skillOwnerIndex(id)].id;
   const variations=contactSamples[job][instrument[surface]||instrument.body];
   parts.push({clip:variations[(sequence+(options.ordinal||0))%variations.length],gain:surface==='body' ? .18 : .32,delay:0});
  }
  return parts;
 }
 return {layers,recipe,surface};
})();

