// game script 31
normalAttackSound = function normalAttackSound(classId=s.classId){return NORMAL_ATTACK_SOUNDS[classId]||NORMAL_ATTACK_SOUNDS.warrior};
soundVolume = function soundVolume(){return (Number.isFinite(s.soundVolume)?Math.max(0,Math.min(100,s.soundVolume)):55)/100};
stopSoundEffects = function stopSoundEffects(){
 for(const v of sfx.voices){try{v.source.stop();v.source.disconnect();v.gain.disconnect()}catch(e){}if(v.timer)clearTimeout(v.timer)}
 sfx.voices=[];sfx.last.clear();
};
warmSoundEffects = function warmSoundEffects(job=s?.classId){
 if(!s?.sound||!soundContext||document.hidden)return;
 const ctx=soundContext;enemySound.warm();
 for(const bank of [sfx,actionBanks[job]]){
  if(!bank||bank.buffer||bank.pending||Date.now()<bank.retryAt)continue;
  bank.pending=fetch(bank.url).then(r=>{if(!r.ok)throw Error('SFX unavailable');return r.arrayBuffer()})
   .then(bytes=>new Promise((resolve,reject)=>ctx.decodeAudioData(bytes,resolve,reject)))
   .then(buffer=>{bank.buffer=buffer;bank.retryAt=0})
   .catch(()=>{bank.retryAt=Date.now()+15000}).finally(()=>{bank.pending=null});
 }
};
chooseSound = function chooseSound(type,options={}){
 const alternating=++sfx.counter%2+1;
 const skill=Number.isInteger(options.skillId)&&options.skillId>=0&&options.skillId<CLASS_SKILLS.length;
 if(skill&&weaponAudio.recipe(options.skillId)){
  if(type==='swing')return 'cast'+options.skillId;
  if(type==='impact')return 'hit'+options.skillId;
 }
 // Other original recordings already contain their full attack.
 if(skill&&type==='impact')return options.echo?null:'skill'+options.skillId;
 if(skill&&type==='swing')return null;
 // Normal attacks have their own class cue, including critical hits. Do not
 // double it with the legacy sword/arrow windup or generic critical-hit sound.
 if(options.skillId===-1&&(type==='swing'||type==='impact'))return type==='impact'&&!options.echo?normalAttackSound(options.classId||s.classId):null;
 if(type==='swing')return options.effect==='arrow'||['volley','rain','pierce'].includes(options.effect)?'arrow':['fire','ice','lightning','meteor','heal','holy','shield','judgment'].includes(options.effect)?null:'swing'+alternating;
 if(type==='impact'){
  const effect=options.effect||'cleave';
  if(['arrow','volley','pierce','rain'].includes(effect))return 'pierce';
  if(['fire','meteor'].includes(effect))return 'fire';
  if(effect==='ice')return 'ice';
  if(['lightning','storm'].includes(effect))return 'lightning';
  if(['holy','shield','judgment'].includes(effect))return 'holy';
  if(effect==='heal')return 'heal';
  if(effect==='quake'||options.crit)return 'heavy';
  return 'blade'+alternating;
 }
 if(type==='hit')return normalAttackSound(options.classId||s.classId);
 if(type==='skill')return 'fire';
 return Object.hasOwn(SFX_CUES,type)?type:null;
};
combatSoundGain = function combatSoundGain(id){if(id==='skill2')return .5625;if(id==='forge')return 1.35;if(id==='reward')return 1.5;if(id==='click')return .6;return /^(skill\d+|attack[A-Z]\w*)$/.test(id)||['arrow','pierce','swing1','swing2','blade1','blade2','heavy','fire','ice','lightning','holy','heal'].includes(id) ? .8 : 1};
soundBus = function soundBus(){
 if(sfx.context!==soundContext){stopSoundEffects();sfx.bus?.disconnect();sfx.context=soundContext;sfx.bus=soundContext.createGain();sfx.bus.connect(soundContext.destination)}
 return sfx.bus;
};
applySoundVolume = function applySoundVolume(){if(sfx.bus&&soundContext){sfx.bus.gain.cancelScheduledValues(soundContext.currentTime);sfx.bus.gain.setTargetAtTime(soundVolume()*.65,soundContext.currentTime,.025)}};
playSoundClip = function playSoundClip(buffer,clip,when,volume,rate,bus){
 const source=soundContext.createBufferSource(),gain=soundContext.createGain();
 source.buffer=buffer;source.playbackRate.value=rate;gain.gain.value=volume;
 source.connect(gain);gain.connect(bus);
 const voice={source,gain,timer:0};
 const release=()=>{const i=sfx.voices.indexOf(voice);if(i>=0)sfx.voices.splice(i,1);try{source.disconnect();gain.disconnect()}catch(e){}clearTimeout(voice.timer)};
 source.onended=release;
 sfx.voices.push(voice);source.start(when,clip[0],clip[1]);
 voice.timer=setTimeout(release,(when-soundContext.currentTime+clip[1]/rate+.15)*1000);
};
setSoundVolume = function setSoundVolume(value,commit=false){const n=Number(value);if(!Number.isFinite(n))return;s.soundVolume=Math.max(0,Math.min(100,Math.round(n)));applySoundVolume();const label=document.getElementById('soundVolumeValue');if(label)label.textContent=s.soundVolume+'%';if(commit)save()};
previewSound = function previewSound(id){
 if(!TEST_TOOLS_ENABLED)return;
 wakeAudio();
 if(!s.sound){notice('효과음을 먼저 켜 주세요');return}
 const skill=/^skill(\d+)$/.exec(id),k=skill?Number(skill[1]):-1;
 const job=weaponAudio.recipe(k)?CLASSES[skillOwnerIndex(k)].id:null;
 if(!(job?actionBanks[job]:sfx).buffer){warmSoundEffects(job||s.classId);notice('효과음을 불러오는 중입니다. 잠시 후 눌러 주세요');return}
 if(job){
  playSound('swing',{skillId:k,big:true,hitCount:SKILL_RULES[k].hits});
  for(let i=0;i<SKILL_RULES[k].hits;i++)playSound('impact',{skillId:k,big:true,echo:i>0,ordinal:i,delay:.27+i*.07});
 }else playSound(id,{big:!!skill});
};
soundSettings = function soundSettings(){return `<section class="music-settings sound-settings" aria-label="효과음 설정"><div class="music-volume-label"><label for="soundVolume">효과음 볼륨</label><output id="soundVolumeValue" for="soundVolume">${Math.round(soundVolume()*100)}%</output></div><input id="soundVolume" data-music-control="true" type="range" min="0" max="100" step="5" value="${Math.round(soundVolume()*100)}" oninput="setSoundVolume(this.value)" onchange="setSoundVolume(this.value,true)"></section>`};
soundPreviewTools = function soundPreviewTools(){return `<section class="music-settings sound-settings"><div class="sound-preview" style="grid-template-columns:repeat(3,minmax(0,1fr))">${[[normalAttackSound(),'일반 공격'],['forge','모루'],['reward','보상']].map(([id,label])=>`<button class="gold-button purple" onclick="previewSound('${id}')">${label}</button>`).join('')}</div>${s.classId?`<p>${currentClass().name} · 스킬 소리 미리듣기</p><div class="sound-preview skill-sound-preview">${classSkillIds().map(k=>`<button class="gold-button purple" onclick="previewSound('skill${k}')">${SK[k][0]}</button>`).join('')}</div>`:''}<small class="sound-mix-note">스킬을 눌러 효과음을 들어보세요.</small></section>`};
/* Recorded weapon hits and distinct skill cues. No oscillator fallback. */
