playSound=function(type,options={}){
 if(!s?.sound||document.hidden||!soundContext||soundContext.state!=='running')return false;
 const id=chooseSound(type,options);if(!id)return false;
 const k=options.skillId,phased=!!weaponAudio.recipe(k)&&(type==='swing'||type==='impact');
 const job=phased?CLASSES[skillOwnerIndex(k)].id:s.classId,bank=phased?actionBanks[job]:sfx;
 if(!bank.buffer){warmSoundEffects(job);return false}
 const group=phased||/^skill\d+$/.test(id)?id:type==='swing'?'swing':type==='impact'?'impact':id;
 const bus=soundBus(),now=Date.now();
 if(!(phased&&options.echo)&&now-(sfx.last.get(group)??-Infinity)<(group==='impact'?95:70))return false;
 sfx.last.set(group,now);
 const at=soundContext.currentTime+Math.max(0,Math.min(.65,options.delay||0));
 bus.gain.setValueAtTime(soundVolume()*.65,soundContext.currentTime);
 // Keep all components of one strike together, including the second impact at double game speed.
 if(phased&&type==='swing')skillTakes.set(k,((skillTakes.get(k)||0)+1)>>>0);
 const layers=phased?weaponAudio.layers(k,type==='swing'?'cast':'hit',options,skillTakes.get(k)||0):null;
 const count=layers?layers.length:1;
 while(sfx.voices.length+count>24){const old=sfx.voices.shift();try{old.source.stop();old.source.disconnect();old.gain.disconnect()}catch(e){}clearTimeout(old.timer)}
 if(phased){
  for(const layer of layers)playSoundClip(bank.buffer,layer.clip,at+layer.delay,layer.gain*.76,1,bus);
 }else{
  const cue=SFX_CUES[id];if(!cue)return false;
  const rate=/^(skill\d+|attack[A-Z]\w*)$/.test(id)?1:['impact','swing','hit'].includes(type)?[.98,1,1.02][sfx.counter%3]:1;
  playSoundClip(bank.buffer,[cue.start,cue.duration],at,(options.big ? .95 : .82)*combatSoundGain(id),rate,bus);
 }
 return true;
};




