normalizeHavenCoins = function normalizeHavenCoins(o){
 for(const {key} of Object.values(HAVEN_COINS))o[key]=Number.isSafeInteger(o[key])&&o[key]>=0?o[key]:0;
 if(!o.daily.shopPurchases||typeof o.daily.shopPurchases!=='object'||Array.isArray(o.daily.shopPurchases))o.daily.shopPurchases={};
 // Old pass counts combined both shops and did not identify the payment currency.
 const splitPassLimits=!Object.hasOwn(o.daily,'diamondPassPurchases');
 const diamondPassPurchases=o.daily.diamondPassPurchases=recordMap(o.daily.diamondPassPurchases);
 for(const item of TOWN_SHOP_ITEMS){
  if(item.id.startsWith('pass-')){
   if(splitPassLimits)o.daily.shopPurchases[item.id]=0;
   diamondPassPurchases[item.id]=Math.min(item.limit,entryCount(diamondPassPurchases[item.id]));
  }
  const n=o.daily.shopPurchases[item.id];
  o.daily.shopPurchases[item.id]=Number.isSafeInteger(n)&&n>=0?Math.min(item.limit,n):0;
 }
 if(o.daily.shop)o.daily.shopPurchases['guild-ore']=1;
 return o;
};
