havenCoinRewards = function havenCoinRewards(rewards={}){return `<div class="haven-coin-rewards">${Object.entries(rewards).filter(([k,n])=>HAVEN_COINS[k]&&n>0).map(([k,n])=>`<span>${havenCoin(k)}${HAVEN_COINS[k].name} <b>+${num(n)}</b></span>`).join('')}</div>`};
