const SKIN_MAX_LEVEL=5;
// Common drops need more duplicates at higher stars. The rarest and limited
// skins use one matching copy per promotion because of their draw rates.
const SKIN_COPIES_BY_TIER=[[],[1,2,3,4],[1,2,3,4],[1,1,2,2],[1,1,1,1],[1,1,1,1]];










const migrateBeforeSkinLevels=migrate;
migrate=function(raw){
 const a=migrateBeforeSkinLevels(raw),levels=recordMap(raw?.skinUpgrades),copies=recordMap(raw?.skinCopies);
 const eligible=a.costumes.filter(key=>key%OUTFIT_STRIDE!==0).map(key=>({key,tier:key%OUTFIT_STRIDE}));
 for(const job of CLASSES)for(const season of Object.keys(EVENT_EFFECTS)){
  if(eventSkinOwned(a,job.id,season))eligible.push({event:true,job:job.id,season});
 }
 a.skinUpgrades={};a.skinCopies={};
 for(const row of eligible){
  const id=skinRowId(row),level=Number.isInteger(levels[id])?Math.max(1,Math.min(SKIN_MAX_LEVEL,levels[id])):1;
  if(level>1)a.skinUpgrades[id]=level;
  if(Number.isSafeInteger(copies[id])&&copies[id]>0){
   const kept=Math.min(copiesToFinish(row,level),copies[id]);
   if(kept)a.skinCopies[id]=kept;
  }
 }
 return a;
};



