playerCombatStats = function playerCombatStats(){const attack=power(),hp=health(),speed=attackSpeed(),crit=criticalChance();return {attack,hp,speed,crit,critDamage:100*criticalDamageBonus(),penetration:100*armorPenetration(),dps:attack*adventureBasicMultiplier()*weaponModifier('storm')*(1+crit*(criticalDamageMultiplier()-1))*speed/1.15,gold:detailedStats().goldFactor}};
growthCombatPreview = function growthCombatPreview(i,count,offers){const p=growthPreview(i,count,offers),before=playerCombatStats(),level=s.stats[i];let after;try{s.stats[i]=p.level;after=playerCombatStats()}finally{s.stats[i]=level}return {p,before,after}};
playerMetric = function playerMetric(value,digits=0){return digits?value.toLocaleString('ko-KR',{minimumFractionDigits:digits,maximumFractionDigits:digits}):num(Math.round(value))};
