stagePlayerImport = function stagePlayerImport(raw){
 if(testSession||dungeonRun||forgeBusy||resultAction)throw Error('진행 중인 도전·제작·소환 또는 테스트가 끝난 뒤 가져오세요');
 const data=validateImport(raw);
 pendingPlayerImport={data,owner:s,localId:s.localId,busy:false};
 return data;
};
previewImportFile = async function previewImportFile(e){
 const file=e.target.files[0],owner=s;
 if(!file)return;
 try{
  if(file.size>1500000)throw Error('저장 파일이 너무 큽니다');
  const raw=JSON.parse(await file.text());
  if(s!==owner)return;
  stagePlayerImport(raw);openMenu('playerImport');
 }catch(error){notice(error.message||'저장 파일을 읽을 수 없습니다')}
 finally{e.target.value=''}
};
cancelPlayerImport = function cancelPlayerImport(){if(pendingPlayerImport?.busy)return;pendingPlayerImport=null;closeMenu()};
confirmPlayerImport = function confirmPlayerImport(){
 const choice=pendingPlayerImport;
 if(!choice||choice.busy||testSession||choice.owner!==s||choice.localId!==s.localId||dungeonRun||forgeBusy||resultAction)return false;
 choice.busy=true;if(view==='playerImport')render();
 return saveGuard.importLocal(JSON.stringify(choice.data)).then(restored=>{
  if(restored&&choice===pendingPlayerImport){pendingPlayerImport=null;if(view==='playerImport')closeMenu()}
  return restored;
 }).catch(error=>{notice(error.message||'저장 기록을 불러오지 못했습니다');return false})
 .finally(()=>{choice.busy=false;if(choice===pendingPlayerImport&&view==='playerImport')render()});
};
