playerJourneyPopup = function playerJourneyPopup(){const j=journeyState();if(j.status==='done')return `<section class="journey-card"><h3>첫 모험 준비 완료</h3><p>STAGE 10·30에서 스킬 슬롯이 열립니다. 메인 퀘스트를 따라 진행하세요.</p><button class="gold-button" onclick="navigate('home')">모험 계속하기</button><button class="muted-button" onclick="startPlayerJourney()">처음부터 다시 보기</button></section>`;const step=JOURNEY_STEPS[j.step]||JOURNEY_STEPS[0];return `<section class="journey-card"><small>첫 모험 안내 · ${j.step+1} / ${JOURNEY_STEPS.length}</small><h3>${step.title}</h3><p>${step.text}</p><small>${step.target}</small><div class="action-row">${button(step.done()?(j.step===5?'안내 마치기':'다음 단계'):'완료 후 다음 단계','nextPlayerJourney()',!step.done())}<button class="gold-button purple" onclick="goPlayerJourney()">해보러 가기</button></div><button class="muted-button" onclick="pausePlayerJourney()">나중에 이어하기</button><button class="muted-button" onclick="skipPlayerJourney()">건너뛰기</button></section><p class="small">완료는 자동 반영됩니다. 멈춘 안내는 설정에서 이어갈 수 있습니다.</p>`};
playerPassState = function playerPassState(state=s){
 let p=state.playerPass;
 if(!p||p.version!==1)p=state.playerPass={version:1};
 for(const [kind,key] of [['daily',today()],['weekly',weekKey()]]){
  if(p[kind]?.key!==key)p[kind]={key};
  p[kind].count=recordMap(p[kind].count);
  p[kind].claimed=recordMap(p[kind].claimed);
 }
 return p;
};
recordPlayerActivity = function recordPlayerActivity(key,n=1,state=s){
 if(!Number.isFinite(n)||n<=0)return;
 trackOrderEvent(key,n,state);
 const p=playerPassState(state);
 for(const kind of ['daily','weekly']){
  if(SEASON_MISSIONS[kind].some(([metric,,,,,base])=>!base&&metric===key))
   p[kind].count[key]=bounded(p[kind].count[key])+n;
 }
};
seasonMissionRows = function seasonMissionRows(kind){
 const activities=playerPassState()[kind];
 return SEASON_MISSIONS[kind].map(([key,name,goal,points,target,base])=>{
  const ledger=base?s[kind]:activities;
  const value=bounded((base?ledger:ledger.count)[key]),claimed=!!ledger.claimed[key];
  return {key,name,goal,points,target,coins:kind==='daily'&&base?5:0,value,claimed,ledger,priority:missionPriority(value,goal,claimed)};
 }).sort((a,b)=>a.priority-b.priority);
};
