returnToHavenShop = function returnToHavenShop(){const i=popupStack.map(p=>p.view).lastIndexOf('havenShop');if(i<0)return false;popupStack.splice(i+1);closeMenu();return true};
playerPortraitStyle = function playerPortraitStyle(id,rank){const key=id+'-'+(rank===6?'event':rank),clean=CLEAN_DISPLAY_PORTRAITS[key],size=clean?[clean.height,clean.span]:DISPLAY_SILHOUETTES[id][rank];return `--display-height:${size[0]};--display-span:${Math.max(.7,size[1])};--display-body:${id==='shadow'?'170px':'200px'};`+(clean?`--class-atlas:url('./assets/portraits/${key}.webp?v=${id==='archer'?142:134}');--atlas-size:100% 100%;--rank-y:0%;--sprite-scale:1;--foot-x:${-clean.x*100}%;--foot-y:${-clean.y*100}%;`:'')};
