growthScreen=function(){
 const v=playerCombatStats(),offers=STAT_NAMES.map((_,i)=>growthOffers(i));
 const available=GROWTH_BATCHES.filter(n=>offers.some(row=>row.has(n)));
 const selected=available.filter(n=>n<=s.growthBatch).pop();
 return `<section class="player-stat-overview" aria-label="현재 전투 능력">${statReading('공격력',num(v.attack))}${statReading('모험 평타 초당 피해',playerMetric(v.dps,1))}${statReading('최대 체력',num(v.hp))}</section><div class="stat-chips">${statReading('치명타 확률',(v.crit*100).toFixed(2)+'%')}${statReading('공격속도',v.speed.toFixed(2)+'×')}${statReading('골드 배율',v.gold.toFixed(2)+'×')}</div>${head('기본 능력 강화')}<div class="batch-controls">${GROWTH_BATCHES.map(n=>`<button class="${selected===n?'active':''}" aria-pressed="${selected===n}" ${available.includes(n)?'':'disabled'} onclick="growthBatch(${n})">×${n}</button>`).join('')}</div>${STAT_NAMES.map((name,i)=>{const {p,before,after}=growthCombatPreview(i,undefined,offers[i]),key=i===0?'attack':i===5?'penetration':i===3?'hp':i===2?'gold':'dps',label=i===0?'최종 공격력':i===5?'최종 방어 관통력':i===3?'최대 체력':i===2?'골드 배율':'기대 피해 / 초',digits=i===5||i===2?2:i===3||i===0?0:1;return `<article class="growth-row growth-comparison"><span class="growth-stat-icon">${growthStatIcon(i)}</span><div><b>${termButton(({'체력':'최대 체력','골드 획득':'골드 배율'})[name]||name,name+' Lv.'+(s.stats[i]??1))}</b><span class="growth-values">${i===6?criticalDamageText(before.critDamage):growthPercent(i,p.before)} → <strong>${i===6?criticalDamageText(after.critDamage):growthPercent(i,p.after)}</strong></span><small>${growthStepHint(i)+(p.count>1?' · Lv.'+p.level:'')}${i===4?' · 확률 가산':''}</small></div>${button(p.capped?'최대 효과':p.count?p.count+'회 강화<small>'+num(p.cost)+' 골드</small>':'골드 부족',`upgrade(${i},${p.count},${p.cost})`,!p.count,false,i===0?'growth':'')}<div class="growth-final"><span>${label}</span><b>${playerMetric(before[key],digits)} → ${playerMetric(after[key],digits)}${i===2?'×':i===5?'%':''}</b></div></article>`}).join('')}<details class="balance-help"><summary>성장 보너스 안내</summary><p>선택한 배수 안에서 가능한 50·10·1회 중 가장 큰 횟수만큼 강화합니다.</p><p>전투력은 모험 평타·장착 스킬의 예상 초당 피해에 생존 보너스(최대 5%)를 더합니다.</p><p>전투 능력은 Lv.25부터 강화 폭이 커집니다. 골드는 회당 +1%.</p><p>모험 평타 기본 피해는 Lv.50에 공격력의 4배, Lv.100에 6배입니다.</p></details>`};


