// A stage boss has 30 seconds of combat time. The wall deadline survives suspension and reload.
const STAGE_BOSS_LIMIT_MS=30000;
let stageBossResolving=false;





const paintBattleBeforeBossClock=paintBattle;
paintBattle=function(){paintBattleBeforeBossClock();stageBossTick()};
const retreatBeforeBossClock=retreatBoss;
retreatBoss=function(reason='defeated'){
 if(stageBossResolving||!stageBossActive())return false;
 stageBossResolving=true;
 const defeated=s.stage;
 s.campaignCleared=Math.max(s.campaignCleared||0,defeated-1);
 tacticsState().encounter=null;
 s.stageBossAttempt=null;
 try{retreatBeforeBossClock()}finally{stageBossResolving=false}
 s.lastStageBossFailure={stage:defeated,reason,at:Date.now()};save();
 const message=reason==='timeout'?'제한시간 30초 초과':'캐릭터 체력 소진';
 banner('보스 도전 실패 · '+message);
 offerDefeatHelp(defeated,true);
 paintStageBossHUD();return true;
};
const retryBeforeBossClock=retryBoss;
retryBoss=function(){
 if(dungeonRun||!s.classId)return false;
 if(stageBossActive()){notice('이미 보스에 도전 중입니다');return false}
 if(!canChallengeStageBoss())return false;
 s.stageKills=0;tacticsState().encounter=null;
 s.maxStage=Math.max(s.maxStage,s.stage+1);s.stageBossAttempt=null;
 retryBeforeBossClock();stageBossTick();return true;
};
