 if(now-forgeLockNoticeAt>1500){forgeLockNoticeAt=now;notice(weaponRitual.kind==='weaponEnhance'?'강화 결과가 나올 때까지 기다려 주세요':'속성 부여가 끝날 때까지 기다려 주세요')}
