   p.age+=dt;p.vy+=p.gravity*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.a+=p.spin*dt;
   const opacity=Math.max(0,1-p.age/p.life);ctx.save();ctx.globalAlpha=opacity;
