// game script 97
trialCombatPaused = function trialCombatPaused(run=dungeonRun){
 return run?.mode==='trial'&&(run.choosing===true||run.exitPending===true||!!run.floorTransition||!!run.endReason);
};
normalizeDailyTrialState = function normalizeDailyTrialState(state,week){
 week??=saveGuard.usesServer()?(trialCalendar()?.weekKey||state.economyClaims?.trial?.weekKey||state.trial?.weekKey||''):weekKey();
 state.daily.trialRuns=Math.min(TRIAL_ENTRY_LIMIT,Math.floor(bounded(state.daily.trialRuns)));
 const previous=state.trial?.weekKey===week?state.trial:null;
 state.trial={weekKey:week,bestScore:Math.floor(bounded(previous?.bestScore)),bestFloors:Math.floor(bounded(previous?.bestFloors))};
};
startDailyTrial = async function startDailyTrial(){
 if(dungeonAdmissionPending||dungeonRun||!s.classId||!guardFeature('trial'))return false;
 if(!saveGuard.usesServer())resetDay();
 const owner=s;
 dungeonAdmissionPending=true;
 try{
  const reservation=await reserveDailyTrial();
  if(!reservation||owner!==s||dungeonRun)return false;
  const hp=trialBossHp(1);
  const run={...reservation,mode:'trial',n:1,bosses:0,floors:0,hp,maxHp:hp,time:TRIAL_TIME,damage:0,
   choosing:false,exitPending:false,selection:0,options:[],buffs:{},picks:[],weakUntil:[]};
  challengeResult=null;dungeonRun=run;
  cancelCombatAnimation();combatTimer=0;heroCurrentHp=health();
  navigate('home');paint();openTrialChoice(run);return true;
 }finally{dungeonAdmissionPending=false}
};
openTrialChoice = function openTrialChoice(run){
 run.options=trialBuffOptions(run.dayKey,run.selection);
 run.choosing=true;beginTrialCombatPause(run);openMenu('trialChoice');
};
trialFloorHealth = function trialFloorHealth(run){
 return Math.max(1,trialBossHp(run.n)*(1-TRIAL_BUFFS.weakHp.amount*run.weakUntil.length));
};
chooseTrialBuff = function chooseTrialBuff(key){
 const run=dungeonRun;
 if(!run?.choosing||run.mode!=='trial'||run.exitPending||!run.options.includes(key))return false;
 run.buffs[key]=(run.buffs[key]||0)+1;run.picks.push(key);
 if(key==='time')run.time+=TRIAL_BUFFS.time.amount;
 if(key==='weakHp'){
  run.weakUntil.push(run.n+2);
  run.hp=run.maxHp=trialFloorHealth(run);
 }
 run.options=[];run.selection++;run.choosing=false;endTrialCombatPause(run);
 if(view==='trialChoice')dismissPopup();
 paintBattle();return true;
};
showTrialFloorStatus = function showTrialFloorStatus(text){
 const status=$('trialFloorStatus');
 status.textContent=text;status.hidden=false;
};
clearTrialFloorStatus = function clearTrialFloorStatus(){
 const status=$('trialFloorStatus');
 status.hidden=true;status.textContent='';
 delete $('battle').dataset.trialDeparture;
};
nextTrialFloor = function nextTrialFloor(run){
 if(run!==dungeonRun||run.mode!=='trial'||trialCombatPaused(run)||run.hp>0)return false;
 run.hp=0;
 run.floorTransition={remaining:TRIAL_FLOOR_TRANSITION_SECONDS};
 beginTrialCombatPause(run);
 const enemy=encounterFor(s.stage,run),anchor=adventureFx.deathAnchor($('mobActor'));
 adventureFx.defeat(anchor,enemy.region,weaponAudio.surface(enemy.region,3),true);
 $('battle').dataset.trialDeparture=anchor?.still?'dissolve':'fall';
 showTrialFloorStatus(num(run.n)+'층 돌파 · '+num(run.n+1)+'층으로 이동');
 paintBattle();return true;
};
tickTrialFloorTransition = function tickTrialFloorTransition(run,dt){
 if(!run?.floorTransition||run!==dungeonRun)return false;
 if(run.exitPending||run.endReason)return true;
 run.floorTransition.remaining-=dt;
 if(run.floorTransition.remaining>0.000001)return true;

 // Retire the old target's remaining contacts before assigning the next boss.
 cancelCombatAnimation();
 delete run.floorTransition;
 endTrialCombatPause(run);
 run.floors++;run.bosses=run.floors;run.n=run.floors+1;
 run.weakUntil=run.weakUntil.filter(last=>last>=run.n);
 run.hp=run.maxHp=trialFloorHealth(run);
 const max=health();heroCurrentHp=Math.min(max,heroCurrentHp+max*.15);
 combatTimer=0;
 clearTrialFloorStatus();paintBattle();
 if(run.floors%TRIAL_CHOICE_INTERVAL===0)openTrialChoice(run);
 return true;
};
cancelTrialExit = function cancelTrialExit(){
 const run=dungeonRun;
 if(run?.mode!=='trial'||dungeonExitTarget!==run||!run.exitPending)return false;
 dungeonExitTarget=null;run.exitPending=false;
 dismissPopup();
 if(run.choosing)openMenu('trialChoice');else endTrialCombatPause(run);
 return true;
};
finishDailyTrial = async function finishDailyTrial(run,reason){
 if(run!==dungeonRun||run.mode!=='trial'||run.endReason)return false;
 const owner=s,abandoned=!!run.abandoned,score=abandoned?0:trialScore(run);
 const paused=trialCombatPaused(run);
 run.exitPending=false;run.choosing=false;run.options=[];dungeonExitTarget=null;
 if(paused)endTrialCombatPause(run);
 run.endReason=reason;
 const result={...run,win:!abandoned,score,bestScore:s.trial.bestScore,bestFloors:s.trial.bestFloors,rewards:{},settling:true};
 challengeResult=result;
 const showResult=()=>{
  if(dungeonRun!==run||owner!==s)return;
  clearTrialFloorStatus();
  dungeonRun=null;cancelCombatAnimation();heroCurrentHp=health();combatTimer=0;
  dismissPopup();paint();openMenu('challengeResult');
 };
 if(reason==='defeat'){
  paintHeroHealth();
  showTrialFloorStatus(num(run.n)+'층 · 전투 패배');
  setTimeout(showResult,1100);
 }else showResult();
 const settled=await settleDailyTrial(run,score);
 if(owner!==s)return false;
 result.settling=false;result.settlementFailed=!settled;
 if(settled){
  result.rewards=settled.rewards;
  result.ranked=settled.ranked;
  result.bestScore=settled.bestScore??s.trial.bestScore;
  result.bestFloors=settled.bestFloors??s.trial.bestFloors;
 }
 if(challengeResult===result&&view==='challengeResult')render();
 return !!settled;
};
'use strict';

const TRIAL_FLOOR_TRANSITION_SECONDS=1.2;














