// game script 98
trialRankButton = function trialRankButton(){
 return '<button type="button" class="muted-button trial-rank-link" data-feature="trial" onclick="openMenu(\'trialRanking\',\'current\')">주간 순위</button>';
};
onTrialCalendarChanged = function onTrialCalendarChanged(){trialRankingUI.redraw()};
invalidateTrialRanking = function invalidateTrialRanking(){trialRankingUI.invalidate()};
'use strict';



const trialRankingUI=(()=>{
 let owner=null,week='',boards=new Map(),previous=null,lastReceipt=null,claiming=false;
 let calendarTask=null,calendarRetryAt=0,showingFor='',refreshQueued=false,displayDay=null;
 const live=()=>saveGuard.usesServer()&&!testSession&&!s?.testOnly;
 const onList=()=>activeScreen==='dungeon'&&screenTab==='content'&&!view;
 const onEntry=()=>onList()||view==='dungeonGuide'&&tab==='trial';
 const onTrial=()=>onEntry()||view==='trialRanking'||view==='trialWeekReward';
 function clear(newWeek){
  owner=s;week=newWeek;boards=new Map();previous=null;lastReceipt=null;claiming=false;showingFor='';
 }
 function ownerWeek(){
  if(owner!==s){clear('');calendarTask=null;calendarRetryAt=0;displayDay=null}
  const calendar=trialCalendar();
  if(calendar&&calendar.weekKey!==week)clear(calendar.weekKey);
  return calendar;
 }
 function redraw(){
  if(refreshQueued||!onTrial()||document.hidden)return;
  refreshQueued=true;Promise.resolve().then(()=>{
   refreshQueued=false;if(document.hidden)return;
   if(onList())renderScreen();else if(onTrial())render();
  });
 }
 function loadCalendar(force=false){
  if(!live()||calendarTask||!force&&Date.now()<calendarRetryAt)return;
  const player=s;
  calendarTask=refreshTrialCalendar(force).then(info=>{
   if(owner!==player||s!==player)return;
   calendarRetryAt=info?0:Date.now()+10000;ownerWeek();
  }).catch(()=>{if(owner===player)calendarRetryAt=Date.now()+10000})
   .finally(()=>{if(owner===player){calendarTask=null;redraw()}});
 }
 function calendarStatus(){
  return calendarRetryAt>Date.now()?'<div class="trial-rank-status" role="status">오늘의 탑 정보를 불러오지 못했습니다. <button class="muted-button" onclick="trialRankingUI.retry()">다시 확인</button></div>':'<p class="trial-rank-status" role="status">서버에서 오늘의 약점을 확인하고 있습니다.</p>';
 }
 function offer(){
  const info=trialCalendar(),prize=previous;
  if(!info||week!==info.weekKey||!prize?.eligible||prize.claimed||s.trialRankPromptWeek===prize.weekKey||
     showingFor===prize.weekKey||dungeonRun||!onEntry()||document.hidden)return;
  showingFor=prize.weekKey;
  Promise.resolve().then(()=>{
   if(previous!==prize||!live()||!onEntry()||dungeonRun||!featureOpen('trial')||trialCalendar()?.weekKey!==week){showingFor='';return}
   s.trialRankPromptWeek=prize.weekKey;save();openMenu('trialWeekReward',prize.weekKey);
  });
 }
 function loadBoard(key,force=false){
  if(!key||!live())return;
  const item=boards.get(key);
  if(item?.loading||!force&&item?.until>Date.now())return;
  const player=s,period=week,next=item||{};
  next.loading=true;boards.set(key,next);
  Promise.resolve(fetchTrialRanking(key)).then(data=>{
   if(!live()||s!==player||owner!==player||week!==period||trialCalendar()?.weekKey!==period||boards.get(key)!==next)return;
   if(data?.weekKey===key&&Array.isArray(data.top)){
    next.data=data;next.failed=false;next.until=Date.now()+30000;
    previous=data.previous||null;
    if(lastReceipt&&previous&&lastReceipt.weekKey===previous.weekKey)previous={...previous,eligible:false,claimed:true};
    offer();
   }else{next.failed=true;next.until=Date.now()+10000}
  }).catch(()=>{next.failed=true;next.until=Date.now()+10000})
   .finally(()=>{next.loading=false;if(s===player&&week===period)redraw()});
 }
 function previousWeek(key){return new Date(Date.parse(key+'T00:00:00Z')-7*86400000).toISOString().slice(0,10)}
 function selectedWeek(){return tab==='previous'?previousWeek(week):week}
 function visit(){
  if(!onEntry()||!live()||!featureOpen('trial')||dungeonRun)return;
  const info=ownerWeek();if(!info){loadCalendar();return}
  if(!boards.get(info.weekKey)?.data)loadBoard(info.weekKey);
  offer();
 }
 function tick(){
  if(!onTrial()||!live()||!featureOpen('trial')||document.hidden)return;
  const info=ownerWeek(),currentDay=info?.dayKey||null;
  if(displayDay!==currentDay){displayDay=currentDay;redraw()}
  if(!info){loadCalendar();return}
  if(onEntry())visit();else if(view==='trialRanking')loadBoard(selectedWeek());
 }
 function retry(){
  const info=ownerWeek();
  if(!info){calendarRetryAt=0;loadCalendar(true)}else if(live())loadBoard(view==='trialRanking'?selectedWeek():week,true);
  redraw();
 }
 function select(period){
  if(view!=='trialRanking'||!['current','previous'].includes(period))return;
  tab=period;render();$('content').scrollTop=0;
 }
 function previousButton(){
  return previous?.eligible&&!previous.claimed?'<button type="button" class="gold-button trial-rank-link" onclick="trialRankingUI.openPrevious()">지난주 순위 보상</button>':'';
 }
 function openPrevious(){
  const info=ownerWeek();
  if(live()&&info&&previous?.eligible&&!previous.claimed&&previous.weekKey===previousWeek(info.weekKey))openMenu('trialWeekReward',previous.weekKey);
 }
 function board(){
  if(!live())return '<p class="trial-rank-status">테스트 플레이는 주간 순위에 등록되지 않습니다.</p>';
  const info=ownerWeek();if(!info){loadCalendar();return calendarStatus()}
  const key=selectedWeek();loadBoard(key);
  const item=boards.get(key),data=item?.data;
  const tabs='<nav class="rank-tabs trial-rank-tabs" aria-label="주간 순위 기간">'+['current','previous'].map((id,i)=>
   '<button type="button" aria-pressed="'+(key===(i?previousWeek(week):week))+'" onclick="trialRankingUI.select(\''+id+'\')">'+(i?'지난주':'이번 주')+'</button>').join('')+'</nav>';
  const error=item?.failed?'<p class="trial-rank-status" role="status">순위를 갱신하지 못했습니다. <button class="muted-button" onclick="trialRankingUI.retry()">다시 확인</button></p>':'';
  if(!data)return tabs+(error||'<p role="status">주간 순위를 불러오는 중입니다.</p>');
  return tabs+error+rankBoard.trialGallery(data,key+' 시작 · 참가 '+num(data.participantCount)+'명',previousButton());
 }
 function reward(){
  if(!live())return '<p>테스트 플레이에서는 주간 순위 보상을 받을 수 없습니다.</p>';
  const info=ownerWeek();if(!info){loadCalendar();return calendarStatus()}
  const prize=lastReceipt?.weekKey===tab?lastReceipt:previous;
  if(!prize||prize.weekKey!==tab||tab!==previousWeek(info.weekKey))return '<p>수령할 지난주 보상이 없습니다.</p>';
  const claimed=!!(prize.claimed||lastReceipt?.weekKey===prize.weekKey);
  return `<section class="trial-week-prize"><div class="trial-result-heading">${art('tower')}<div><small>${safeText(prize.weekKey)} 시작</small><h3>지난주 ${num(prize.rank)}위</h3></div></div>
   ${rewardsHTML(prize.rewards||{})}${prize.title?'<p class="trial-title-prize">칭호 <b>'+safeText(prize.title)+'</b></p>':''}
   ${claimed?'<p role="status">보상을 받았습니다.</p><button type="button" class="gold-button profile-wide" onclick="closeMenu()">확인</button>':
    '<button type="button" class="gold-button profile-wide" onclick="trialRankingUI.claim()" '+transactionAttrs(claiming||!prize.eligible)+'>'+(claiming?'지급 확인 중':'보상 받기')+'</button>'}</section>`;
 }
 async function claim(){
  const player=s,info=ownerWeek(),prize=previous;
  if(!live()||claiming||!saveGuard.canTransact()||!info||view!=='trialWeekReward'||!prize?.eligible||prize.claimed||prize.weekKey!==tab||tab!==previousWeek(info.weekKey))return false;
  claiming=true;render();
  try{
   const receipt=await claimTrialWeek(prize.weekKey);
   if(s!==player||!live()||trialCalendar()?.weekKey!==info.weekKey)return false;
   if(!receipt){loadBoard(info.weekKey,true);return false}
   lastReceipt={...receipt,claimed:true};previous={...prize,eligible:false,claimed:true};return true;
  }finally{if(s===player){claiming=false;redraw()}}
 }
 function invalidate(){
  for(const item of boards.values())item.until=0;
  if(view==='trialRanking')redraw();
 }
 return {visit,tick,calendarStatus,retry,select,board,reward,openPrevious,claim,redraw,invalidate};
})();


EXTRA_POPUPS.trialRanking=['오늘의 탑 주간 순위',trialRankingUI.board];
EXTRA_POPUPS.trialWeekReward=['지난주 순위 보상',trialRankingUI.reward];

